} from "../api/client";
import StatusBadge from "../components/ui/StatusBadge";
import { ZvmActionButton, ZvmCard, ZvmViewShell } from "../components/zionvm";

function HaKpi({
  label,
  value,
  icon: Icon,
  accent,
  hint,
}: {
  label: string;
  value: ReactNode;
  icon: LucideIcon;
  accent?: "primary" | "ok" | "info" | "warn";
  hint?: string;
}) {
  return (
    <article className={`zvm-ds-kpi sa-corp-card zvm-ds-kpi-${accent ?? "primary"}`}>
      <span className="sa-corp-card-fx" aria-hidden>
        <span className="sa-corp-card-fx-grid" />
        <span className="sa-corp-card-fx-scan" />
      </span>
      <div className="zvm-ds-kpi-inner">
        <span className="zvm-ds-kpi-icon" aria-hidden>
          <Icon size={18} strokeWidth={2.1} />
        </span>
        <div className="zvm-ds-kpi-copy">
          <span className="zvm-ds-kpi-label">{label}</span>
          <strong className="zvm-ds-kpi-value">{value}</strong>
          {hint ? <small className="zvm-ds-kpi-hint">{hint}</small> : null}
        </div>
      </div>
    </article>
  );
}

type Props = {
  title?: string;
  haDashboard: ZionvmHaDashboard | null;
  haGroups: ZionvmHaGroup[];
  datacenterId?: number;
  defaultClusterId?: number;
  busy?: boolean;
  error?: string | null;
  onBusy: (v: boolean) => void;
  onError: (msg: string | null) => void;
  onRefresh: () => void | Promise<void>;
  onAfterMutate?: () => void | Promise<void>;
  zvmApiError: (e: unknown, fallback?: string) => string;
};

export default function ZionvmHaPanel({
  title = "High Availability",
  haDashboard,
  haGroups,
  datacenterId,
  defaultClusterId = 1,
  busy,
  error,
  onBusy,
  onError,
  onRefresh,
  onAfterMutate,
  zvmApiError,
}: Props) {
  const [groupForm, setGroupForm] = useState({
    cluster_id: defaultClusterId,
    name: "prod-failover",
    node_priority: "",
    description: "",
  });
  const [policyForm, setPolicyForm] = useState({
    vm_id: "" as number | "",
    ha_group_id: "" as number | "",
    enabled: true,
    mode: "started",
  });
  const [failoverForm, setFailoverForm] = useState({
    vm_id: "" as number | "",
    target_node_id: "" as number | "",
  });
  const [evalClusterId, setEvalClusterId] = useState(defaultClusterId);
  const [evalResult, setEvalResult] = useState<{ ok: boolean; stale_nodes: number[] } | null>(null);
  const [showGroupForm, setShowGroupForm] = useState(false);

  const run = async (fn: () => Promise<unknown>) => {
    onBusy(true);
    onError(null);
    try {
      await fn();
      await onAfterMutate?.();
      await onRefresh();
    } catch (e) {
      onError(zvmApiError(e));
    } finally {
      onBusy(false);
    }
  };

  const recent = haDashboard?.recent_failovers ?? [];

  return (
    <ZvmViewShell
      title={title}
      icon={Shield}
      busy={busy}
      error={error}
      onRefresh={() => void onRefresh()}
      toolbar={
        <>
          <ZvmActionButton
            variant={showGroupForm ? "accent" : "primary"}
            onClick={() => setShowGroupForm((v) => !v)}
          >
            {showGroupForm ? "Fechar form" : "Novo group"}
          </ZvmActionButton>
          <ZvmActionButton
            icon={RefreshCw}
            disabled={busy}
            onClick={() => void onRefresh()}
          >
            Refresh
          </ZvmActionButton>
        </>
      }
    >
      <div className="zvm-ds-stack zvm-ds-corp-panel zvm-ds-ha-panel">
        <div className="zvm-ds-sn-kicker">
          <span className="sa-corp-card-badge">Sprint 9</span>
          <p>
            Resource groups · policy por VM · failover · recovery. Evaluate deteta nodes stale no
            cluster.
          </p>
        </div>

        <div className="zvm-ds-kpi-grid">
          <HaKpi
            label="Groups"
            value={haDashboard?.groups ?? "—"}
            icon={Users}
            hint={datacenterId != null ? `DC #${datacenterId}` : undefined}
          />
          <HaKpi
            label="HA enabled"
            value={haDashboard?.policies_enabled ?? "—"}
            icon={Shield}
            accent="ok"
          />
          <HaKpi
            label="Recovering"
            value={haDashboard?.recovering ?? "—"}
            icon={HeartPulse}
            accent="info"
          />
          <HaKpi
            label="Failed"
            value={haDashboard?.failed ?? "—"}
            icon={AlertTriangle}
            accent={haDashboard && haDashboard.failed > 0 ? "warn" : "primary"}
          />
        </div>

        {showGroupForm ? (
          <ZvmCard title="Novo resource group" className="zvm-ds-sn-form-card">
            <form
              className="zvm-ds-inline-form"
              onSubmit={(e) => {
                e.preventDefault();
                void run(async () => {
                  await createZionvmHaGroup({
                    cluster_id: Number(groupForm.cluster_id),
                    name: groupForm.name.trim(),
                    description: groupForm.description.trim() || undefined,
                    node_priority: groupForm.node_priority
                      .split(",")
                      .map((x) => Number(x.trim()))
                      .filter((n) => !Number.isNaN(n) && n > 0),
                  });
                  setShowGroupForm(false);
                });
              }}
            >
              <label className="zvm-ds-form-field zvm-ds-form-field-narrow">
                <span className="zvm-ds-form-label">Cluster ID</span>
                <input
                  type="number"
                  value={groupForm.cluster_id}
                  onChange={(e) =>
                    setGroupForm((f) => ({ ...f, cluster_id: Number(e.target.value) }))
                  }
                />
              </label>
              <label className="zvm-ds-form-field zvm-ds-form-field-md">
                <span className="zvm-ds-form-label">Group name</span>
                <input
                  value={groupForm.name}
                  onChange={(e) => setGroupForm((f) => ({ ...f, name: e.target.value }))}
                  placeholder="prod-failover"
                />
              </label>
              <label className="zvm-ds-form-field zvm-ds-form-field-grow">
                <span className="zvm-ds-form-label">Node priority (ids)</span>
                <input
                  value={groupForm.node_priority}
                  onChange={(e) => setGroupForm((f) => ({ ...f, node_priority: e.target.value }))}
                  placeholder="1, 2, 3"
                />


