candidates = []

def walk(o, depth=0):
    if depth > 20:
        return
    if isinstance(o, dict):
        # tool_use Write
        name = o.get("name") or o.get("toolName")
        inp = o.get("input") or o.get("arguments") or {}
        if isinstance(inp, str):
            try:
                inp = json.loads(inp)
            except Exception:
                inp = {}
        if name in ("Write", "write") and isinstance(inp, dict):
            path = str(inp.get("path") or "")
            contents = inp.get("contents")
            if contents and "ZvmNumberField" in path.replace("\\", "/"):
                yield path, contents
            # also contents that define the component file
            if contents and path.endswith("ZvmNumberField.tsx"):
                yield path, contents
        for v in o.values():
            yield from walk(v, depth + 1)
    elif isinstance(o, list):
        for v in o:
            yield from walk(v, depth + 1)

