"""mTLS / certificado cliente para rotas agent (Sprint 15.7)."""

from __future__ import annotations

import hashlib

from fastapi import HTTPException, Request

from app.config import settings


def _client_cert_sha256(request: Request) -> str | None:
    pin = (request.headers.get("X-ZionVM-Agent-Cert-SHA256") or "").strip().lower()
    if pin:
        return pin.replace(":", "")
    peercert = request.scope.get("peercert")
    if not peercert:
        return None
    try:
        import ssl

        der = ssl.DER_cert_to_PEM_cert(peercert)  # type: ignore[arg-type]
        if isinstance(der, str):
            body = der.encode("utf-8")
        else:
            return None
    except Exception:
        return None
    return hashlib.sha256(body).hexdigest()


def assert_agent_mtls(request: Request) -> None:
    """Exige verificação TLS no edge ou header de pin quando activado."""
    if not getattr(settings, "zionvm_agent_mtls_required", False):
        return

    verify = (request.headers.get("X-SSL-Client-Verify") or "").upper()
    if verify == "SUCCESS":
        return

    expected_pin = (getattr(settings, "zionvm_agent_mtls_cert_sha256", "") or "").strip().lower()
    if expected_pin:
        got = _client_cert_sha256(request)
        if got and got == expected_pin.replace(":", ""):
            return

    raise HTTPException(
        status_code=403,
        detail="Agent mTLS obrigatório (nginx client cert ou X-ZionVM-Agent-Cert-SHA256)",
    )

"""Hypervisor driver abstraction — Sprint 14 (stub vs agent/libvirt)."""

from __future__ import annotations

from abc import ABC, abstractmethod

from sqlalchemy.orm import Session

from app.models.zionvm import ZionvmTask


class HypervisorDriver(ABC):
    @abstractmethod
    def apply_vm_action(self, session: Session, task: ZionvmTask) -> dict:
        """Execute VM lifecycle action and return result payload."""


class StubHypervisorDriver(HypervisorDriver):
    def apply_vm_action(self, session: Session, task: ZionvmTask) -> dict:
        from app.services.zionvm_service import apply_vm_action_stub

        return apply_vm_action_stub(session, task)


class AgentHypervisorDriver(HypervisorDriver):
    def apply_vm_action(self, session: Session, task: ZionvmTask) -> dict:
        from app.services.zionvm_agent_jobs import AGENT_VM_ACTIONS, apply_vm_action_via_agent
        from app.services.zionvm_service import apply_vm_action_stub

        if task.task_type in AGENT_VM_ACTIONS:
            return apply_vm_action_via_agent(session, task)
        return apply_vm_action_stub(session, task)


def get_hypervisor_driver() -> HypervisorDriver:
    from app.config import settings

    driver = (getattr(settings, "zionvm_hypervisor_driver", None) or "stub").strip().lower()
    if driver == "agent":
        return AgentHypervisorDriver()
    return StubHypervisorDriver()

