function fmtBytes(n: number) {
  if (!Number.isFinite(n) || n < 0) return "—";
  if (n < 1024) return `${n} B`;
  if (n < 1024 ** 2) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 ** 3) return `${(n / 1024 ** 2).toFixed(1)} MB`;
  return `${(n / 1024 ** 3).toFixed(2)} GB`;
}

function fmtWhen(v: unknown) {
  if (!v) return "—";
  return String(v).replace("T", " ").slice(0, 19);
}

function jobStatusClass(status: string) {
  const s = status.toLowerCase();
  if (s === "success") return "sa-bk-zvm-pill-ok";
  if (s === "failed") return "sa-bk-zvm-pill-bad";
  if (s === "running") return "sa-bk-zvm-pill-run";
  return "sa-bk-zvm-pill-muted";
}

function healthRisk(success24: number, failed24: number): string {
  const t = success24 + failed24;
  if (t === 0) return "unknown";
  const pct = success24 / t;
  if (pct >= 0.95) return "low";
  if (pct >= 0.75) return "medium";
  if (pct >= 0.5) return "high";
  return "critical";
}

function riskClass(risk: string) {
  if (risk === "critical" || risk === "high") return "sa-bk-risk-bad";
  if (risk === "medium") return "sa-bk-risk-mid";
  if (risk === "low") return "sa-bk-risk-ok";
  return "";
}

