#!/usr/bin/env python3
"""Extract fetchZionvmOpsRepository definitions from transcripts if any."""
import json
import re
from pathlib import Path

tbase = Path(
    r"C:\Users\aosebastiao\.cursor\projects\c-Users-aosebastiao-Desktop-SentinelAI\agent-transcripts"
)
needle = "fetchZionvmOpsRepository"
out = Path(r"c:\Users\aosebastiao\Desktop\SentinelAI\_recover_out")

snippets = []
for tp in [
    tbase
    / "e5492ecc-99c4-4a47-9d7c-0ff1456722bf"
    / "e5492ecc-99c4-4a47-9d7c-0ff1456722bf.jsonl",
    tbase
    / "a8f9e08f-eaaa-4389-a28f-6c3ffb324b79"
    / "a8f9e08f-eaaa-4389-a28f-6c3ffb324b79.jsonl",
]:
    with open(tp, "r", encoding="utf-8", errors="replace") as f:
        for i, line in enumerate(f, 1):
            if needle not in line:
                continue
            # try extract from tool args new_string/contents
            try:
                obj = json.loads(line)
            except Exception:
                continue

            def walk(o):
                if isinstance(o, dict):
                    for k, v in o.items():
                        if k in (
                            "contents",
                            "content",
                            "new_string",
                            "newString",
                            "old_string",
                            "oldString",
                        ) and isinstance(v, str) and needle in v:
                            # extract function block
                            m = re.search(
                                rf"export async function {needle}\s*\([^)]*\)[^{{]*\{{(?:[^{{}}]|{{[^{{}}]*}})*\}}",
                                v,
                                re.S,
                            )
                            if not m:
                                # looser
                                idx = v.find(needle)
                                snippets.append(
                                    {
                                        "src": f"{tp.name}:L{i}",
                                        "key": k,
                                        "excerpt": v[max(0, idx - 80) : idx + 400],
                                    }
                                )
                            else:
                                snippets.append(
                                    {
                                        "src": f"{tp.name}:L{i}",
                                        "key": k,
                                        "fn": m.group(0),
                                    }
                                )
                        else:
                            walk(v)
                elif isinstance(o, list):
                    for x in o:
                        walk(x)

            walk(obj)

print("snippets", len(snippets))
for s in snippets[:15]:
    print("---", s["src"], s.get("key"))
    print(s.get("fn") or s.get("excerpt", "")[:300])

(out / "ops_repo_snippets.json").write_text(
    json.dumps(snippets, indent=2), encoding="utf-8"
)

