"""Scan agent transcripts for peak Writes vs disk for ZionVM focus files."""
from __future__ import annotations

import json
from collections import defaultdict
from pathlib import Path

repo = Path(r"c:\Users\aosebastiao\Desktop\SentinelAI")
tbase = Path(
    r"C:\Users\aosebastiao\.cursor\projects\c-Users-aosebastiao-Desktop-SentinelAI\agent-transcripts"
)
out_dir = repo / "_recover_out"
out_dir.mkdir(exist_ok=True)

FOCUS_NAMES = [
    "ZionvmManagerPanel",
    "ZionvmOpsPanel",
    "ZionvmPermissionsPanel",
    "ZionvmCorpParityPanel",
    "ZionvmEnterpriseS2630Panel",
    "ZvmCard",
    "ZvmCreateVmCard",
    "zionvm-corp-fx.css",
    "zionvm-ds.css",
    "ZionvmClusterPanel",
    "ZIONVM-ROADMAP.md",
    "repo-layout-plan.mdc",
]

FOCUS_DISK = [
    "frontend/src/pages/ZionvmManagerPanel.tsx",
    "frontend/src/pages/ZionvmOpsPanel.tsx",
    "frontend/src/pages/ZionvmPermissionsPanel.tsx",
    "frontend/src/pages/ZionvmCorpParityPanel.tsx",
