    "frontend/src/components/zionvm/ZvmCreateVmCard.tsx",
    "frontend/src/styles/zionvm-corp-fx.css",
    "frontend/src/styles/zionvm-ds.css",
    "frontend/src/api/client.ts",
    "docs/ZIONVM-ROADMAP.md",
    ".cursor/rules/repo-layout-plan.mdc",
]

transcripts = [
    tbase
    / "e5492ecc-99c4-4a47-9d7c-0ff1456722bf"
    / "e5492ecc-99c4-4a47-9d7c-0ff1456722bf.jsonl",
    tbase
    / "a8f9e08f-eaaa-4389-a28f-6c3ffb324b79"
    / "a8f9e08f-eaaa-4389-a28f-6c3ffb324b79.jsonl",
    tbase
    / "57edbc0d-e0b9-4df8-afb3-f5db4a2ed851"
    / "57edbc0d-e0b9-4df8-afb3-f5db4a2ed851.jsonl",
]
sub = tbase / "e5492ecc-99c4-4a47-9d7c-0ff1456722bf" / "subagents"
if sub.exists():
    transcripts.extend(sorted(sub.glob("*.jsonl")))


def is_focus(path: str) -> bool:
    pl = path.replace("\\", "/").lower()
    name = Path(pl).name
    for f in FOCUS_NAMES:
        if f.lower() in name.lower():
            return True
    if name == "client.ts" and ("frontend" in pl or "api" in pl):
        return True
    if "backend" in pl and "zionvm" in pl:
        return True
    if "repo-layout-plan" in pl:
        return True
    if "zionvm-roadmap" in pl:
        return True
    return False


def normalize_path(path: str) -> str:
    p = path.replace("\\", "/")
    rs = str(repo).replace("\\", "/")
    if p.lower().startswith(rs.lower()):
        p = p[len(rs) :].lstrip("/")
    for prefix in [
        "c:/Users/aosebastiao/Desktop/SentinelAI/",
        "C:/Users/aosebastiao/Desktop/SentinelAI/",
    ]:
        if p.startswith(prefix) or p.lower().startswith(prefix.lower()):
            p = p[len(prefix) :]
    return p


def extract_tool_calls(obj, out):
    if isinstance(obj, dict):
        name = obj.get("name") or obj.get("toolName") or obj.get("tool")
        args = (
            obj.get("arguments")
            or obj.get("args")
            or obj.get("input")
            or obj.get("parameters")
        )
        if name and args is not None:
            n = str(name)
            if n == "Write" or n.endswith(".Write") or n.endswith("Write"):
                if "StrReplace" not in n:
                    out.append(("Write", n, args))
            if n == "StrReplace" or "StrReplace" in n:
                out.append(("StrReplace", n, args))
        for v in obj.values():
            extract_tool_calls(v, out)
    elif isinstance(obj, list):
        for v in obj:
            extract_tool_calls(v, out)


def parse_args(args):
    if isinstance(args, str):
        try:
            args = json.loads(args)
        except Exception:
            return {}
    return args if isinstance(args, dict) else {}


peaks: dict[str, dict] = {}
writes: dict[str, list] = defaultdict(list)
strreplaces: dict[str, list] = defaultdict(list)
stats: dict[str, int] = defaultdict(int)

for tp in transcripts:
    if not tp.exists():
        print("MISSING", tp)
        continue
    print("Scanning", tp, "size", tp.stat().st_size)
    with open(tp, "r", encoding="utf-8", errors="replace") as f:
        for i, line in enumerate(f, 1):
            if "Write" not in line and "StrReplace" not in line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                stats["bad_json"] += 1
                continue
            calls = []
