                    old = (
                        args.get("old_string")
                        or args.get("oldString")
                        or args.get("old_str")
                        or ""
                    )
                    new = (
                        args.get("new_string")
                        or args.get("newString")
                        or args.get("new_str")
                        or ""
                    )
                    strreplaces[npath].append(
                        {
                            "src": src,
