#!/usr/bin/env python3
"""SentinelAI lab agent — heartbeat + CPU/RAM/disk (+ services) push.

Usage (env):
  set SENTINEL_URL=http://localhost:8800
  set SENTINEL_AGENT_TOKEN=<token>
  python sentinel_lab_agent.py

Usage (config file next to script):
  agent.json → { "url": "...", "token": "...", "interval": 30, "hostname": "optional" }

Optional: pip install psutil
"""

from __future__ import annotations

import json
import os
import platform
import socket
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

VERSION = "0.2.0-lab"


def _env(name: str, default: str = "") -> str:
    return os.environ.get(name, default).strip()


def _load_config() -> dict:
    cfg_path = Path(__file__).resolve().with_name("agent.json")
    if not cfg_path.is_file():
        return {}
    try:
        data = json.loads(cfg_path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def collect_metrics() -> dict:
    cpu_pct = None
    mem_pct = None
    disk_pct = None
    services: list[dict] = []

    try:
        import psutil  # type: ignore

        cpu_pct = round(float(psutil.cpu_percent(interval=0.4)), 2)
        mem_pct = round(float(psutil.virtual_memory().percent), 2)
        root = "C:\\" if os.name == "nt" else "/"
        disk_pct = round(float(psutil.disk_usage(root).percent), 2)
        if hasattr(psutil, "win_service_get") and os.name == "nt":
            for svc in ("wuauserv", "Spooler", "EventLog", "Winmgmt"):
                try:
                    st = psutil.win_service_get(svc).as_dict().get("status", "unknown")
                    services.append({"name": svc, "status": str(st)})
                except Exception:
                    continue
    except ImportError:
        load = os.getloadavg()[0] if hasattr(os, "getloadavg") else 1.0
        cpu_pct = round(min(load * 10, 99.0), 2)
        mem_pct = 42.0
        disk_pct = 55.0
        services = [{"name": "lab", "status": "running"}]

    cfg = _load_config()
    hostname = _env("SENTINEL_HOSTNAME") or str(cfg.get("hostname") or "") or socket.gethostname()
    ip_address = None
    try:
        ip_address = socket.gethostbyname(hostname)
    except Exception:
        try:
            ip_address = socket.gethostbyname(socket.gethostname())
        except Exception:
            ip_address = None

    return {
        "cpu_pct": cpu_pct,
        "mem_pct": mem_pct,
        "disk_pct": disk_pct,
        "hostname": hostname,
        "services": services,
        "version": VERSION,
        "ip_address": ip_address,
    }


def post_json(url: str, token: str, body: dict) -> dict:
    data = json.dumps(body).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=data,
        method="POST",
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
            "User-Agent": f"sentinel-lab-agent/{VERSION}",
        },
    )
    with urllib.request.urlopen(req, timeout=15) as resp:
        return json.loads(resp.read().decode("utf-8"))


def main() -> int:
    cfg = _load_config()
    base = (_env("SENTINEL_URL") or str(cfg.get("url") or "http://localhost:8000")).rstrip("/")
    token = _env("SENTINEL_AGENT_TOKEN") or str(cfg.get("token") or "")
    interval = int(_env("SENTINEL_INTERVAL") or str(cfg.get("interval") or 30) or 30)
    if not token:
        print("Defina SENTINEL_AGENT_TOKEN ou agent.json com token.", file=sys.stderr)
        return 2

    print(f"SentinelAI lab agent {VERSION} → {base} interval={interval}s ({platform.system()})")
    while True:
        metrics = collect_metrics()
        try:
            post_json(
                f"{base}/api/agents/heartbeat",
                token,
                {"version": VERSION, "ip_address": metrics.get("ip_address")},
            )
            row = post_json(f"{base}/api/agents/metrics", token, metrics)
            lm = row.get("last_metrics") or {}
