class ParityError(RuntimeError):
    pass


def _run(cmd: list[str], *, timeout: int = 120) -> str:
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, check=False)
    except FileNotFoundError as exc:
        raise ParityError(f"Comando não encontrado: {cmd[0]}") from exc
    if proc.returncode != 0:
        err = (proc.stderr or proc.stdout or "").strip()
        raise ParityError(err or f"exit {proc.returncode}")
    return (proc.stdout or "").strip()


def _ensure_dir(path: str) -> Path:
    p = Path(path)
    p.mkdir(parents=True, exist_ok=True)
    return p


def iscsi_login(portal: str, target_iqn: str, mount_path: str) -> dict:
    mount = _ensure_dir(mount_path)
    iscsiadm = shutil.which("iscsiadm")
    if not iscsiadm:
        (mount / ".zionvm-iscsi-stub").write_text(f"{portal}\n{target_iqn}\n", encoding="utf-8")
        return {"mount_path": str(mount), "simulated": True, "reason": "iscsiadm missing"}
    try:
        _run([iscsiadm, "-m", "discovery", "-t", "sendtargets", "-p", portal], timeout=60)
        _run(
            [
                iscsiadm,
                "-m",
                "node",
                "-T",
                target_iqn,
                "-p",
                portal,
                "--login",
            ],
            timeout=60,
        )
    except ParityError as exc:
        (mount / ".zionvm-iscsi-stub").write_text(str(exc), encoding="utf-8")
        return {"mount_path": str(mount), "simulated": True, "error": str(exc)}
    return {"mount_path": str(mount), "simulated": False, "portal": portal, "target_iqn": target_iqn}


