    rbd = shutil.which("rbd")
    if not rbd:
        (mount / ".zionvm-ceph-stub").write_text(json.dumps({"pool": pool, "mon": mon_host}), encoding="utf-8")
        return {"mount_path": str(mount), "simulated": True, "reason": "rbd missing"}
    try:
        _run([rbd, "ls", pool, "-m", mon_host], timeout=30)
    except ParityError as exc:
        (mount / ".zionvm-ceph-stub").write_text(str(exc), encoding="utf-8")
        return {"mount_path": str(mount), "simulated": True, "error": str(exc)}
    return {"mount_path": str(mount), "pool": pool, "mon_host": mon_host, "simulated": False}


def storage_volume_migrate(src_root: str, dest_root: str, src_path: str) -> dict:
    src = Path(src_root) / src_path
    dest = Path(dest_root) / src_path
    if not src.is_file():
        raise ParityError(f"Ficheiro não encontrado: {src}")
    dest.parent.mkdir(parents=True, exist_ok=True)
