            out = subprocess.check_output(
                [zfs_bin, "list", "-H", "-o", "name,mountpoint,used,avail"],
                text=True,
                timeout=10,
            )
            for line in out.splitlines():
                parts = line.split("\t")
                if len(parts) < 4:
                    continue
                pool_name, mountpoint, used_t, avail_t = parts[0], parts[1], parts[2], parts[3]
                used_b = _zfs_bytes(used_t)
                avail_b = _zfs_bytes(avail_t)
                total_b = (used_b or 0) + (avail_b or 0) if used_b is not None and avail_b is not None else None
                safe = pool_name.replace("/", "-").replace("@", "-")
                storages.append(
                    {
                        "name": f"zfs-{safe}",
                        "storage_type": "zfs",
