def _slugify(label: str) -> str:
    s = re.sub(r"[^a-zA-Z0-9]+", "-", label.strip().lower()).strip("-")
    return (s or "custom")[:48]


def _load_custom_templates() -> dict[str, dict]:
    if not CUSTOM_TEMPLATES_PATH.is_file():
        return {}
    try:
        raw = json.loads(CUSTOM_TEMPLATES_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(raw, dict):
        return {}
    out: dict[str, dict] = {}
    for tid, t in raw.items():
        if not isinstance(t, dict):
            continue
        out[str(tid)] = {
            "id": str(t.get("id") or tid),
            "label": str(t.get("label") or tid),
            "scope": str(t.get("scope") or "custom"),
            "widgets": [str(x) for x in (t.get("widgets") or ALL_WIDGETS)],
            "hidden": [str(x) for x in (t.get("hidden") or [])],
            "custom": True,
        }
    return out


def _save_custom_templates(data: dict[str, dict]) -> None:
    CUSTOM_TEMPLATES_PATH.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        tid: {
            "id": t["id"],
            "label": t["label"],
