@router.post("/coverage-campaign", response_model=ZionCoverageCampaignResponse)
async def zion_coverage_campaign(
    body: ZionCoverageCampaignRequest,
    _: User = Depends(require_operator),
):
    """Enfileira campanhas WMI / SNMP / inventário de software para fechar gaps de cobertura."""
    from app.workers.discovery_tasks import (
        run_snmp_poll,
        run_software_inventory_campaign,
        run_wmi_poll,
    )

    queued: dict = {}
    actions = {str(a).strip().lower() for a in (body.actions or [])}
    if not actions:
        raise HTTPException(status_code=400, detail="Informe ao menos uma ação")

    if "wmi_poll" in actions or "wmi" in actions:
        async_result = run_wmi_poll.delay(limit=body.limit)
        queued["wmi_poll"] = {"task_id": async_result.id, "limit": body.limit}
    if "snmp_poll" in actions or "snmp" in actions:
        async_result = run_snmp_poll.delay()
        queued["snmp_poll"] = {"task_id": async_result.id}
    if "software" in actions or "software_inventory" in actions:
        async_result = run_software_inventory_campaign.delay(limit=body.limit)
        queued["software"] = {"task_id": async_result.id, "limit": body.limit}

    if not queued:
        raise HTTPException(
            status_code=400,
            detail="Ações inválidas. Use: wmi_poll, snmp_poll, software",
        )
    return ZionCoverageCampaignResponse(
        queued=queued,
        message=f"Campanha enfileirada: {', '.join(queued.keys())}",
    )


