class LxcError(RuntimeError):
    pass


def _run(cmd: list[str], *, timeout: int = 300) -> str:
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, check=False)
    except FileNotFoundError as exc:
        raise LxcError(f"Comando não encontrado: {cmd[0]}") from exc
    if proc.returncode != 0:
        err = (proc.stderr or proc.stdout or "").strip()
        raise LxcError(err or f"exit {proc.returncode}: {' '.join(cmd)}")
    return (proc.stdout or "").strip()


def detect_backend() -> str:
    pref = (os.environ.get("ZIONVM_LXC_BACKEND") or "auto").strip().lower()
    if pref == "pct":
        if shutil.which("pct"):
            return "pct"
        raise LxcError("ZIONVM_LXC_BACKEND=pct mas pct não encontrado")
    if pref == "lxd":
        if shutil.which("lxc"):
            return "lxd"
        raise LxcError("ZIONVM_LXC_BACKEND=lxd mas lxc não encontrado")
    if shutil.which("pct"):
        return "pct"
    if shutil.which("lxc"):
        return "lxd"
    raise LxcError("LXC indisponível — instale LXD (lxc) ou use host Proxmox (pct)")


def _safe_name(name: str) -> str:
    cleaned = re.sub(r"[^a-zA-Z0-9._-]", "-", (name or "ct").strip())[:63]
    return cleaned.lower() or "ct"


def create_container(
    *,
    vmid: int,
    name: str,
    memory_mb: int = 512,
    template: str | None = None,
) -> dict:
    backend = detect_backend()
    cname = _safe_name(name)
    if backend == "lxd":
        tpl = template or os.environ.get("ZIONVM_LXC_TEMPLATE", "ubuntu:22.04")
        _run(["lxc", "launch", tpl, cname])
        if memory_mb:
            try:
                _run(["lxc", "config", "set", cname, f"limits.memory={int(memory_mb)}MB"])
            except LxcError:
                pass
        return {"name": cname, "vmid": vmid, "status": "stopped", "backend": "lxd", "template": tpl}
    # pct (Proxmox)
    tpl_path = template or os.environ.get("ZIONVM_PCT_TEMPLATE", "")
    if not tpl_path or not Path(tpl_path).is_file():
        raise LxcError(
            "pct create exige template — defina ZIONVM_PCT_TEMPLATE=/var/lib/vz/template/cache/....tar.zst"
        )
    rootfs = os.environ.get("ZIONVM_PCT_STORAGE", "local")
    _run(
        [
            "pct",
            "create",
            str(int(vmid)),
            tpl_path,
            "--hostname",
            cname,
            "--memory",
            str(int(memory_mb)),
            "--storage",
            rootfs,
        ]
    )
    return {"name": cname, "vmid": vmid, "status": "stopped", "backend": "pct", "template": tpl_path}


def start_container(*, vmid: int, name: str | None = None) -> dict:
    backend = detect_backend()
    if backend == "lxd":
        cname = _safe_name(name or f"ct-{vmid}")
        _run(["lxc", "start", cname])
        return {"name": cname, "status": "running", "backend": "lxd"}
    _run(["pct", "start", str(int(vmid))])
    return {"vmid": vmid, "status": "running", "backend": "pct"}


def stop_container(*, vmid: int, name: str | None = None) -> dict:
    backend = detect_backend()
    if backend == "lxd":
        cname = _safe_name(name or f"ct-{vmid}")
        _run(["lxc", "stop", cname])
        return {"name": cname, "status": "stopped", "backend": "lxd"}
    _run(["pct", "stop", str(int(vmid))])
    return {"vmid": vmid, "status": "stopped", "backend": "pct"}


def delete_container(*, vmid: int, name: str | None = None) -> dict:
    backend = detect_backend()
    if backend == "lxd":
        cname = _safe_name(name or f"ct-{vmid}")
        _run(["lxc", "delete", cname, "--force"])
        return {"name": cname, "destroyed": True, "backend": "lxd"}
    _run(["pct", "destroy", str(int(vmid))])
    return {"vmid": vmid, "destroyed": True, "backend": "pct"}


def list_containers_local() -> list[dict]:
    try:
        backend = detect_backend()
    except LxcError:
        return []
    if backend == "lxd":
        raw = _run(["lxc", "list", "--format", "json"])
        try:
            rows = json.loads(raw)
        except json.JSONDecodeError:
