#!/usr/bin/env python3
"""ZionVM node agent — heartbeat, metrics, storage + network sync (Sprint 3–7).

Usage (env):
  set ZIONVM_URL=http://localhost:8800
  set ZIONVM_AGENT_TOKEN=<token from POST /api/zionvm/v1/nodes/{id}/agent-token>
  python zionvm_node_agent.py

Optional: pip install psutil
Interval default: 30s (ZIONVM_INTERVAL).
"""

from __future__ import annotations

import json
import os
import platform
import shutil
import socket
import subprocess
import sys
import time
import ssl
import urllib.error
import urllib.request
from pathlib import Path

VERSION = "0.9.0-s26-30"


def _env(name: str, default: str = "") -> str:
    return os.environ.get(name, default).strip()


def _load_config() -> dict:
    cfg_path = Path(__file__).resolve().with_name("zionvm-agent.json")
    if not cfg_path.is_file():
        return {}
    try:
        data = json.loads(cfg_path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _zfs_bytes(token: str) -> int | None:
    token = token.strip().upper()
    if not token or token == "-":
        return None
    mult = 1
    if token.endswith("K"):
        mult = 1024
        token = token[:-1]
    elif token.endswith("M"):
        mult = 1024**2
        token = token[:-1]
    elif token.endswith("G"):
        mult = 1024**3
        token = token[:-1]
    elif token.endswith("T"):
        mult = 1024**4
        token = token[:-1]
    try:
        return int(float(token) * mult)
    except ValueError:
        return None


def collect_storages() -> list[dict]:
    storages: list[dict] = []
    local_root = _env("ZIONVM_LOCAL_ROOT", "/var/lib/zionvm/images")
    local_path = Path(local_root)
    if not local_path.is_dir():
        local_path = Path.home() / "zionvm" / "images"
        local_path.mkdir(parents=True, exist_ok=True)
    try:
        usage = shutil.disk_usage(local_path)
        storages.append(
            {
                "name": "local",
                "storage_type": "local",
                "path": str(local_path),
                "content_types": ["images", "iso", "vztmpl"],
                "used_bytes": int(usage.used),
                "total_bytes": int(usage.total),
            }
        )
    except Exception:
        storages.append(
            {
                "name": "local",
                "storage_type": "local",
                "path": str(local_path),
                "content_types": ["images", "iso", "vztmpl"],
            }
        )

    zfs_bin = shutil.which("zfs")
    if zfs_bin:
        try:
            out = subprocess.check_output(
                [zfs_bin, "list", "-H", "-o", "name,mountpoint,used,avail"],
                text=True,
                timeout=10,
            )
            for line in out.splitlines():
                parts = line.split("\t")
                if len(parts) < 4:
                    continue
                pool_name, mountpoint, used_t, avail_t = parts[0], parts[1], parts[2], parts[3]
                used_b = _zfs_bytes(used_t)
                avail_b = _zfs_bytes(avail_t)
                total_b = (used_b or 0) + (avail_b or 0) if used_b is not None and avail_b is not None else None
                safe = pool_name.replace("/", "-").replace("@", "-")
                storages.append(
                    {
                        "name": f"zfs-{safe}",
                        "storage_type": "zfs",
                        "path": mountpoint or f"/{pool_name}",
                        "zfs_pool": pool_name,
                        "content_types": ["images", "rootdir"],
                        "used_bytes": used_b,
                        "total_bytes": total_b,
                    }
                )
        except Exception:
            pass

    try:
        import psutil  # type: ignore

        seen_nfs: set[str] = set()
        for part in psutil.disk_partitions(all=False):
            if part.fstype not in ("nfs", "nfs4"):
                continue
            key = part.mountpoint
            if key in seen_nfs:
                continue
            seen_nfs.add(key)
            server = part.device.split(":", 1)[0] if ":" in part.device else part.device
            export = part.device.split(":", 1)[1] if ":" in part.device else part.mountpoint
            name = f"nfs-{Path(part.mountpoint).name or 'share'}"
            entry: dict = {
                "name": name,
                "storage_type": "nfs",
                "path": part.mountpoint,
                "nfs_server": server,
                "nfs_export": export,
                "content_types": ["images", "iso", "backup"],
            }
            try:
                usage = shutil.disk_usage(part.mountpoint)
                entry["used_bytes"] = int(usage.used)
                entry["total_bytes"] = int(usage.total)
            except Exception:
                pass
            storages.append(entry)
    except Exception:
        pass

    return storages


def _iface_cidr(name: str) -> str | None:
    try:
        import psutil  # type: ignore

