#!/usr/bin/env python3
"""ZionXDR Windows agent — heartbeat, jobs, ingest Eagle (estilo ZionVM node agent)."""

from __future__ import annotations

import json
import os
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

AGENT_VERSION = "0.3.1-s9"
POLL_SECONDS = 5


def _api_base() -> str:
    return (os.environ.get("ZIONXDR_API_BASE") or "http://127.0.0.1:8000").rstrip("/")


def _token() -> str:
    tok = (os.environ.get("ZIONXDR_AGENT_TOKEN") or "").strip()
    if not tok:
        raise SystemExit("Defina ZIONXDR_AGENT_TOKEN (POST /api/zionxdr/v1/endpoints/{id}/agent-token)")
    return tok


def _request(method: str, path: str, body: dict | None = None) -> dict:
    url = f"{_api_base()}{path}"
    data = None
    headers = {"Authorization": f"Bearer {_token()}", "Content-Type": "application/json"}
    cert_hint = (os.environ.get("ZIONXDR_CLIENT_CERT_HINT") or "").strip()
    if cert_hint:
        headers["X-ZionXDR-Client-Cert"] = cert_hint
    if body is not None:
        data = json.dumps(body).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            raw = resp.read().decode("utf-8")
            return json.loads(raw) if raw else {}
    except urllib.error.HTTPError as exc:
        err = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"HTTP {exc.code} {path}: {err}") from exc


def _ensure_eagle_path() -> None:
    root = Path(__file__).resolve().parent
    if str(root) not in sys.path:
        sys.path.insert(0, str(root))


def _console_state():
    _ensure_eagle_path()
    from eagle.console_server import ConsoleState
    from eagle.runner import RuntimePaths

    root = Path(__file__).resolve().parent
    paths = RuntimePaths.from_root(root)
    return ConsoleState(paths)


def _collect_payload() -> dict:
    _ensure_eagle_path()
    state = _console_state()
    stats = state.stats()
    stats["telemetry"] = state.telemetry_status()
    alerts = state.read_alerts(limit=300)
    quar = state.quarantine_list()
    coverage = state.coverage_summary()
    rules = state.rules_summary()
    return {
        "stats": stats,
        "alerts": alerts,
        "quarantine": quar,
        "extra": {"coverage": coverage, "rules": rules},
    }


def _run_job(action: str, payload: dict) -> dict:
    state = _console_state()
    root = Path(__file__).resolve().parent
    if action == "eagle.scan":
        return state.scan_once(evaluate_all=bool(payload.get("all", True)))
    if action == "eagle.monitor_start":
        return state.start_monitor(interval=float(payload.get("interval", 3)))
    if action == "eagle.monitor_stop":
        return state.stop_monitor()
    if action == "eagle.policy_apply":
        import yaml

        yaml_text = payload.get("yaml_text") or ""
        data = yaml.safe_load(yaml_text) or {}
        telemetry = data.get("telemetry") if isinstance(data.get("telemetry"), dict) else None
        rules_body = yaml.safe_dump({"rules": data.get("rules") or []}, allow_unicode=True, sort_keys=False)
        rules_path = root / "config" / "rules.yaml"
        rules_path.parent.mkdir(parents=True, exist_ok=True)
        rules_path.write_text(rules_body, encoding="utf-8")
        from eagle.zionxdr_control import write_control

        write_control(
            root,
            policy_id=payload.get("policy_id"),
            policy_version=payload.get("version"),
        )
        if telemetry:
            from eagle.telemetry_ops import apply_telemetry_policy

            apply_telemetry_policy(root, telemetry)
        return {"ok": True, "policy_version": payload.get("version")}
    if action == "eagle.set_enforcement_mode":
        from eagle.zionxdr_control import write_control

        mode = str(payload.get("enforcement_mode") or "monitor")
        write_control(root, enforcement_mode=mode)
        return {"ok": True, "enforcement_mode": mode}
    if action == "eagle.memory_scan":
        return state.memory_scan()
    if action == "eagle.etw_start":
        return state.etw_start()
    if action == "eagle.etw_stop":
        return state.etw_stop()
    if action == "eagle.policy_reload":
        from eagle.runner import AgentRunner

        AgentRunner(paths=state.paths).engine.reload()
        return {"ok": True, "reloaded": True}
    if action == "eagle.evidence_collect":
        from eagle.evidence import collect_evidence

        fp = str(payload.get("fingerprint") or "")
        return collect_evidence(state.paths, fp)
    if action == "eagle.quarantine_request":
        return {"ok": True, "note": "quarantine HITL stub", "fingerprint": payload.get("fingerprint")}
    if action == "eagle.isolate_stub":
        return {"ok": True, "note": "isolate HITL stub"}
    if action == "eagle.ingest":
        return {"ok": True}
    raise ValueError(f"Ação desconhecida: {action}")


def _heartbeat() -> None:
    import socket

    _request(
        "POST",
        "/api/zionxdr/v1/agent/heartbeat",
        {"version": AGENT_VERSION, "hostname": socket.gethostname()},
    )


def _ingest(extra: dict | None = None) -> None:
    pack = _collect_payload()
    body = {
        "stats": pack["stats"],
        "alerts": pack["alerts"],
        "quarantine": pack["quarantine"],
    }
    body["extra"] = {
        "coverage": pack.get("extra", {}).get("coverage"),
        "rules": pack.get("extra", {}).get("rules"),
        "telemetry": pack["stats"].get("telemetry"),
    }
    _request("POST", "/api/zionxdr/v1/agent/ingest", body)


def _claim_job() -> dict | None:
    out = _request("POST", "/api/zionxdr/v1/agent/jobs/claim", {})
    return out.get("job")


def _complete_job(job_id: int, ok: bool, result: dict | None = None, error: str | None = None) -> None:
    _request(
        "POST",
        f"/api/zionxdr/v1/agent/jobs/{job_id}/complete",
        {"ok": ok, "result": result, "error": error},
    )


def main() -> None:
    print(f"ZionXDR agent {AGENT_VERSION} → {_api_base()}")
    while True:
        try:
            _heartbeat()
            job = _claim_job()
            if job:
                jid = job["id"]
                action = job["action"]
                payload = job.get("payload") or {}
                try:
                    result = _run_job(action, payload)
                    _complete_job(jid, True, result=result)
                except Exception as exc:
                    _complete_job(jid, False, error=str(exc))
            _ingest()
        except Exception as exc:
            print(f"[zionxdr-agent] {exc}", file=sys.stderr)
        time.sleep(POLL_SECONDS)


if __name__ == "__main__":
    main()

