"""Relatório operacional completo do mapa (Vision AI / rules-engine)."""

from __future__ import annotations

from datetime import UTC, datetime

from sqlalchemy.orm import Session

from app.models import Device, DeviceStatus
from app.services.topology_service import _devices_in_department, build_topology_graph


def _format_duration(since: datetime | None, now: datetime) -> str:
    if since is None:
        return "tempo desconhecido"
    if since.tzinfo is None:
        since = since.replace(tzinfo=UTC)
    delta = now - since
    secs = max(int(delta.total_seconds()), 0)
    days, rem = divmod(secs, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, _ = divmod(rem, 60)
    parts: list[str] = []
    if days:
        parts.append(f"{days}d")
    if hours:
        parts.append(f"{hours}h")
    if minutes or not parts:
        parts.append(f"{minutes}min")
    return " ".join(parts)


def _device_offline_since(device: Device, now: datetime) -> str:
    if device.status == DeviceStatus.ACTIVE:
        return "online"
    return _format_duration(device.last_seen, now)


def _dept_alert_duration(devices: list[Device], now: datetime) -> str:
    offline = [d for d in devices if d.status != DeviceStatus.ACTIVE]
    if not offline:
        return "—"
    times = [d.last_seen for d in offline if d.last_seen]
    if not times:
        return "tempo desconhecido"
    oldest = min(times)
    return _format_duration(oldest, now)


def build_operational_map_report(
    session: Session,
    map_layer: str = "physical",
