"""AI NOC Copilot — contextual assistant with optional external LLM + RAG + Guardian."""

from datetime import UTC, datetime, timedelta

from sqlalchemy import func, select
from sqlalchemy.orm import Session

from app.config import settings
from app.engines.ai.attack_response import build_attack_reply_section
from app.engines.ai.llm_client import build_system_prompt, chat_completion, llm_available
from app.engines.ai.noc_rag import format_rag_for_prompt, retrieve_noc_rag, sanitize_event_message
