"""Sentinel Guardian — avalia ameaças na telemetria e emite alertas quando necessário."""

from __future__ import annotations

from datetime import UTC, datetime, timedelta
from typing import Any

from sqlalchemy import func, select
from sqlalchemy.orm import Session

from app.engines.ai.attack_response import recommend_response
from app.models import AnomalyRecord, Device, DeviceStatus, Event, EventSeverity
from app.services.alert_service import queue_alerts_for_event

THREAT_EVENT_TYPE = "ai_threat_detected"
DEDUP_MINUTES = 45


def _count_offline(session: Session) -> tuple[int, int]:
    total = session.execute(select(func.count(Device.id))).scalar() or 0
    offline = session.execute(
        select(func.count(Device.id)).where(Device.status == DeviceStatus.INACTIVE)
    ).scalar() or 0
    return int(total), int(offline)


def _recent_events(session: Session, hours: int = 2) -> list[Event]:
    since = datetime.now(UTC) - timedelta(hours=hours)
    return list(
        session.execute(
            select(Event).where(Event.created_at >= since).order_by(Event.created_at.desc()).limit(400)
        )
        .scalars()
        .all()
    )


def _already_alerted(session: Session, fingerprint: str) -> bool:
    since = datetime.now(UTC) - timedelta(minutes=DEDUP_MINUTES)
    rows = session.execute(
        select(Event)
        .where(Event.event_type == THREAT_EVENT_TYPE, Event.created_at >= since)
        .order_by(Event.created_at.desc())
        .limit(30)
    ).scalars().all()
    return any(fingerprint in (e.message or "") for e in rows)


def assess_operational_threats(session: Session) -> dict[str, Any]:
    """Heurísticas conservadoras — só sinaliza o que parece importante."""
    total, offline = _count_offline(session)
    events = _recent_events(session, hours=2)
    anomalies = session.execute(
        select(func.count(AnomalyRecord.id)).where(AnomalyRecord.is_resolved.is_(False))
    ).scalar() or 0

    down_events = [e for e in events if e.event_type == "device_down"]
    anomaly_events = [e for e in events if e.event_type == "anomaly_detected"]
    check_fail = [e for e in events if e.event_type in ("http_check_failed", "tcp_check_failed")]
    critical = [e for e in events if e.severity == EventSeverity.CRITICAL]

    findings: list[dict[str, Any]] = []

    offline_ratio = (offline / total) if total else 0.0
    if total >= 5 and (offline >= 5 or offline_ratio >= 0.25):
        findings.append(
            {
                "code": "mass_offline",
                "severity": "critical",
                "title": "Queda em massa de dispositivos",
                "detail": f"{offline}/{total} offline ({offline_ratio:.0%}) — possível falha de enlace, energia ou ataque.",
                "evidence": {"offline": offline, "total": total, "device_down_events_2h": len(down_events)},
            }
        )

    if len(down_events) >= 8:
        findings.append(
            {
                "code": "device_down_burst",
                "severity": "warning",
                "title": "Rajada de eventos device_down",
                "detail": f"{len(down_events)} eventos device_down em 2h.",
                "evidence": {"count": len(down_events)},
            }
        )

    if anomalies >= 4 or len(anomaly_events) >= 5:
        findings.append(
            {
                "code": "anomaly_cluster",
                "severity": "warning",
                "title": "Cluster de anomalias de latência",
                "detail": f"{anomalies} anomalia(s) ativa(s); {len(anomaly_events)} eventos recentes.",
                "evidence": {"active_anomalies": anomalies, "recent_events": len(anomaly_events)},
            }
        )

    if len(check_fail) >= 6:
        findings.append(
            {
                "code": "probe_fail_burst",
                "severity": "warning",
                "title": "Falhas de probe HTTP/TCP em rajada",
                "detail": f"{len(check_fail)} falhas de check em 2h — serviço degradado ou bloqueio.",
                "evidence": {"count": len(check_fail)},
            }
        )

    if len(critical) >= 10:
        findings.append(
            {
                "code": "critical_flood",
                "severity": "critical",
                "title": "Volume elevado de eventos críticos",
                "detail": f"{len(critical)} eventos críticos em 2h.",
                "evidence": {"count": len(critical)},
            }
        )

    enriched = []
    for f in findings:
        resp = recommend_response(f["code"], f["severity"])
        enriched.append({**f, "response": resp})
    return {
        "assessed_at": datetime.now(UTC).isoformat(),
        "snapshot": {
            "devices_total": total,
            "devices_offline": offline,
            "active_anomalies": anomalies,
            "events_2h": len(events),
            "critical_2h": len(critical),
        },
        "findings": enriched,
        "threat_level": _aggregate_level(enriched),
    }


def _aggregate_level(findings: list[dict]) -> str:
    if not findings:
        return "clear"
    if any(f.get("severity") == "critical" for f in findings):
        return "critical"
    if any(f.get("severity") == "warning" for f in findings):
        return "elevated"
    return "watch"


