@dataclass
class AlertPayload:
    subject: str
    body: str
    severity: str
    event_type: str
    device_id: int | None = None
    event_id: int | None = None
    alert_id: int | None = None


def _push_deep_link(payload: AlertPayload) -> str:
    params: list[str] = []
    if payload.alert_id is not None:
        params.append(f"alert_id={payload.alert_id}")
    if payload.event_type:
        params.append(f"event_type={payload.event_type}")
    if payload.device_id is not None:
        params.append(f"device_id={payload.device_id}")
    qs = "&".join(params)
    return f"/#/alerts{('?' + qs) if qs else ''}"


async def send_push_channel(payload: AlertPayload) -> bool:
    return send_push_alert(
        payload.subject,
        payload.body,
        data={
            "url": _push_deep_link(payload),
            "event_type": payload.event_type,
            "device_id": payload.device_id,
            "event_id": payload.event_id,
            "alert_id": payload.alert_id,
            "severity": payload.severity,
        },
    )


async def send_email_channel(payload: AlertPayload) -> bool:
    return send_email_alert(payload.subject, payload.body)


async def send_sms_channel(payload: AlertPayload) -> bool:
