from app.config import settings
from app.models import Alert, AlertChannelConfig, AlertSilence, AlertStatus, Event, EventSeverity

_SEVERITY_RANK = {
    EventSeverity.INFO: 0,
    EventSeverity.WARNING: 1,
    EventSeverity.CRITICAL: 2,
    "info": 0,
    "warning": 1,
    "critical": 2,
}


def _severity_value(severity: EventSeverity | str) -> int:
    if isinstance(severity, EventSeverity):
        return _SEVERITY_RANK.get(severity, 0)
    return _SEVERITY_RANK.get(str(severity).lower(), 0)


def matching_rules(session: Session, event: Event) -> list:
    from app.models import AlertRule

    rules = session.execute(
        select(AlertRule).where(AlertRule.is_enabled.is_(True)).order_by(AlertRule.id)
    ).scalars().all()
    matched: list = []
    event_sev = _severity_value(event.severity)
    for rule in rules:
        if rule.event_type and rule.event_type != event.event_type:
            continue
        if event_sev < _severity_value(rule.min_severity):
            continue
        matched.append(rule)
    return matched


def is_event_silenced(session: Session, event: Event) -> bool:
    now = datetime.now(UTC)
    rows = session.execute(
        select(AlertSilence).where(
            AlertSilence.event_type == event.event_type,
            AlertSilence.silenced_until > now,
        )
    ).scalars().all()
    for row in rows:
        if row.device_id is None:
            return True
        if event.device_id is not None and row.device_id == event.device_id:
            return True
    return False


def is_duplicate_suppressed(session: Session, event: Event) -> bool:
    """Suppress re-queue when same (event_type, device_id) already alerted recently."""
    minutes = int(settings.alert_suppress_repeat_minutes or 0)
    if minutes <= 0:
        return False
    since = datetime.now(UTC) - timedelta(minutes=minutes)
    stmt = (
        select(Alert.id)
        .join(Event, Event.id == Alert.event_id)
        .where(
            Event.event_type == event.event_type,
            Alert.created_at >= since,
            Alert.status.in_([AlertStatus.PENDING, AlertStatus.SENT]),
        )
        .limit(1)
    )
    if event.device_id is None:
        stmt = stmt.where(Event.device_id.is_(None))
    else:
        stmt = stmt.where(Event.device_id == event.device_id)
    # Allow current event's own rows (idempotent re-queue); only suppress other events
    stmt = stmt.where(Event.id != event.id)
    return session.execute(stmt).first() is not None


def channels_for_event(session: Session, event: Event) -> list[str]:
    """Resolve alert channels: matching rules override global defaults when any rule matches."""
    rules = matching_rules(session, event)
    if rules:
        channels: list[str] = []
        for rule in rules:
            for ch in rule.channels or []:
                ch_norm = str(ch).strip().lower()
                if ch_norm and ch_norm not in channels:
                    channels.append(ch_norm)
        if channels:
            return channels
    return settings.enabled_alert_channels


