import hashlib
import logging
import re
import time

from app.config import settings

logger = logging.getLogger(__name__)


def backup_device_config(host: str, username: str | None = None, password: str | None = None) -> tuple[str, str]:
    username = username or settings.ssh_default_username
    password = password or settings.ssh_default_password

    if not username or not password:
        raise ValueError("Credenciais SSH não configuradas (SSH_DEFAULT_USERNAME/PASSWORD)")

    try:
        import paramiko
    except ImportError as exc:
        raise RuntimeError("paramiko não instalado") from exc

    client = paramiko.SSHClient()
    client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    try:
        client.connect(host, username=username, password=password, timeout=15, look_for_keys=False, allow_agent=False)
        stdin, stdout, stderr = client.exec_command("show running-config", timeout=30)
        content = stdout.read().decode("utf-8", errors="replace")
        err = stderr.read().decode("utf-8", errors="replace")
        if not content.strip():
            stdin, stdout, stderr = client.exec_command("cat /etc/os-release 2>/dev/null; uname -a", timeout=15)
            content = stdout.read().decode("utf-8", errors="replace")
        if not content.strip() and err:
            raise RuntimeError(err.strip() or "Comando SSH sem saída")
        content_hash = hashlib.sha256(content.encode()).hexdigest()
        return content, content_hash
    finally:
        client.close()


def _looks_like_network_config(content: str) -> bool:
    lower = content.lower()
    signals = ("hostname ", "interface ", "vlan ", "ip address", "router ", "switchport", "configuration")
    return any(s in lower for s in signals) and "name=" not in lower[:80]


def _config_lines_for_apply(content: str) -> list[str]:
    lines: list[str] = []
    for raw in content.splitlines():
        line = raw.rstrip()
        stripped = line.strip()
        if not stripped:
            continue
        low = stripped.lower()
        if low.startswith("building configuration") or low.startswith("current configuration"):
            continue
        if low.startswith("version ") and len(lines) < 3:
            continue
        if stripped.startswith("!"):
            continue
        if low in {"end", "exit"}:
            continue
        lines.append(line)
    return lines


def restore_device_config(
    host: str,
    content: str,
    username: str | None = None,
    password: str | None = None,
) -> dict:
    """Push backup content to a device over SSH (network running-config style).

    Returns {"status": "applied"|"failed", "lines": int, "detail": str}.
    """
    username = username or settings.ssh_default_username
    password = password or settings.ssh_default_password
    if not username or not password:
        raise ValueError("Credenciais SSH não configuradas")
    if not content or not content.strip():
        raise ValueError("Backup sem conteúdo")
    if not _looks_like_network_config(content):
        raise ValueError(
            "Conteúdo do backup não parece running-config de rede "
            "(ex.: snapshot Linux/os-release) — restore SSH recusado"
        )

    lines = _config_lines_for_apply(content)
    if not lines:
        raise ValueError("Nenhuma linha de configuração aplicável após filtro")
    if len(lines) > 2500:
        raise ValueError(f"Backup muito grande para apply interativo ({len(lines)} linhas)")

    try:
        import paramiko
    except ImportError as exc:
        raise RuntimeError("paramiko não instalado") from exc

    client = paramiko.SSHClient()
    client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    channel = None
    try:
        client.connect(host, username=username, password=password, timeout=15, look_for_keys=False, allow_agent=False)
        channel = client.invoke_shell(width=200, height=40)
        channel.settimeout(20)
        time.sleep(0.4)
        if channel.recv_ready():
            channel.recv(65535)

        def _send(cmd: str, wait: float = 0.35) -> str:
            channel.send(cmd + "\n")
            time.sleep(wait)
            out = b""
            end = time.time() + 8
            while time.time() < end:
                if channel.recv_ready():
                    out += channel.recv(65535)
                    end = time.time() + 1.5
                else:
                    time.sleep(0.15)
            return out.decode("utf-8", errors="replace")

        # Privilege + configure (Cisco-like; fails with clear stderr on other CLIs)
        _send("terminal length 0", 0.2)
        cfg_out = _send("configure terminal", 0.6)
        if re.search(r"(invalid|unknown|error|%\s)", cfg_out, re.I) and "config" not in cfg_out.lower():
            raise RuntimeError(f"Dispositivo não aceitou 'configure terminal': {cfg_out[-200:].strip()}")

        applied = 0
        for line in lines:
            _send(line, 0.12)
            applied += 1
            if applied % 40 == 0:
                time.sleep(0.4)

        end_out = _send("end", 0.5)
        write_out = _send("write memory", 1.0)
        if "incomplete" in write_out.lower() or "invalid" in write_out.lower():
            _send("copy running-config startup-config", 1.2)

        detail = (end_out + write_out)[-400:].strip() or f"{applied} linhas enviadas"
        logger.info("SSH restore applied %s lines on %s", applied, host)
        return {"status": "applied", "lines": applied, "detail": detail, "host": host}
    finally:
        if channel is not None:
            try:
                channel.close()
            except Exception:
                pass
        client.close()

"""Cálculo de progresso do scan: 0–5% nmap, 5–99% inventário por host."""

NMAP_MAX_PERCENT = 5
INVENTORY_MAX_PERCENT = 99


def nmap_percent(ratio: float) -> int:
    """ratio 0.0–1.0 dentro da fase nmap → 0–5%."""
    return min(NMAP_MAX_PERCENT, max(0, int(NMAP_MAX_PERCENT * min(1.0, ratio))))


def nmap_range_percent(start_ratio: float, end_ratio: float, inner_ratio: float) -> int:
    """Interpola dentro de um sub-intervalo da fase nmap (0–5%)."""
    lo = nmap_percent(start_ratio)
    hi = nmap_percent(end_ratio)
    span = max(hi - lo, 1)
    return lo + int(span * min(1.0, max(0.0, inner_ratio)))


def inventory_percent(hosts_done: float, total: int) -> int:
    """hosts_done pode ser fracionário (heartbeat) · total = hosts a inventariar."""
    if total <= 0:
        return NMAP_MAX_PERCENT
    ratio = min(1.0, max(0.0, hosts_done / total))
    span = INVENTORY_MAX_PERCENT - NMAP_MAX_PERCENT
    return min(INVENTORY_MAX_PERCENT, NMAP_MAX_PERCENT + int(span * ratio))

import ipaddress
import socket


def reverse_dns(ip: str, timeout: float = 2.0) -> str | None:
    original_timeout = socket.getdefaulttimeout()
    try:
        socket.setdefaulttimeout(timeout)
        hostname, _, _ = socket.gethostbyaddr(ip)
        return hostname
    except (socket.herror, socket.gaierror, OSError):
        return None
    finally:
        socket.setdefaulttimeout(original_timeout)


def validate_subnet(cidr: str) -> ipaddress.IPv4Network | ipaddress.IPv6Network:
    network = ipaddress.ip_network(cidr, strict=False)
    if network.num_addresses > 4096:
        raise ValueError("Sub-rede muito grande. Máximo permitido: /20 (4096 endereços)")
    return network


def iter_host_addresses(cidr: str) -> list[str]:
    network = validate_subnet(cidr)
    if network.version == 4:
        return [str(ip) for ip in network.hosts()]
    return [str(ip) for ip in network.hosts()]

"""Consultas externas (RDAP, DNS) para enriquecer dispositivos quando SNMP não responde."""

from __future__ import annotations

import ipaddress
import logging
from typing import Any

import httpx

from app.config import settings

logger = logging.getLogger(__name__)

RDAP_SERVERS = (
    "https://rdap.lacnic.net/rdap/ip/{ip}",
    "https://rdap.arin.net/registry/ip/{ip}",
    "https://rdap.db.ripe.net/ip/{ip}",
    "https://rdap.apnic.net/ip/{ip}",
)


def _extract_org(data: dict[str, Any]) -> str | None:
    for entity in data.get("entities") or []:
        roles = entity.get("roles") or []
        if "registrant" not in roles and "administrative" not in roles:
            continue
        vcard = entity.get("vcardArray")
        if not vcard or len(vcard) < 2:
            continue
        for row in vcard[1]:
            if len(row) >= 4 and row[0] == "fn" and row[3]:
                return str(row[3]).strip()
    return None


def lookup_rdap(ip: str, timeout: float | None = None, max_servers: int = 4) -> dict[str, str | None]:
    """Retorna organização (vendor) e identificador de rede a partir de RDAP."""
    if timeout is None:
        timeout = settings.discovery_rdap_timeout_seconds
    try:
        ipaddress.ip_address(ip)
    except ValueError:
        return {}

    result: dict[str, str | None] = {"vendor": None, "network": None, "hostname": None}
    headers = {"Accept": "application/rdap+json, application/json"}

    for template in RDAP_SERVERS[:max_servers]:
        url = template.format(ip=ip)
        try:
            with httpx.Client(timeout=timeout, follow_redirects=True) as client:
                response = client.get(url, headers=headers)
            if response.status_code != 200:
                continue
            data = response.json()
            org = _extract_org(data)
            if org:
                result["vendor"] = org
            network_name = data.get("name")
            if network_name:
                result["network"] = str(network_name)
            if result["vendor"]:
                return result
        except Exception:
            logger.debug("RDAP lookup failed for %s via %s", ip, url, exc_info=True)

    return result


def lookup_ptr_doh(ip: str, timeout: float | None = None) -> str | None:
    """Consulta registro PTR via DNS-over-HTTPS (Cloudflare)."""
    if timeout is None:
        timeout = settings.discovery_ptr_timeout_seconds
    try:
        ipaddress.ip_address(ip)
    except ValueError:
        return None

    if ipaddress.ip_address(ip).version != 4:
        return None

    parts = ip.split(".")[::-1]
    qname = ".".join(parts) + ".in-addr.arpa"
    url = "https://cloudflare-dns.com/dns-query"
    params = {"name": qname, "type": "PTR"}

    try:
        with httpx.Client(timeout=timeout) as client:
            response = client.get(url, params=params, headers={"Accept": "application/dns-json"})
        if response.status_code != 200:
            return None
        answers = response.json().get("Answer") or []
        for answer in answers:
            if answer.get("type") == 12 and answer.get("data"):
                ptr = str(answer["data"]).rstrip(".")
                return ptr
    except Exception:
        logger.debug("PTR DoH lookup failed for %s", ip, exc_info=True)
    return None


def lookup_ip_intel(ip: str, *, skip_rdap: bool = False) -> dict[str, str | None]:
    """Agrega RDAP + PTR para preencher vendor, modelo (rede) e hostname."""
    intel: dict[str, str | None] = {"vendor": None, "model": None, "hostname": None}

    try:
        addr = ipaddress.ip_address(ip)
        # RDAP em IPs privados/link-local não ajuda e atrasa o inventário.
        if addr.is_private or addr.is_loopback or addr.is_link_local or addr.is_reserved:
            skip_rdap = True
    except ValueError:
        return intel

    ptr = lookup_ptr_doh(ip)
    if ptr:
        intel["hostname"] = ptr

    if not skip_rdap:
        rdap = lookup_rdap(ip, max_servers=2)
        if rdap.get("vendor") and not intel.get("vendor"):
            intel["vendor"] = rdap["vendor"]
        if rdap.get("network") and not intel.get("model"):
            intel["model"] = rdap["network"]

    return intel

"""Inventário de software via SNMP (HOST-RESOURCES-MIB) e WMI."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import UTC, datetime
import logging

from app.config import settings
from app.engines.discovery.snmp_collector import _snmp_walk
from app.engines.discovery.wmi_collector import _wmi_query, wmi_credentials_configured

logger = logging.getLogger(__name__)

HR_SW_INSTALLED_NAME = "1.3.6.1.2.1.25.6.3.1.2"
HR_SW_INSTALLED_ID = "1.3.6.1.2.1.25.6.3.1.3"


@dataclass
class SoftwarePackage:
    name: str
    version: str | None = None
    vendor: str | None = None
    source: str = "snmp"

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "version": self.version,
            "vendor": self.vendor,
            "source": self.source,
        }


@dataclass
class SoftwareInventory:
    packages: list[SoftwarePackage] = field(default_factory=list)
    sources: list[str] = field(default_factory=list)
    collected_at: str | None = None
    error: str | None = None

    def to_extra_data(self) -> dict:
        return {
            "software": {
                "packages": [p.to_dict() for p in self.packages],
                "sources": self.sources,
                "collected_at": self.collected_at,
                "count": len(self.packages),
                "error": self.error,
            }
        }


def collect_software_snmp(
    host: str,
    community: str | None = None,
    *,
    limit: int | None = None,
) -> list[SoftwarePackage]:
    limit = limit or settings.software_inventory_max_packages
    names = _snmp_walk(host, HR_SW_INSTALLED_NAME, community, limit=limit)
    if not names:
        return []

    ids = _snmp_walk(host, HR_SW_INSTALLED_ID, community, limit=limit)
    packages: list[SoftwarePackage] = []
    for index, raw_name in enumerate(names):
        name = raw_name.strip()
        if not name or name.lower() in ("null", ""):
            continue
        version = ids[index].strip() if index < len(ids) else None
        if version and version.lower() == "null":
            version = None
        packages.append(SoftwarePackage(name=name, version=version, source="snmp"))
    return packages


def collect_software_wmi(
    host: str,
    username: str | None = None,
    password: str | None = None,
    domain: str | None = None,
    *,
    limit: int | None = None,
    include_slow_product_query: bool = False,
) -> list[SoftwarePackage]:
    if not wmi_credentials_configured() and not (username and password):
        return []

    limit = limit or settings.software_inventory_max_packages
    username = username or settings.wmi_username
    password = password or settings.wmi_password
    domain = domain if domain is not None else settings.wmi_domain
    timeout = settings.wmi_timeout_seconds
    packages: list[SoftwarePackage] = []

    try:
        store_rows = _wmi_query(
            host,
            username,
            password,
            domain,
            "SELECT Name, Version, Vendor FROM Win32_InstalledStoreProgram",
            timeout,
        )
        for row in store_rows[:limit]:
            name = row.get("Name", "").strip()
            if name:
                packages.append(
                    SoftwarePackage(
                        name=name,
                        version=row.get("Version") or None,
                        vendor=row.get("Vendor") or None,
                        source="wmi",
                    )
                )

        patch_rows = _wmi_query(
            host,
            username,
            password,
            domain,
            "SELECT Caption, Description, HotFixID FROM Win32_QuickFixEngineering",
            min(timeout, 10.0),
        )
        for row in patch_rows:
            if len(packages) >= limit:
                break
            caption = row.get("Caption") or row.get("HotFixID") or row.get("Description")
            if caption:
                packages.append(
                    SoftwarePackage(
                        name=caption.strip(),
                        version=row.get("HotFixID") or None,
                        vendor="Microsoft",
                        source="wmi",
                    )
                )

        if include_slow_product_query and len(packages) < limit:
            product_rows = _wmi_query(
                host,
                username,
                password,
                domain,
                "SELECT Name, Version, Vendor FROM Win32_Product",
                min(timeout * 2, 30.0),
            )
            for row in product_rows:
                if len(packages) >= limit:
                    break
                name = row.get("Name", "").strip()
                if name:
                    packages.append(
                        SoftwarePackage(
                            name=name,
                            version=row.get("Version") or None,
                            vendor=row.get("Vendor") or None,
                            source="wmi",
                        )
                    )
    except ImportError:
        logger.warning("impacket não instalado — inventário WMI indisponível")
    except Exception as exc:
        logger.debug("WMI software collection failed for %s: %s", host, exc)

    return packages[:limit]


def collect_device_software(
    host: str,
    *,
    use_snmp: bool = True,
    use_wmi: bool = True,
    snmp_community: str | None = None,
    include_slow_wmi: bool = False,
) -> SoftwareInventory:
    inventory = SoftwareInventory(collected_at=datetime.now(UTC).isoformat())
    seen: set[str] = set()

    if use_snmp:
        try:
            for pkg in collect_software_snmp(host, snmp_community):
                key = pkg.name.lower()
                if key not in seen:
                    seen.add(key)
                    inventory.packages.append(pkg)
            if any(p.source == "snmp" for p in inventory.packages):
                inventory.sources.append("snmp")
        except Exception as exc:
            inventory.error = f"SNMP: {exc}"

    if use_wmi and wmi_credentials_configured():
        try:
            for pkg in collect_software_wmi(host, include_slow_product_query=include_slow_wmi):
                key = pkg.name.lower()
                if key not in seen:
                    seen.add(key)
                    inventory.packages.append(pkg)
            if any(p.source == "wmi" for p in inventory.packages):
                if "wmi" not in inventory.sources:
                    inventory.sources.append("wmi")
        except Exception as exc:
            err = f"WMI: {exc}"
            inventory.error = f"{inventory.error}; {err}" if inventory.error else err

    return inventory

