import asyncio
import time


async def check_tcp(host_port: str, timeout: int = 3) -> tuple[bool, float]:
    if ":" in host_port:
        host, port_str = host_port.rsplit(":", 1)
        port = int(port_str)
    else:
        host, port = host_port, 80

    start = time.perf_counter()
    try:
        _, writer = await asyncio.wait_for(asyncio.open_connection(host, port), timeout=timeout)
        writer.close()
        await writer.wait_closed()
        return True, round((time.perf_counter() - start) * 1000, 2)
    except Exception:
        return False, round((time.perf_counter() - start) * 1000, 2)

"""OpenTelemetry tracing setup for SentinelAI."""

import logging

from app.config import settings

logger = logging.getLogger(__name__)
_tracer = None


def setup_tracing() -> None:
    global _tracer
    if not settings.otel_enabled:
        return

    try:
        from opentelemetry import trace
        from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter
        from opentelemetry.sdk.resources import Resource
        from opentelemetry.sdk.trace import TracerProvider
        from opentelemetry.sdk.trace.export import BatchSpanProcessor

        resource = Resource.create(
            {
                "service.name": "sentinelai-api",
                "service.version": "1.4.0",
                "deployment.region": settings.api_region,
            }
        )
        provider = TracerProvider(resource=resource)
        exporter = OTLPSpanExporter(endpoint=f"{settings.otel_exporter_endpoint.rstrip('/')}/v1/traces")
        provider.add_span_processor(BatchSpanProcessor(exporter))
        trace.set_tracer_provider(provider)
        _tracer = trace.get_tracer("sentinelai")
        logger.info("OpenTelemetry tracing enabled → %s", settings.otel_exporter_endpoint)
    except Exception as exc:
        logger.warning("OpenTelemetry setup failed: %s", exc)


def instrument_fastapi(app) -> None:
    if not settings.otel_enabled:
        return
    try:
        from opentelemetry.instrumentation.fastapi import FastAPIInstrumentor

        FastAPIInstrumentor.instrument_app(app)
    except Exception as exc:
        logger.warning("FastAPI OTEL instrumentation failed: %s", exc)


def get_tracing_status() -> dict:
    return {
        "enabled": settings.otel_enabled,
        "exporter_endpoint": settings.otel_exporter_endpoint if settings.otel_enabled else None,
        "jaeger_ui": settings.jaeger_ui_url or None,
    }

