        raise RuntimeError("PyYAML não instalado — adicione PyYAML às dependências") from exc
    return yaml


def parse_playbook_yaml(raw: str, *, default_slug: str | None = None) -> dict[str, Any]:
    yaml = _require_yaml()
    data = yaml.safe_load(raw) or {}
    if not isinstance(data, dict):
        raise ValueError("Playbook YAML deve ser um mapping na raiz")

    slug = str(data.get("playbook") or data.get("slug") or default_slug or "").strip()
    if not slug:
        raise ValueError("Playbook YAML sem campo playbook/slug")

    actions = data.get("actions") or []
    if not isinstance(actions, list):
        raise ValueError("Campo actions deve ser uma lista")

    raw_steps = data.get("steps")
    if not actions and isinstance(raw_steps, list):
        for step in raw_steps:
            if isinstance(step, dict):
                actions.append(step)
            elif isinstance(step, str):
                actions.append(step)

    steps = raw_steps
    if not isinstance(steps, list) or not steps:
        steps = _steps_from_actions(actions)

    triggers = data.get("triggers") or []
    if isinstance(triggers, str):
        triggers = [triggers]
    if not isinstance(triggers, list):
        triggers = []

    return {
        "slug": slug,
        "name": str(data.get("name") or slug),
        "description": str(data.get("description") or ""),
        "triggers": [str(t) for t in triggers],
        "enabled": bool(data.get("enabled", True)),
        "steps": _normalize_steps(steps),
        "actions": actions,
        "source": data.get("source") or "yaml",
    }


def _normalize_steps(steps: list[Any]) -> list[dict[str, str]]:
    out: list[dict[str, str]] = []
    for i, step in enumerate(steps):
        if isinstance(step, dict):
            sid = str(step.get("id") or f"step-{i + 1}")
            label = str(step.get("label") or step.get("name") or sid)
            out.append({"id": sid, "label": label})
        elif isinstance(step, str):
            out.append({"id": f"step-{i + 1}", "label": step})
    return out


def _steps_from_actions(actions: list[Any]) -> list[dict[str, str]]:
    steps: list[dict[str, str]] = []
    for i, action in enumerate(actions):
        kind, _ = normalize_action(action)
        steps.append({"id": f"{kind}-{i + 1}", "label": f"Ação: {kind}"})
    if not steps:
        steps = [{"id": "noop", "label": "Sem ações"}]
    return steps


def normalize_action(action: Any) -> tuple[str, Any]:
    """Convert YAML action item to (kind, params).

    Supports:
      - ping: all
      - { ping: all }
      - { reopen_inactive: { limit: 10 } }
      - { action: log, message: hi }
    """
    if isinstance(action, str):
        return action.strip().lower(), True
    if not isinstance(action, dict):
        raise ValueError(f"Ação inválida: {action!r}")
    if "action" in action:
        kind = str(action["action"]).strip().lower()
        params = {k: v for k, v in action.items() if k != "action"}
        return kind, params or True
    if len(action) == 1:
        kind, params = next(iter(action.items()))
        return str(kind).strip().lower(), params
    raise ValueError(f"Ação ambígua (use um único tipo): {action!r}")


def load_builtin_playbooks() -> list[dict[str, Any]]:
    if not PLAYBOOKS_DIR.is_dir():
        return []
    loaded: list[dict[str, Any]] = []
    for path in sorted(PLAYBOOKS_DIR.glob("*.yaml")) + sorted(PLAYBOOKS_DIR.glob("*.yml")):
        try:
            pb = parse_playbook_yaml(path.read_text(encoding="utf-8"), default_slug=path.stem)
            pb["source"] = "builtin"
            loaded.append(pb)
        except Exception as exc:
            logger.warning("Falha ao carregar playbook %s: %s", path.name, exc)
    return loaded


def load_custom_playbooks(session: Session) -> list[dict[str, Any]]:
    from app.models import CustomPlaybook

    rows = session.execute(select(CustomPlaybook).order_by(CustomPlaybook.slug)).scalars().all()
    loaded: list[dict[str, Any]] = []
    for row in rows:
        try:
            pb = parse_playbook_yaml(row.yaml_content, default_slug=row.slug)
            pb["slug"] = row.slug
            pb["name"] = row.name or pb["name"]
            pb["description"] = row.description or pb["description"]
            pb["enabled"] = bool(row.enabled)
            pb["source"] = row.marketplace_source or "custom"
            loaded.append(pb)
        except Exception as exc:
            logger.warning("Custom playbook %s inválido: %s", row.slug, exc)
    return loaded


def resolve_playbook(session: Session | None, slug: str) -> dict[str, Any] | None:
    """Resolve by slug. Custom DB (enabled) wins over builtin file."""
    if session is not None:
        for pb in load_custom_playbooks(session):
            if pb["slug"] == slug and pb.get("enabled", True):
                return pb
    for pb in load_builtin_playbooks():
        if pb["slug"] == slug and pb.get("enabled", True):
            return pb
    return None


def list_all_playbooks(session: Session | None = None) -> list[dict[str, Any]]:
    by_slug: dict[str, dict[str, Any]] = {}
    for pb in load_builtin_playbooks():
        by_slug[pb["slug"]] = pb
    if session is not None:
        for pb in load_custom_playbooks(session):
            by_slug[pb["slug"]] = pb
    # Public list omits raw actions (API schema); keep them for engine
    return sorted(by_slug.values(), key=lambda p: p["slug"])

"""HashiCorp Vault integration (KV v2 secrets)."""

import logging

import httpx

from app.config import settings

logger = logging.getLogger(__name__)


def get_vault_status() -> dict:
    if not settings.vault_enabled:
        return {"enabled": False, "status": "disabled"}
    try:
        with httpx.Client(timeout=5) as client:
            resp = client.get(
                f"{settings.vault_addr.rstrip('/')}/v1/sys/health",
                headers=_headers(),
            )
        data = resp.json() if resp.content else {}
        return {
            "enabled": True,
            "status": "ok" if resp.status_code in (200, 429, 472, 473) else "error",
            "initialized": data.get("initialized"),
            "sealed": data.get("sealed"),
            "version": data.get("version"),
        }
    except Exception as exc:
        return {"enabled": True, "status": "error", "message": str(exc)}


def read_secret(path: str) -> dict | None:
    if not settings.vault_enabled:
        return None
    try:
        mount = settings.vault_mount.strip("/")
        url = f"{settings.vault_addr.rstrip('/')}/v1/{mount}/data/{path.lstrip('/')}"
        with httpx.Client(timeout=5) as client:
            resp = client.get(url, headers=_headers())
        if resp.status_code != 200:
            return None
        return resp.json().get("data", {}).get("data", {})
    except Exception as exc:
        logger.debug("Vault read failed: %s", exc)
        return None


def resolve_secret(key: str, fallback: str = "") -> str:
    """Read secret from Vault or fall back to settings/env."""
    if settings.vault_enabled:
        data = read_secret(settings.vault_secret_path)
        if data and key in data:
            return str(data[key])
    return fallback


def _headers() -> dict:
    headers = {}
    if settings.vault_token:
        headers["X-Vault-Token"] = settings.vault_token
    return headers

