"""MFA TOTP (Google Authenticator / Authy)."""

from __future__ import annotations

import base64
import io

import pyotp
import qrcode

from app.services.secret_crypto import decrypt_secret, encrypt_secret


ISSUER = "SentinelAI"


def generate_totp_secret() -> str:
    return pyotp.random_base32()


def build_otpauth_url(username: str, secret: str) -> str:
    return pyotp.TOTP(secret).provisioning_uri(name=username, issuer_name=ISSUER)


def qr_png_base64(otpauth_url: str) -> str:
    img = qrcode.make(otpauth_url)
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    return base64.b64encode(buf.getvalue()).decode("ascii")


def encrypt_mfa_secret(secret: str) -> str:
    enc = encrypt_secret(secret)
    if not enc:
        raise ValueError("Falha ao cifrar segredo MFA")
    return enc


def decrypt_mfa_secret(stored: str | None) -> str | None:
    if not stored:
        return None
    return decrypt_secret(stored)


def verify_totp(secret: str, code: str, valid_window: int = 1) -> bool:
    cleaned = "".join(ch for ch in str(code).strip() if ch.isdigit())
    if len(cleaned) < 6:
        return False
    totp = pyotp.TOTP(secret)
    return bool(totp.verify(cleaned, valid_window=valid_window))

from datetime import UTC, datetime, timedelta

from sqlalchemy import func, select
from sqlalchemy.orm import Session

from app.models import Device, Metric, Monitor, MonitorType


def monitor_due(session: Session, monitor: Monitor) -> bool:
    latest = session.execute(
        select(Metric.recorded_at)
        .where(Metric.monitor_id == monitor.id)
        .order_by(Metric.recorded_at.desc())
        .limit(1)
    ).scalar_one_or_none()
    if latest is None:
        return True
    if latest.tzinfo is None:
        latest = latest.replace(tzinfo=UTC)
    return datetime.now(UTC) - latest >= timedelta(seconds=monitor.interval_seconds)


