from app.config import settings
from app.dependencies import ALGORITHM, get_password_hash
from app.models import Organization, User, UserRole

logger = logging.getLogger(__name__)

_DISCOVERY_CACHE: dict[str, Any] = {"at": 0.0, "data": None}
_STATE_PURPOSE = "oidc_pkce"


def oidc_configured() -> bool:
    return bool(
        settings.oidc_enabled
        and (settings.oidc_issuer or "").strip()
        and (settings.oidc_client_id or "").strip()
        and (settings.oidc_redirect_uri or "").strip()
    )


def oidc_status() -> dict[str, Any]:
    enabled = oidc_configured()
    return {
        "enabled": enabled,
        "issuer": (settings.oidc_issuer or "").rstrip("/") if enabled else None,
        "client_id": settings.oidc_client_id if enabled else None,
        "scopes": settings.oidc_scopes,
        "redirect_uri": settings.oidc_redirect_uri if enabled else None,
        "login_path": "/api/auth/oidc/login" if enabled else None,
        "logout_path": "/api/auth/oidc/logout" if enabled else None,
        "skip_local_mfa": bool(settings.oidc_skip_local_mfa),
        "default_role": settings.oidc_default_role,
        "default_org_slug": settings.oidc_default_org_slug,
    }


def _b64url(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def generate_pkce_pair() -> tuple[str, str]:
    verifier = _b64url(secrets.token_bytes(32))
    challenge = _b64url(hashlib.sha256(verifier.encode("ascii")).digest())
    return verifier, challenge


def create_oidc_state(*, code_verifier: str, nonce: str) -> str:
    return jwt.encode(
        {
            "purpose": _STATE_PURPOSE,
            "cv": code_verifier,
            "nonce": nonce,
            "exp": datetime.now(UTC) + timedelta(minutes=10),
        },
        settings.secret_key,
        algorithm=ALGORITHM,
    )


def parse_oidc_state(state: str) -> dict[str, str]:
    try:
        payload = jwt.decode(state, settings.secret_key, algorithms=[ALGORITHM])
    except JWTError as exc:
        raise ValueError("state OIDC inválido ou expirado") from exc
    if payload.get("purpose") != _STATE_PURPOSE:
        raise ValueError("state OIDC com purpose inválido")
    cv = payload.get("cv")
    nonce = payload.get("nonce")
    if not cv or not nonce:
        raise ValueError("state OIDC incompleto")
    return {"code_verifier": str(cv), "nonce": str(nonce)}


async def fetch_oidc_discovery() -> dict[str, Any]:
    issuer = settings.oidc_issuer.rstrip("/")
    import time

    now = time.monotonic()
    if _DISCOVERY_CACHE["data"] and now - float(_DISCOVERY_CACHE["at"]) < 300:
        return _DISCOVERY_CACHE["data"]  # type: ignore[return-value]

    url = f"{issuer}/.well-known/openid-configuration"
    async with httpx.AsyncClient(timeout=10.0) as client:
        resp = await client.get(url)
        resp.raise_for_status()
        data = resp.json()
    for key in ("authorization_endpoint", "token_endpoint"):
        if not data.get(key):
            raise RuntimeError(f"OIDC discovery sem {key}")
    _DISCOVERY_CACHE["data"] = data
    _DISCOVERY_CACHE["at"] = now
    return data


def clear_discovery_cache() -> None:
    _DISCOVERY_CACHE["data"] = None
    _DISCOVERY_CACHE["at"] = 0.0


async def build_authorize_url() -> tuple[str, str]:
    """Returns (authorize_url, state)."""
    if not oidc_configured():
        raise RuntimeError("OIDC não configurado")
    discovery = await fetch_oidc_discovery()
    verifier, challenge = generate_pkce_pair()
    nonce = _b64url(secrets.token_bytes(16))
    state = create_oidc_state(code_verifier=verifier, nonce=nonce)
    params = {
        "response_type": "code",
        "client_id": settings.oidc_client_id,
        "redirect_uri": settings.oidc_redirect_uri,
        "scope": settings.oidc_scopes,
        "state": state,
        "nonce": nonce,
        "code_challenge": challenge,
        "code_challenge_method": "S256",
    }
    url = f"{discovery['authorization_endpoint']}?{urlencode(params)}"
    return url, state


async def exchange_code(*, code: str, code_verifier: str) -> dict[str, Any]:
    discovery = await fetch_oidc_discovery()
    data = {
        "grant_type": "authorization_code",
        "code": code,
        "redirect_uri": settings.oidc_redirect_uri,
        "client_id": settings.oidc_client_id,
        "code_verifier": code_verifier,
    }
    if settings.oidc_client_secret:
        data["client_secret"] = settings.oidc_client_secret
    async with httpx.AsyncClient(timeout=15.0) as client:
        resp = await client.post(
            discovery["token_endpoint"],
            data=data,
            headers={"Accept": "application/json"},
        )
        if resp.status_code >= 400:
            logger.warning("OIDC token error %s: %s", resp.status_code, resp.text[:300])
            raise RuntimeError("Falha no token endpoint OIDC")
        return resp.json()


async def fetch_userinfo(access_token: str) -> dict[str, Any]:
    discovery = await fetch_oidc_discovery()
    endpoint = discovery.get("userinfo_endpoint")
    if not endpoint:
        return {}
    async with httpx.AsyncClient(timeout=10.0) as client:
        resp = await client.get(
            endpoint,
            headers={"Authorization": f"Bearer {access_token}", "Accept": "application/json"},
        )
        if resp.status_code >= 400:
            logger.warning("OIDC userinfo error %s", resp.status_code)
            return {}
        return resp.json()


def claims_from_id_token(id_token: str | None) -> dict[str, Any]:
    if not id_token:
        return {}
    try:
        return jwt.get_unverified_claims(id_token)
    except Exception:
        return {}


def merge_claims(id_claims: dict[str, Any], userinfo: dict[str, Any]) -> dict[str, Any]:
    merged = dict(id_claims)
    merged.update({k: v for k, v in userinfo.items() if v is not None})
    return merged


def _sanitize_username(raw: str) -> str:
    cleaned = re.sub(r"[^a-zA-Z0-9._@+-]", "-", (raw or "").strip())[:100]
    return cleaned or f"oidc-{secrets.token_hex(4)}"


