logger = logging.getLogger(__name__)


def compute_plugins_checksum(plugins: list[dict]) -> str:
    payload = json.dumps(plugins, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def compute_registry_signature(checksum: str, secret: str) -> str:
    return hmac.new(secret.encode("utf-8"), checksum.encode("utf-8"), hashlib.sha256).hexdigest()


def verify_signed_registry(data: dict) -> tuple[list[dict], bool, str | None]:
    """Validate signed registry manifest. Returns (plugins, verified, error)."""
    if isinstance(data, list):
        return data, not settings.marketplace_registry_secret, None

    plugins = data.get("plugins", [])
    if not plugins:
        return [], False, "Registry vazio"

    checksum = data.get("checksum")
    signature = data.get("signature")
    if not checksum:
        return plugins, False, "Checksum ausente no manifest"

    expected = compute_plugins_checksum(plugins)
    if not hmac.compare_digest(expected, checksum):
        return plugins, False, "Checksum inválido — registry pode estar corrompido"

    secret = settings.marketplace_registry_secret
    if secret:
        if not signature:
            return plugins, False, "Assinatura HMAC ausente"
        expected_sig = compute_registry_signature(checksum, secret)
        if not hmac.compare_digest(expected_sig, signature):
            return plugins, False, "Assinatura HMAC inválida"
        return plugins, True, None

    return plugins, True, None


def list_regions(session: Session) -> list[dict]:
    nodes = session.execute(select(HaNode).order_by(HaNode.region, HaNode.last_heartbeat.desc())).scalars().all()
    regions: dict[str, dict] = {}
    for node in nodes:
        reg = node.region or "default"
        if reg not in regions:
            regions[reg] = {"region": reg, "nodes": [], "healthy_count": 0, "active_active": settings.multi_region_enabled}
        entry = {
            "node_id": node.node_id,
            "role": node.role,
            "hostname": node.hostname,
            "version": node.version,
            "is_healthy": node.is_healthy,
            "last_heartbeat": node.last_heartbeat.isoformat(),
        }
        regions[reg]["nodes"].append(entry)
        if node.is_healthy:
            regions[reg]["healthy_count"] += 1

    result = list(regions.values())
    for r in result:
        r["preferred"] = r["region"] == settings.api_region
    return result


def route_to_region(session: Session, region: str | None = None) -> dict:
    target = region or settings.api_region
    regions = list_regions(session)
    match = next((r for r in regions if r["region"] == target), None)
    if match and match["healthy_count"] > 0:
        node = next((n for n in match["nodes"] if n["is_healthy"]), match["nodes"][0] if match["nodes"] else None)
        return {
            "region": target,
            "routed": True,
            "node_id": node["node_id"] if node else None,
            "strategy": "active-active" if settings.multi_region_enabled else "single-region",
        }
    fallback = next((r for r in regions if r["healthy_count"] > 0), None)
    if fallback:
        return {
            "region": fallback["region"],
            "routed": True,
            "fallback": True,
            "strategy": "failover",
        }
    return {"region": target, "routed": False, "strategy": "none"}


