"""Event bus Redis pub/sub — workers e API partilham o mesmo canal SSE."""

from __future__ import annotations

import asyncio
import json
import logging
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import Any

from app.config import settings

logger = logging.getLogger(__name__)

CHANNEL = "sentinelai:realtime"
HISTORY_KEY = "sentinelai:realtime:history"
MAX_EVENTS = 500


@dataclass
class RealtimeEvent:
    type: str
    payload: dict[str, Any] = field(default_factory=dict)
    created_at: str = field(default_factory=lambda: datetime.now(UTC).isoformat())

    def to_dict(self) -> dict[str, Any]:
        return {"type": self.type, "payload": self.payload, "created_at": self.created_at}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> RealtimeEvent:
        return cls(
            type=str(data.get("type") or "unknown"),
            payload=data.get("payload") if isinstance(data.get("payload"), dict) else {},
            created_at=str(data.get("created_at") or datetime.now(UTC).isoformat()),
        )


class RealtimeEventBus:
    def __init__(self) -> None:
        self._subscribers: set[asyncio.Queue[RealtimeEvent]] = set()
        self._listener_task: asyncio.Task[None] | None = None
        self._lock = asyncio.Lock()

    def _sync_redis(self):
        import redis

        return redis.from_url(settings.redis_url, decode_responses=True, socket_connect_timeout=2)

    def publish(self, event_type: str, payload: dict[str, Any] | None = None) -> None:
        event = RealtimeEvent(type=event_type, payload=payload or {})
        raw = json.dumps(event.to_dict())
        try:
            client = self._sync_redis()
            pipe = client.pipeline()
            pipe.publish(CHANNEL, raw)
            pipe.lpush(HISTORY_KEY, raw)
            pipe.ltrim(HISTORY_KEY, 0, MAX_EVENTS - 1)
            pipe.execute()
        except Exception:
            logger.exception("Redis publish failed; fan-out local only")
            self._fanout(event)

    def recent(self, limit: int = 20) -> list[dict[str, Any]]:
        try:
            client = self._sync_redis()
            items = client.lrange(HISTORY_KEY, 0, max(limit, 1) - 1)
            parsed: list[dict[str, Any]] = []
            for item in reversed(items):
                try:
                    parsed.append(json.loads(item))
                except json.JSONDecodeError:
                    continue
            return parsed
        except Exception:
            logger.exception("Redis history read failed")
            return []

    def _fanout(self, event: RealtimeEvent) -> None:
        for queue in list(self._subscribers):
            try:
                queue.put_nowait(event)
            except asyncio.QueueFull:
                pass

    async def _listen_redis(self) -> None:
        import redis.asyncio as aioredis

        client = aioredis.from_url(settings.redis_url, decode_responses=True)
        pubsub = client.pubsub()
        await pubsub.subscribe(CHANNEL)
        try:
            while True:
                message = await pubsub.get_message(ignore_subscribe_messages=True, timeout=1.0)
                if message and message.get("type") == "message":
                    data_raw = message.get("data")
                    if not isinstance(data_raw, str):
                        continue
                    try:
                        data = json.loads(data_raw)
                    except json.JSONDecodeError:
                        continue
                    self._fanout(RealtimeEvent.from_dict(data))
                else:
                    await asyncio.sleep(0.05)
        except asyncio.CancelledError:
            raise
        finally:
            try:
                await pubsub.unsubscribe(CHANNEL)
                await pubsub.aclose()
            except Exception:
                pass
            try:
                await client.aclose()
            except Exception:
                pass

    async def ensure_listener(self) -> None:
        async with self._lock:
            if self._listener_task and not self._listener_task.done():
                return
            self._listener_task = asyncio.create_task(self._listen_redis(), name="realtime-redis-listener")

    async def subscribe(self) -> asyncio.Queue[RealtimeEvent]:
        await self.ensure_listener()
        queue: asyncio.Queue[RealtimeEvent] = asyncio.Queue(maxsize=64)
        self._subscribers.add(queue)
        return queue

    def unsubscribe(self, queue: asyncio.Queue[RealtimeEvent]) -> None:
        self._subscribers.discard(queue)

    async def shutdown(self) -> None:
        task = self._listener_task
        self._listener_task = None
        if task and not task.done():
            task.cancel()
            try:
                await task
            except asyncio.CancelledError:
                pass
        self._subscribers.clear()


event_bus = RealtimeEventBus()

"""Criptografia local de secrets (Fernet derivado de SECRET_KEY)."""

from __future__ import annotations

import base64
import hashlib
import logging

from cryptography.fernet import Fernet, InvalidToken

from app.config import settings

logger = logging.getLogger(__name__)

_ENC_PREFIX = "enc:v1:"


def _fernet() -> Fernet:
    digest = hashlib.sha256(settings.secret_key.encode("utf-8")).digest()
    return Fernet(base64.urlsafe_b64encode(digest))


def encrypt_secret(value: str | None) -> str | None:
    if value is None:
        return None
    text = str(value)
    if not text:
        return ""
    if text.startswith(_ENC_PREFIX):
        return text
    token = _fernet().encrypt(text.encode("utf-8")).decode("ascii")
    return f"{_ENC_PREFIX}{token}"


def decrypt_secret(value: str | None) -> str | None:
    if value is None:
        return None
    text = str(value)
    if not text:
        return ""
    if not text.startswith(_ENC_PREFIX):
        return text
    token = text[len(_ENC_PREFIX) :]
    try:
        return _fernet().decrypt(token.encode("ascii")).decode("utf-8")
    except (InvalidToken, ValueError, TypeError) as exc:
        logger.warning("Falha ao descriptografar secret: %s", type(exc).__name__)
        return None


def is_encrypted(value: str | None) -> bool:
    return bool(value and str(value).startswith(_ENC_PREFIX))

"""Política de secrets e senhas (Fase 1.3)."""

from __future__ import annotations

from datetime import UTC, datetime
from typing import Any

WEAK_SECRETS = {
    "change-me-in-production",
    "change-me-in-production-use-openssl-rand-hex-32",
    "secret",
    "changeme",
}

WEAK_PASSWORDS = {
    "admin123",
    "admin",
    "password",
    "password123",
    "123456",
    "12345678",
    "sentinel",
    "sentinelai",
}


def is_weak_secret(value: str) -> bool:
    cleaned = (value or "").strip()
    return not cleaned or cleaned in WEAK_SECRETS or len(cleaned) < 32


def is_weak_password(value: str) -> bool:
    cleaned = (value or "").strip()
    return not cleaned or cleaned.lower() in WEAK_PASSWORDS or len(cleaned) < 8


def validate_new_password(password: str, *, username: str | None = None) -> None:
    if is_weak_password(password):
        raise ValueError("Senha fraca — use pelo menos 8 caracteres e evite senhas comuns")
    if username and password.lower() == username.lower():
        raise ValueError("A senha não pode ser igual ao nome de utilizador")


def validate_runtime_secrets(*, app_env: str, secret_key: str, admin_password: str) -> None:
    env = (app_env or "development").strip().lower()
    if env in {"development", "dev", "local", "test"}:
        return
    if is_weak_secret(secret_key):
        raise RuntimeError(
            "SECRET_KEY fraco ou curto — defina um valor forte (≥32 chars) quando APP_ENV≠development"
        )
    if is_weak_password(admin_password):
        raise RuntimeError(
            "ADMIN_PASSWORD fraco — proibido fora de development (troque admin123)"
        )


def password_is_expired(user: Any, *, max_age_days: int) -> bool:
    """True se a senha ultrapassou a idade máxima (política mensal)."""
    if max_age_days <= 0:
        return False
    changed_at = getattr(user, "password_changed_at", None)
    if changed_at is None:
        return False
    if changed_at.tzinfo is None:
        changed_at = changed_at.replace(tzinfo=UTC)
    age_days = (datetime.now(UTC) - changed_at).days
    return age_days >= max_age_days


def password_change_required(user: Any, *, max_age_days: int) -> bool:
    """
    Troca obrigatória apenas quando:
    - flag must_change_password (1.º login / senha default), ou
    - senha com idade >= password_max_age_days (default 30).
    Nunca reabrir só porque a senha digitada parece fraca.
    """
    if getattr(user, "is_ldap", False) or getattr(user, "is_oidc", False):
        return False
    if bool(getattr(user, "must_change_password", False)):
        return True
    return password_is_expired(user, max_age_days=max_age_days)

import hashlib
import re
from datetime import UTC, datetime

from sqlalchemy import text
