"""mTLS / certificado cliente para rotas agent (Sprint 15.7)."""

from __future__ import annotations

import hashlib

from fastapi import HTTPException, Request

from app.config import settings


def _client_cert_sha256(request: Request) -> str | None:
    pin = (request.headers.get("X-ZionVM-Agent-Cert-SHA256") or "").strip().lower()
    if pin:
        return pin.replace(":", "")
    peercert = request.scope.get("peercert")
    if not peercert:
        return None
    try:
        import ssl

        der = ssl.DER_cert_to_PEM_cert(peercert)  # type: ignore[arg-type]
        if isinstance(der, str):
            body = der.encode("utf-8")
        else:
            return None
    except Exception:
        return None
    return hashlib.sha256(body).hexdigest()


def assert_agent_mtls(request: Request) -> None:
    """Exige verificação TLS no edge ou header de pin quando activado."""
    if not getattr(settings, "zionvm_agent_mtls_required", False):
        return

    verify = (request.headers.get("X-SSL-Client-Verify") or "").upper()
    if verify == "SUCCESS":
        return

    expected_pin = (getattr(settings, "zionvm_agent_mtls_cert_sha256", "") or "").strip().lower()
    if expected_pin:
        got = _client_cert_sha256(request)
        if got and got == expected_pin.replace(":", ""):
            return

    raise HTTPException(
        status_code=403,
        detail="Agent mTLS obrigatório (nginx client cert ou X-ZionVM-Agent-Cert-SHA256)",
    )

