from __future__ import annotations

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models import User
from app.models.zionvm import ZionvmGlobalPolicy, ZionvmVm
from app.services.zionvm_service import map_zionvm_role

_ROLE_RANK = {"zionvm_viewer": 0, "zionvm_operator": 1, "zionvm_admin": 2}


def assert_console_policy_allowed(session: Session, user: User, vm: ZionvmVm) -> None:
    role = map_zionvm_role(user)
    policies = (
        session.execute(select(ZionvmGlobalPolicy).where(ZionvmGlobalPolicy.enabled.is_(True)))
        .scalars()
        .all()
    )
    for pol in policies:
        spec = dict(pol.spec or {})
        if not spec.get("console_policy"):
            continue
        min_role = str(spec.get("console_min_role") or "zionvm_operator")
        need = _ROLE_RANK.get(min_role, 1)
        have = _ROLE_RANK.get(role, 0)
        if have < need:
            raise PermissionError(
                f"Política '{pol.name}': console requer role {min_role} (tem {role})"
            )
        blocked_vmids = spec.get("console_blocked_vmids") or []
        if vm.vmid in blocked_vmids or vm.id in blocked_vmids:
            raise PermissionError(f"Política '{pol.name}': console bloqueado para VM {vm.vmid}")
        if spec.get("console_production_only_operator") and (vm.extra or {}).get("production"):
            if role != "zionvm_admin":
                raise PermissionError(f"Política '{pol.name}': VM produção — só admin abre console")

