def narrate_lifecycle_success(task: ZionvmTask, result: dict) -> None:
    payload = dict(task.result or {})
    t = task.task_type
    if t == "vm.create":
        storage = payload.get("storage_name") or payload.get("images_root") or "pool"
        disk = payload.get("disk_gb") or "?"
        vmid = result.get("vmid") or payload.get("vmid")
        append_task_narrative(
            task,
            f"Disco {disk}GB provisionado em {storage}. Domain zvm-{vmid} definido no hypervisor.",
        )
        if payload.get("iso"):
            append_task_narrative(task, f"ISO {payload.get('iso')} associada ao CD-ROM.")
        if payload.get("vlan_tag"):
            append_task_narrative(task, f"Rede bridge {payload.get('bridge')} VLAN {payload.get('vlan_tag')}.")
        elif payload.get("bridge"):
            append_task_narrative(task, f"Rede bridge {payload.get('bridge')}.")
    elif t == "vm.start":
        vnc = (result.get("console") or {}).get("vnc_port") or result.get("vnc_port")
        if vnc:
            append_task_narrative(task, f"QEMU iniciado — console VNC na porta {vnc}.")
        else:
            append_task_narrative(task, "QEMU iniciado.")
    elif t == "vm.stop":
        append_task_narrative(task, "Guest parada (shutdown/destroy no hypervisor).")
    elif t == "vm.restart":
        append_task_narrative(task, "Guest reiniciada.")
    elif t == "vm.delete":
        if result.get("destroyed"):
            append_task_narrative(task, "VM removida do hypervisor e discos apagados.")
        else:
            append_task_narrative(task, "VM marcada como removida (soft delete).")
    elif t == "vm.clone":
        append_task_narrative(
            task,
            f"Clone concluído — nova VM vmid {result.get('vmid')} (origem hypervisor zvm-{payload.get('source_vmid') or '?'})",
        )
    elif t == "vm.snapshot":
        append_task_narrative(
            task,
            f"Snapshot libvirt '{result.get('libvirt_snapshot') or result.get('name')}' criado.",
        )
    elif t == "vm.snapshot_rollback":
        append_task_narrative(task, f"Rollback para snapshot '{result.get('rolled_back_to')}'.")
    elif t == "cluster.cold_migrate":
        append_task_narrative(
            task,
            f"Migração offline concluída — VM no node {result.get('to_node_id')} "
            f"(modo {result.get('mode') or 'cold'}, driver {result.get('hypervisor') or 'stub'}).",
        )
    elif t == "cluster.live_migrate":
        append_task_narrative(
            task,
            f"Live migrate concluído — guest em execução no node {result.get('to_node_id')} "
            f"(URI {result.get('dest_uri') or 'n/a'}).",
        )
    elif t == "lxc.create":
        append_task_narrative(
            task,
            f"Container CT {result.get('vmid')} ({result.get('name') or payload.get('name')}) "
            f"criado via {result.get('backend') or 'agent'}.",
        )
    elif t == "lxc.start":
        append_task_narrative(task, f"Container {result.get('container_id')} em execução.")
    elif t == "lxc.stop":
        append_task_narrative(task, f"Container {result.get('container_id')} parado.")
    elif t == "lxc.delete":
        append_task_narrative(task, "Container removido do hypervisor e marcado como apagado.")

"""ZionXDR S6 — contexto de incidente para Copilot."""

from __future__ import annotations

from typing import Any

from sqlalchemy.orm import Session

from app.services.zionxdr_evidence import get_detection_by_event, get_evidence
from app.services.zionxdr_nms import nms_context
from app.services.zionxdr_service import get_endpoint


def _suggest_playbook(severity: str | None, telemetry_source: str | None) -> str:
    if telemetry_source == "memory":
        return "zionxdr-collect-evidence"
    s = (severity or "").lower()
    if s == "critical":
        return "zionxdr-quarantine-file"
    return "zionxdr-collect-evidence"


def build_incident_context(
    session: Session,
    *,
    event_id: int | None = None,
    endpoint_id: int | None = None,
    fingerprint: str | None = None,
) -> dict[str, Any]:
    if event_id is not None:
        det = get_detection_by_event(session, event_id)
        if not det:
            raise ValueError("Evento não indexado como detecção ZionXDR")
        endpoint_id = int(det["endpoint_id"])
        fingerprint = str(det["fingerprint"])
        snapshot = det.get("snapshot") or {}
    elif endpoint_id is not None and fingerprint:
        ev = get_evidence(session, endpoint_id, fingerprint)
        snapshot = ev.get("alert") or {}
    else:
        raise ValueError("Informe event_id ou endpoint_id+fingerprint")

    ep = get_endpoint(session, endpoint_id)
    nms = nms_context(session, ep) if not ep.is_local else {"device": None, "department_path": []}
    sev = (snapshot.get("severity") or "unknown") if isinstance(snapshot, dict) else "unknown"
    src = snapshot.get("telemetry_source") if isinstance(snapshot, dict) else None
    slug = _suggest_playbook(sev, src)
    proc = (snapshot.get("process") or {}) if isinstance(snapshot, dict) else {}
    hints = [
        f"Regra {snapshot.get('rule_id')} — severidade {sev}.",
        "Revise modo enforcement antes de ações destrutivas (HITL obrigatório).",
    ]
    if src:
        hints.append(f"Origem telemetria: {src}.")
    if nms.get("department_path"):
        dept = " › ".join(d["name"] for d in nms["department_path"])
        hints.append(f"Contexto NMS: {dept}.")

    summary = (
        f"{ep.name}: {snapshot.get('rule_name') or snapshot.get('rule_id')} · "
        f"{proc.get('name') or '?'} pid={proc.get('pid')}"
    )
    llm_note: str | None = None
    try:
        from app.engines.ai.llm_client import chat_completion, llm_available

        if llm_available():
            prompt = (
                f"Incidente ZionXDR/Eagle (1 parágrafo, PT-BR, operacional): {summary}. "
                f"MITRE: {snapshot.get('mitre_tactic')}/{snapshot.get('mitre_technique')}. "
                f"Playbook sugerido: {slug}."
            )
            llm_note = chat_completion(
                "Você é analista SOC. Seja conciso e acionável.",
                prompt,
            )
            if llm_note:
                hints.insert(0, llm_note.strip())
    except Exception:
        llm_note = None

    return {
        "endpoint_id": endpoint_id,
        "endpoint_name": ep.name,
        "fingerprint": fingerprint,
        "event_id": event_id,
        "alert": snapshot,
        "nms": nms,
        "suggested_playbook_slug": slug,
        "hints": hints,
        "summary": summary,
        "llm_analysis": llm_note,
    }

"""Ponte SentinelAI → Eagle Offensive Platform (ConsoleState em zionxdr/eagle-offensive-platform)."""

from __future__ import annotations

import logging
import shutil
import sys
from functools import lru_cache
from pathlib import Path

from app.config import settings

log = logging.getLogger(__name__)


def _repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def _agent_has_eagle_package(agent: Path) -> bool:
    return (agent / "eagle" / "console_server.py").is_file()


def discover_eagle_agent_dir() -> Path | None:
    """Resolve diretório agent/ com pacote ``eagle`` (Docker, monorepo ou ZIONXDR_EAGLE_ROOT)."""
    configured = (settings.zionxdr_eagle_root or "").strip()
    if configured:
        p = Path(configured).expanduser().resolve()
        if _agent_has_eagle_package(p):
            return p
        log.warning("ZIONXDR_EAGLE_ROOT=%s sem pacote eagle", p)

    here = Path(__file__).resolve()
    candidates: list[Path] = [
        Path("/eagle-agent"),
    ]
    for base in list(here.parents)[:10]:
        candidates.append(base / "zionxdr" / "eagle-offensive-platform" / "agent")
    candidates.append(_repo_root() / "zionxdr" / "eagle-offensive-platform" / "agent")

    seen: set[str] = set()
    for raw in candidates:
        try:
            agent = raw.resolve()
        except OSError:
            continue
        key = str(agent)
        if key in seen:
            continue
        seen.add(key)
        if _agent_has_eagle_package(agent):
            return agent
    return None


def eagle_agent_dir() -> Path:
    found = discover_eagle_agent_dir()
    if found:
        return found
    return _repo_root() / "zionxdr" / "eagle-offensive-platform" / "agent"


def eagle_platform_dir() -> Path:
    return eagle_agent_dir().parent


def _ensure_runtime_dirs(root: Path) -> None:
    (root / "logs").mkdir(parents=True, exist_ok=True)
    (root / "quarantine").mkdir(parents=True, exist_ok=True)
    (root / "config").mkdir(parents=True, exist_ok=True)
    (root / "config" / "rules.d").mkdir(parents=True, exist_ok=True)


def _copy_file(src: Path, dst: Path) -> None:
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)


def eagle_runtime_root(agent: Path) -> Path:
    """Dados mutáveis (logs, quarantine) — sincroniza catálogo completo (rules + rules.d)."""
    configured = (settings.zionxdr_eagle_runtime_root or "").strip()
    if configured:
        runtime = Path(configured).expanduser().resolve()
    else:
        runtime = Path(__file__).resolve().parents[1] / "data" / "eagle-runtime"
    runtime.mkdir(parents=True, exist_ok=True)
    _ensure_runtime_dirs(runtime)

    src_cfg = agent / "config"
    dst_cfg = runtime / "config"
    if not src_cfg.is_dir():
        return runtime

    # Catálogo completo: rules.yaml + rules.d (176) + correlation + whitelist
    for name in ("rules.yaml", "coverage.yaml", "correlation.yaml", "whitelist.yaml"):
        src = src_cfg / name
        if src.is_file():
            _copy_file(src, dst_cfg / name)

    src_rules_d = src_cfg / "rules.d"
    dst_rules_d = dst_cfg / "rules.d"
    if src_rules_d.is_dir():
        dst_rules_d.mkdir(parents=True, exist_ok=True)
        for src in src_rules_d.glob("*.y*ml"):
            _copy_file(src, dst_rules_d / src.name)

    return runtime


def clear_console_state_cache() -> None:
    _get_console_state_cached.cache_clear()


@lru_cache(maxsize=1)
def _get_console_state_cached():
    agent = discover_eagle_agent_dir()
    if not agent:
        log.warning(
            "Eagle agent não encontrado — lab stub (defina ZIONXDR_EAGLE_ROOT ou monte /eagle-agent no Docker)"
        )
        from app.services.zionxdr_eagle_stub import LabConsoleState

        return LabConsoleState()

    agent_str = str(agent)
    if agent_str not in sys.path:
        sys.path.insert(0, agent_str)

    try:
        from eagle.console_server import ConsoleState
        from eagle.runner import RuntimePaths
    except ModuleNotFoundError as exc:
        log.warning("Import Eagle falhou (%s) — lab stub", exc)
        from app.services.zionxdr_eagle_stub import LabConsoleState

        return LabConsoleState()

    runtime = eagle_runtime_root(agent)
    return ConsoleState(RuntimePaths.from_root(runtime))


def get_console_state():
    """Re-sincroniza rules.d a cada acesso (catálogo 176) e reutiliza ConsoleState."""
    agent = discover_eagle_agent_dir()
    if agent:
        eagle_runtime_root(agent)
    return _get_console_state_cached()


def eagle_bundle_meta() -> dict[str, str]:
    platform = eagle_platform_dir()
    agent = discover_eagle_agent_dir()
    return {
        "product": "Eagle Offensive Platform",
        "brand": "ZionXDR",
        "platform_path": str(platform),
        "agent_path": str(agent or eagle_agent_dir()),
        "console": "SentinelAI embedded",
        "eagle_available": bool(agent),
    }

"""Console Eagle em lab quando o pacote agent não está no PYTHONPATH (ex.: API Docker só com /app)."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any


@dataclass
class _RuntimePaths:
    root: Path
    rules: Path
    coverage: Path
    logs: Path
    alerts: Path
    telemetry: Path
    quarantine: Path


def _lab_root() -> Path:
    root = Path(__file__).resolve().parents[1] / "data" / "eagle-lab"
    root.mkdir(parents=True, exist_ok=True)
    (root / "logs").mkdir(exist_ok=True)
    (root / "quarantine").mkdir(exist_ok=True)
    (root / "config").mkdir(exist_ok=True)
    return root


class LabConsoleState:
    """Respostas vazias/stub — evita 500; sync devolve 0 eventos até Eagle real estar ligado."""

    def __init__(self) -> None:
        root = _lab_root()
        logs = root / "logs"
        self.paths = _RuntimePaths(
            root=root,
            rules=root / "config" / "rules.yaml",
            coverage=root / "config" / "coverage.yaml",
            logs=logs,
            alerts=logs / "alerts.jsonl",
            telemetry=logs / "telemetry.jsonl",
            quarantine=root / "quarantine",
        )
        self.monitor_running = False
        self.last_scan_alerts = 0
        self.last_error: str | None = "Eagle agent indisponível — monte zionxdr/eagle-offensive-platform/agent ou defina ZIONXDR_EAGLE_ROOT"

    def read_alerts(self, limit: int = 200) -> list[dict[str, Any]]:
        path = self.paths.alerts
        if not path.is_file():
            return []
        import json

        lines = path.read_text(encoding="utf-8").strip().splitlines()
        out: list[dict[str, Any]] = []
        for line in lines[-limit:]:
            try:
                out.append(json.loads(line))
            except json.JSONDecodeError:
                continue
        out.reverse()
        return out

    def stats(self) -> dict[str, Any]:
        alerts = self.read_alerts(limit=5000)
        return {
            "total_alerts": len(alerts),
            "by_severity": {},
            "rules": 0,
            "quarantine_files": 0,
            "monitor_running": self.monitor_running,
            "last_scan_alerts": self.last_scan_alerts,
            "last_error": self.last_error,
            "alerts_path": str(self.paths.alerts),
            "telemetry": self.telemetry_status(),
            "lab_stub": True,
        }

    def scan_once(self, evaluate_all: bool = True) -> dict[str, Any]:
        return {"ok": True, "alerts": 0, "lab_stub": True}

    def start_monitor(self, interval: float = 3.0) -> dict[str, Any]:
        return {"ok": False, "monitor_running": False, "error": self.last_error}

    def stop_monitor(self) -> dict[str, Any]:
        self.monitor_running = False
        return {"ok": True, "monitor_running": False}

    def telemetry_status(self) -> dict[str, Any]:
        return {"etw": {"running": False}, "lab_stub": True}

    def etw_start(self) -> dict[str, Any]:
        return {"ok": False, "error": self.last_error}

    def etw_stop(self) -> dict[str, Any]:
        return {"ok": True}

    def memory_scan(self) -> dict[str, Any]:
        return {"ok": True, "findings": 0, "lab_stub": True}

    def quarantine_list(self) -> list[str]:
        if not self.paths.quarantine.is_dir():
            return []
        return sorted(p.name for p in self.paths.quarantine.iterdir() if p.is_file())

    def rules_summary(self) -> list[dict[str, Any]]:
        return []

    def coverage_summary(self) -> dict[str, Any]:
        return {"title": "Cobertura", "note": "Eagle lab stub", "pillars": [], "lab_stub": True}

    def audit_logs(self, source: str = "alerts", limit: int = 100) -> dict[str, Any]:
        return {"source": source, "path": str(self.paths.alerts), "entries": []}

"""ZionXDR S3 — evidence bundle e deep links."""

from __future__ import annotations

import io
import json
import zipfile
from typing import Any

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models.zionxdr import ZionxdrAlertFingerprint, ZionxdrEndpoint


def deep_link_hash(*, endpoint_id: int, fingerprint: str, event_id: int | None = None) -> str:
    q = f"endpoint_id={endpoint_id}&fp={fingerprint}"
    if event_id is not None:
        q += f"&event_id={event_id}"
    return f"#zionxdr?{q}"


def get_detection_by_event(session: Session, event_id: int) -> dict[str, Any] | None:
    row = session.execute(
        select(ZionxdrAlertFingerprint).where(ZionxdrAlertFingerprint.event_id == event_id).limit(1)
    ).scalar_one_or_none()
    if not row:
        return None
    return {
        "endpoint_id": row.endpoint_id,
        "fingerprint": row.fingerprint,
        "event_id": row.event_id,
        "deep_link": deep_link_hash(endpoint_id=row.endpoint_id, fingerprint=row.fingerprint, event_id=row.event_id),
        "snapshot": row.alert_snapshot,
    }


def get_evidence(session: Session, endpoint_id: int, fingerprint: str) -> dict[str, Any]:
    ep = session.get(ZionxdrEndpoint, endpoint_id)
    if not ep:
        raise ValueError("Endpoint não encontrado")
    row = session.execute(
        select(ZionxdrAlertFingerprint).where(
            ZionxdrAlertFingerprint.endpoint_id == endpoint_id,
            ZionxdrAlertFingerprint.fingerprint == fingerprint,
        )
    ).scalar_one_or_none()
    snapshot = row.alert_snapshot if row else None
    if not snapshot:
        for a in ep.eagle_alerts_cache or []:
            from app.services.zionxdr_alerts import _fingerprint

            if _fingerprint(a) == fingerprint:
                snapshot = a
                break
    if not snapshot:
        raise ValueError("Detecção não encontrada")
    agent_collect = ((ep.extra or {}).get("evidence_collect") or {}).get(fingerprint)
    return {
        "endpoint_id": endpoint_id,
        "endpoint_name": ep.name,
        "fingerprint": fingerprint,
        "enforcement_mode": ep.enforcement_mode.value if hasattr(ep.enforcement_mode, "value") else str(ep.enforcement_mode),
        "device_id": ep.device_id,
        "alert": snapshot,
        "agent_collect": agent_collect,
        "deep_link": deep_link_hash(endpoint_id=endpoint_id, fingerprint=fingerprint, event_id=row.event_id if row else None),
    }


def merge_agent_evidence(session: Session, endpoint: ZionxdrEndpoint, fingerprint: str, result: dict[str, Any]) -> None:
    """Persiste payload do job eagle.evidence_collect no endpoint."""
    store = dict((endpoint.extra or {}).get("evidence_collect") or {})
    store[fingerprint] = result
    endpoint.extra = {**(endpoint.extra or {}), "evidence_collect": store}
    session.flush()


def export_evidence_zip(payload: dict[str, Any]) -> bytes:
    buf = io.BytesIO()
    alert = payload.get("alert") or {}
    agent = payload.get("agent_collect") or {}
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        manifest = {
            "product": "ZionXDR",
            "kind": "evidence-bundle",
            "endpoint_id": payload.get("endpoint_id"),
            "fingerprint": payload.get("fingerprint"),
            "rule_id": alert.get("rule_id"),
            "mitre_tactic": alert.get("mitre_tactic"),
            "mitre_technique": alert.get("mitre_technique"),
            "suggested_playbook_slug": alert.get("suggested_playbook_slug"),
        }
        zf.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2))
        zf.writestr("evidence.json", json.dumps(payload, ensure_ascii=False, indent=2))
        if agent:
            zf.writestr("agent-collect.json", json.dumps(agent, ensure_ascii=False, indent=2))
        proc = alert.get("process") if isinstance(alert, dict) else None
        if proc:
            zf.writestr("process.json", json.dumps(proc, ensure_ascii=False, indent=2))
    return buf.getvalue()

"""ZionXDR S4 — correlação endpoint ↔ Device NMS ↔ topologia."""

from __future__ import annotations

from typing import Any

from sqlalchemy import func, or_, select
from sqlalchemy.orm import Session

from app.models import Device, TopologyGroup, TopologyLayout
from app.models.zionxdr import ZionxdrEndpoint


def _group_path(session: Session, group_id: int | None) -> list[dict[str, Any]]:
    path: list[dict[str, Any]] = []
    gid = group_id
    seen = 0
    while gid and seen < 32:
        g = session.get(TopologyGroup, gid)
        if not g:
            break
        path.append({"id": g.id, "name": g.name, "type": g.group_type.value if hasattr(g.group_type, "value") else str(g.group_type)})
        gid = g.parent_id
        seen += 1
    path.reverse()
    return path


def suggest_devices_for_endpoint(session: Session, endpoint: ZionxdrEndpoint, *, limit: int = 5) -> list[dict[str, Any]]:
    if endpoint.device_id:
        return []
    host = (endpoint.hostname or endpoint.name or "").strip()
    if not host:
        return []
    needle = host.lower()
    rows = session.execute(
        select(Device)
        .where(
            or_(
                Device.hostname.ilike(f"%{needle}%"),
                Device.ip_address.ilike(f"%{needle}%"),
            )
        )
        .limit(limit)
    ).scalars().all()
    return [{"device_id": d.id, "hostname": d.hostname, "ip_address": d.ip_address} for d in rows]


def try_auto_link_device(session: Session, endpoint: ZionxdrEndpoint) -> int | None:
    """Vincula automaticamente se hostname do endpoint coincide com um Device."""
    if endpoint.is_local or endpoint.device_id:
        return None
    host = (endpoint.hostname or "").strip().lower()
    if not host:
        return None
    dev = session.execute(
        select(Device).where(func.lower(Device.hostname) == host).limit(1)
    ).scalar_one_or_none()
    if not dev:
        return None
    endpoint.device_id = dev.id
    session.flush()
    return dev.id


def link_endpoint_device(session: Session, endpoint: ZionxdrEndpoint, device_id: int) -> Device:
    if endpoint.is_local:
        raise ValueError("Endpoint local não suporta vínculo NMS")
    dev = session.get(Device, device_id)
    if not dev:
        raise ValueError("Dispositivo não encontrado")
    endpoint.device_id = device_id
    session.flush()
    return dev


def nms_context(session: Session, endpoint: ZionxdrEndpoint) -> dict[str, Any]:
    device = session.get(Device, endpoint.device_id) if endpoint.device_id else None
    layout = (
        session.get(TopologyLayout, endpoint.device_id) if endpoint.device_id else None
    )
    department_path: list[dict[str, Any]] = []
    map_groups: list[dict[str, Any]] = []
    if layout and layout.parent_group_id:
        department_path = _group_path(session, layout.parent_group_id)
        map_groups = department_path
    return {
        "endpoint_id": endpoint.id,
        "endpoint_name": endpoint.name,
        "device_id": endpoint.device_id,
        "device": (
            {
                "id": device.id,
                "hostname": device.hostname,
                "ip_address": device.ip_address,
                "device_type": device.device_type,
                "status": device.status.value if hasattr(device.status, "value") else str(device.status),
            }
            if device
            else None
        ),
        "map_groups": map_groups,
        "department_path": department_path,
        "topology_deep_link": f"#topology?device_id={device.id}" if device else None,
        "suggested_devices": suggest_devices_for_endpoint(session, endpoint),
    }


def device_index(session: Session) -> dict[str, dict[str, Any]]:
    rows = session.execute(
        select(ZionxdrEndpoint).where(
            ZionxdrEndpoint.is_local.is_(False),
            ZionxdrEndpoint.device_id.isnot(None),
        )
    ).scalars().all()
    by_device: dict[str, dict[str, Any]] = {}
    for ep in rows:
        if ep.device_id is None:
            continue
        by_device[str(ep.device_id)] = {"endpoint_id": ep.id, "name": ep.name}
    return {"by_device_id": by_device}

"""ZionXDR S2 — políticas YAML versionadas e modos monitor/detect/enforce."""

from __future__ import annotations

import hashlib
from pathlib import Path

import yaml
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models.zionxdr import (
    ZionxdrEnforcementMode,
