def _checksum(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _default_rules_yaml() -> str:
    path = eagle_agent_dir() / "config" / "rules.yaml"
    if path.is_file():
        return path.read_text(encoding="utf-8")
    return "rules: []\n"


def ensure_builtin_default_policy(session: Session) -> ZionxdrPolicy:
    row = session.execute(
        select(ZionxdrPolicy)
        .where(ZionxdrPolicy.slug == "eagle-default", ZionxdrPolicy.is_builtin.is_(True))
        .order_by(ZionxdrPolicy.version.desc())
        .limit(1)
    ).scalar_one_or_none()
    if row:
        return row
    yaml_text = _default_rules_yaml()
    row = ZionxdrPolicy(
        slug="eagle-default",
        name="Eagle default (bundled)",
        version=1,
        yaml_text=yaml_text,
        checksum=_checksum(yaml_text),
        is_builtin=True,
    )
    session.add(row)
    session.flush()
    return row


def list_policies(session: Session) -> list[ZionxdrPolicy]:
    ensure_builtin_default_policy(session)
    return list(
        session.execute(select(ZionxdrPolicy).order_by(ZionxdrPolicy.slug.asc(), ZionxdrPolicy.version.desc())).scalars().all()
    )


def get_policy(session: Session, policy_id: int) -> ZionxdrPolicy | None:
    return session.get(ZionxdrPolicy, policy_id)


def create_policy(session: Session, *, name: str, slug: str, yaml_text: str | None = None) -> ZionxdrPolicy:
    slug_norm = slug.strip().lower().replace(" ", "-")[:64]
    if not slug_norm:
        raise ValueError("slug inválido")
    latest = session.execute(
        select(ZionxdrPolicy.version)
        .where(ZionxdrPolicy.slug == slug_norm)
        .order_by(ZionxdrPolicy.version.desc())
        .limit(1)
    ).scalar_one_or_none()
    version = int(latest or 0) + 1
    body = yaml_text if yaml_text is not None else _default_rules_yaml()
    row = ZionxdrPolicy(
        slug=slug_norm,
        name=name.strip()[:120],
        version=version,
        yaml_text=body,
        checksum=_checksum(body),
        is_builtin=False,
    )
    session.add(row)
    session.flush()
    return row


def rules_preview_from_yaml(yaml_text: str) -> list[dict]:
    try:
        data = yaml.safe_load(yaml_text) or {}
    except yaml.YAMLError:
        return []
    out: list[dict] = []
    for r in data.get("rules") or []:
        out.append(
            {
                "id": r.get("id"),
                "name": r.get("name"),
                "severity": r.get("severity"),
                "action": r.get("action"),
                "mitre_tactic": r.get("mitre_tactic"),
                "mitre_technique": r.get("mitre_technique"),
            }
        )
    return out


def _control_path() -> Path:
    return eagle_agent_dir() / "zionxdr_control.json"


def write_local_control(
    *,
    enforcement_mode: str,
    policy_id: int | None,
    policy_version: int | None,
    **extra: object,
) -> None:
    import json

    path = _control_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    payload: dict = {}
    if path.is_file():
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            payload = {}
    payload.update(
        {
            "enforcement_mode": enforcement_mode,
            "policy_id": policy_id,
            "policy_version": policy_version,
        }
    )
    for k, v in extra.items():
        if v is not None:
            payload[k] = v
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")


def _parse_policy_yaml(yaml_text: str) -> tuple[str, dict | None]:
    import yaml

    data = yaml.safe_load(yaml_text) or {}
    telemetry = data.get("telemetry") if isinstance(data.get("telemetry"), dict) else None
    if "rules" in data:
        body = yaml.safe_dump({"rules": data.get("rules") or []}, allow_unicode=True, sort_keys=False)
    else:
        body = yaml_text
    return body, telemetry


def apply_policy_to_local_rules(yaml_text: str) -> None:
    rules_body, telemetry = _parse_policy_yaml(yaml_text)
    agent_root = eagle_agent_dir()
    rules_path = agent_root / "config" / "rules.yaml"
    rules_path.parent.mkdir(parents=True, exist_ok=True)
    rules_path.write_text(rules_body, encoding="utf-8")
    if telemetry:
        import json

        path = _control_path()
        payload: dict = {}
        if path.is_file():
            try:
                payload = json.loads(path.read_text(encoding="utf-8"))
            except json.JSONDecodeError:
                payload = {}
        if "memory_scan_interval_sec" in telemetry:
            payload["memory_scan_interval_sec"] = int(telemetry.get("memory_scan_interval_sec") or 0)
        if "etw_enabled" in telemetry:
            payload["etw_enabled"] = bool(telemetry.get("etw_enabled"))
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    get_console_state.cache_clear()


