"""Metadados de regras Eagle (MITRE) para enrich de alertas."""

from __future__ import annotations

from functools import lru_cache
from typing import Any

import yaml

from app.services.zionxdr_eagle import eagle_agent_dir


@lru_cache(maxsize=1)
def _rules_index() -> dict[str, dict[str, Any]]:
    path = eagle_agent_dir() / "config" / "rules.yaml"
    if not path.is_file():
        return {}
    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    except yaml.YAMLError:
        return {}
    out: dict[str, dict[str, Any]] = {}
    for r in data.get("rules") or []:
        rid = str(r.get("id") or "")
        if rid:
            out[rid] = r
    return out


def enrich_alert_from_rules(alert: dict[str, Any]) -> dict[str, Any]:
    out = dict(alert)
    rid = str(out.get("rule_id") or "")
    meta = _rules_index().get(rid)
    if not meta:
        return out
    if not out.get("mitre_tactic") and meta.get("mitre_tactic"):
        out["mitre_tactic"] = meta.get("mitre_tactic")
    if not out.get("mitre_technique") and meta.get("mitre_technique"):
        out["mitre_technique"] = meta.get("mitre_technique")
    if not out.get("rule_name") and meta.get("name"):
        out["rule_name"] = meta.get("name")
    return out


def clear_rules_cache() -> None:
    _rules_index.cache_clear()

"""ZionXDR endpoints e resolução local vs remoto."""

from __future__ import annotations

import secrets
from datetime import UTC, datetime, timedelta

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models.zionxdr import ZionxdrEndpoint, ZionxdrEndpointStatus
from app.services.zionvm_service import hash_agent_token


ZIONXDR_AGENT_VERSION = "0.3.1-s9"
OFFLINE_AFTER_SECONDS = 120


def ensure_local_endpoint(session: Session) -> ZionxdrEndpoint:
    row = session.execute(select(ZionxdrEndpoint).where(ZionxdrEndpoint.is_local.is_(True)).limit(1)).scalar_one_or_none()
    if row:
        return row
    row = ZionxdrEndpoint(
        name="Control Plane (local)",
        hostname="localhost",
        os_platform="linux",
        status=ZionxdrEndpointStatus.UNKNOWN,
        is_local=True,
    )
    session.add(row)
    session.flush()
    return row


def get_endpoint(session: Session, endpoint_id: int | None) -> ZionxdrEndpoint:
    if endpoint_id is None:
        return ensure_local_endpoint(session)
    row = session.get(ZionxdrEndpoint, endpoint_id)
    if not row:
        raise ValueError("Endpoint não encontrado")
    return row


def list_endpoints(session: Session) -> list[ZionxdrEndpoint]:
    ensure_local_endpoint(session)
    rows = session.execute(select(ZionxdrEndpoint).order_by(ZionxdrEndpoint.is_local.desc(), ZionxdrEndpoint.id)).scalars().all()
    refresh_endpoint_statuses(session, rows)
    return list(rows)


def refresh_endpoint_statuses(session: Session, rows: list[ZionxdrEndpoint] | None = None) -> None:
    if rows is None:
        rows = session.execute(select(ZionxdrEndpoint)).scalars().all()
    now = datetime.now(UTC)
    for ep in rows:
        if ep.is_local:
            continue
        if ep.last_seen_at and (now - ep.last_seen_at).total_seconds() <= OFFLINE_AFTER_SECONDS:
            if ep.status != ZionxdrEndpointStatus.ONLINE:
                ep.status = ZionxdrEndpointStatus.ONLINE
        elif ep.last_seen_at:
            ep.status = ZionxdrEndpointStatus.OFFLINE


def create_endpoint(
    session: Session,
    *,
    name: str,
    hostname: str | None,
    os_platform: str = "windows",
    device_id: int | None = None,
) -> ZionxdrEndpoint:
    row = ZionxdrEndpoint(
        name=name.strip(),
        hostname=(hostname or "").strip() or None,
        os_platform=os_platform or "windows",
        device_id=device_id,
        status=ZionxdrEndpointStatus.UNKNOWN,
        is_local=False,
    )
    session.add(row)
    session.flush()
    return row


def issue_endpoint_agent_token(session: Session, endpoint: ZionxdrEndpoint) -> str:
    if endpoint.is_local:
        raise ValueError("Endpoint local não usa agent token remoto")
    token = secrets.token_urlsafe(32)
    endpoint.agent_token_hash = hash_agent_token(token)
    session.flush()
    return token


def get_endpoint_by_agent_token(session: Session, token: str) -> ZionxdrEndpoint | None:
    if not token:
        return None
    digest = hash_agent_token(token)
    return session.execute(
        select(ZionxdrEndpoint).where(
            ZionxdrEndpoint.agent_token_hash == digest,
            ZionxdrEndpoint.is_local.is_(False),
        )
    ).scalar_one_or_none()


def agent_heartbeat(session: Session, endpoint: ZionxdrEndpoint, *, version: str | None, hostname: str | None) -> dict:
    endpoint.last_seen_at = datetime.now(UTC)
    endpoint.status = ZionxdrEndpointStatus.ONLINE
    if version:
        endpoint.agent_version = version
    if hostname:
        endpoint.hostname = hostname
    from app.services.zionxdr_nms import try_auto_link_device

    try_auto_link_device(session, endpoint)
    mode = endpoint.enforcement_mode.value if hasattr(endpoint.enforcement_mode, "value") else str(endpoint.enforcement_mode or "monitor")
    return {
        "policy_id": endpoint.policy_id,
        "applied_policy_version": endpoint.applied_policy_version,
        "enforcement_mode": mode,
    }


def apply_agent_ingest(
    session: Session,
    endpoint: ZionxdrEndpoint,
    *,
    stats: dict | None,
    alerts: list | None,
    quarantine: list | None,
    extra: dict | None = None,
) -> None:
    if stats is not None:
        merged = dict(stats)
        if extra and extra.get("telemetry"):
            merged["telemetry"] = extra["telemetry"]
        endpoint.eagle_stats = merged
    if alerts is not None:
        endpoint.eagle_alerts_cache = alerts[-500:]
    if quarantine is not None:
        endpoint.quarantine_cache = quarantine
    if extra is not None:
        endpoint.extra = {**(endpoint.extra or {}), **extra}
    endpoint.last_seen_at = datetime.now(UTC)
    endpoint.status = ZionxdrEndpointStatus.ONLINE


def remote_stats(endpoint: ZionxdrEndpoint) -> dict:
    base = dict(endpoint.eagle_stats or {})
    base.setdefault("total_alerts", len(endpoint.eagle_alerts_cache or []))
    base.setdefault("monitor_running", False)
    base.setdefault("rules", base.get("rules", 0))
    base.setdefault("quarantine_files", len(endpoint.quarantine_cache or []))
    base["endpoint_id"] = endpoint.id
    base["endpoint_name"] = endpoint.name
    base["remote"] = True
    return base

