@celery_app.task(name="app.workers.ai_tasks.run_anomaly_detection")
def run_anomaly_detection() -> dict:
    with SyncSession() as session:
        records = detect_latency_anomalies(session)
        for record in records:
            event = session.execute(
                select(Event)
                .where(Event.device_id == record.device_id, Event.event_type == "anomaly_detected")
                .order_by(Event.created_at.desc())
            ).scalars().first()
            if event:
                queue_alerts_for_event(session, event)
        session.commit()
    return {"anomalies_detected": len(records)}


