from app.db_sync import SyncSession
from app.engines.config.ssh_backup import backup_device_config, restore_device_config
from app.engines.netflow.collector import drain_flow_records
from app.models import ConfigBackup, Device, Event, EventSeverity
from app.services.credential_service import resolve_ssh_creds
from app.services.enterprise_service import save_config_backup, store_flow_records
from app.workers.celery_app import celery_app

logger = logging.getLogger(__name__)


@celery_app.task(name="app.workers.enterprise_tasks.persist_flow_records")
def persist_flow_records() -> dict:
    async def _run() -> list[dict]:
        return await drain_flow_records()

    try:
        records = asyncio.run(_run())
    except RuntimeError:
        records = []

    if not records:
        return {"stored": 0}

    with SyncSession() as session:
        count = store_flow_records(session, records)
        session.commit()
    return {"stored": count}


@celery_app.task(name="app.workers.enterprise_tasks.run_config_backup")
def run_config_backup(device_id: int) -> dict:
    with SyncSession() as session:
        device = session.get(Device, device_id)
        if not device:
            return {"error": "device not found"}
        try:
            ssh = resolve_ssh_creds(session, device)
            content, content_hash = backup_device_config(
                device.ip_address,
                username=ssh.get("username"),
                password=ssh.get("password"),
            )
            backup = save_config_backup(session, device_id, content, content_hash)
            session.commit()
            return {"backup_id": backup.id, "changed": backup.content_hash == content_hash}
        except Exception as exc:
            logger.warning("Config backup failed for device %s: %s", device_id, exc)
            return {"error": str(exc)}


@celery_app.task(name="app.workers.enterprise_tasks.run_config_restore")
def run_config_restore(device_id: int, backup_id: int, reviewed_by: str = "system") -> dict:
    with SyncSession() as session:
        device = session.get(Device, device_id)
        backup = session.get(ConfigBackup, backup_id)
        if not device or not backup or backup.device_id != device_id:
            return {"error": "device/backup not found"}
        try:
            ssh = resolve_ssh_creds(session, device)
            result = restore_device_config(
                device.ip_address,
                backup.content,
                username=ssh.get("username"),
                password=ssh.get("password"),
            )
            session.add(
                Event(
                    device_id=device_id,
                    event_type="config_restore_applied",
                    message=(
                        f"Restore SSH aplicado (backup #{backup_id}, "
                        f"{result.get('lines')} linhas) por {reviewed_by}"
                    ),
                    severity=EventSeverity.WARNING,
                )
            )
            session.commit()
            return {"ok": True, **result, "backup_id": backup_id, "device_id": device_id}
        except Exception as exc:
            logger.warning("Config restore failed device=%s backup=%s: %s", device_id, backup_id, exc)
            session.add(
                Event(
                    device_id=device_id,
                    event_type="config_restore_failed",
                    message=f"Restore SSH falhou (backup #{backup_id}): {exc}",
                    severity=EventSeverity.CRITICAL,
                )
            )
            session.commit()
            return {"error": str(exc), "backup_id": backup_id, "device_id": device_id}

