@celery_app.task(name="app.workers.tasks.ping_device")
def ping_device(device_id: int) -> dict:
    """Ping imediato de um host (adição no mapa) — não espera o ciclo global."""
    from app.services.monitor_service import ping_device_now

    with SyncSession() as session:
        result = ping_device_now(session, device_id, timeout=2)
        session.commit()
