def _lifecycle_failure_message(exc: BaseException) -> str:
    from sqlalchemy.exc import IntegrityError

    if isinstance(exc, IntegrityError):
        orig = str(getattr(exc, "orig", exc))
        if "uq_zionvm_vms_node_vmid" in orig or "UniqueViolation" in orig:
            return "VMID já utilizado neste node (registo anterior ou soft-delete). Tente novamente."
        return "Conflito de dados ao gravar a VM."
    return str(exc) or exc.__class__.__name__


def _append_log(task: ZionvmTask, msg: str) -> None:
    entry = {"ts": datetime.now(UTC).isoformat(), "msg": msg}
    log = list(task.log or [])
    log.append(entry)
    task.log = log


def run_simulate_inline(session, task: ZionvmTask) -> None:
    """Run simulated progress without Celery (dev fallback)."""
    task.status = ZionvmTaskStatus.RUNNING
    task.started_at = datetime.now(UTC)
    task.progress_pct = 10
    _append_log(task, "started")
    session.flush()

    for pct in (35, 65, 90):
        task.progress_pct = pct
        _append_log(task, f"progress {pct}%")
        session.flush()

    task.progress_pct = 100
    task.status = ZionvmTaskStatus.SUCCESS
    task.finished_at = datetime.now(UTC)
    task.result = {**(task.result or {}), "ok": True, "simulated": True}
    _append_log(task, "completed")
    session.flush()


def run_lifecycle_inline(session, task: ZionvmTask) -> None:
    from app.services.zionvm_service import (
        apply_backup_action,
        apply_ops_action,
        apply_cluster_action,
        apply_lxc_action,
        apply_ha_action,
        apply_network_action,
        apply_storage_action,
        apply_vm_action,
    )
    from app.services.zionvm_parity import apply_node_action
    from app.services.zionvm_parity_s26_30 import apply_hardware_action

    task.status = ZionvmTaskStatus.RUNNING
    task.started_at = datetime.now(UTC)
    task.progress_pct = 20
    _append_log(task, f"running {task.task_type}")
    session.flush()
    try:
        if str(task.task_type).startswith("storage."):
            result = apply_storage_action(session, task)
        elif str(task.task_type).startswith("network."):
            result = apply_network_action(session, task)
        elif str(task.task_type).startswith("cluster."):
            result = apply_cluster_action(session, task)
        elif str(task.task_type).startswith("lxc."):
            result = apply_lxc_action(session, task)
        elif str(task.task_type).startswith("ha."):
            result = apply_ha_action(session, task)
        elif str(task.task_type).startswith("backup."):
            result = apply_backup_action(session, task)
        elif str(task.task_type).startswith("ops."):
            result = apply_ops_action(session, task)
        elif str(task.task_type).startswith("node."):
            result = apply_node_action(session, task)
        elif str(task.task_type).startswith("hardware."):
            result = apply_hardware_action(session, task)
        elif str(task.task_type).startswith("manager."):
            from app.services.zionvm_parity_s26_30 import apply_manager_action

            result = apply_manager_action(session, task)
        else:
            result = apply_vm_action(session, task)
        task.progress_pct = 100
        task.status = ZionvmTaskStatus.SUCCESS
        task.finished_at = datetime.now(UTC)
        task.result = {**(task.result or {}), **result, "ok": True}
        from app.services.zionvm_task_narrative import narrate_lifecycle_success

        narrate_lifecycle_success(task, result)
        _append_log(task, "completed")
        session.flush()
    except Exception as exc:
        from sqlalchemy.exc import SQLAlchemyError

        task_id = task.id
        fail_msg = _lifecycle_failure_message(exc)
        try:
            session.rollback()
        except Exception:
            pass
        task = session.get(ZionvmTask, task_id)
        if not task:
            raise
        task.status = ZionvmTaskStatus.FAILED
        task.finished_at = datetime.now(UTC)
        task.message = fail_msg
        _append_log(task, f"failed: {fail_msg}")
        try:
            from app.services.zionvm_alerts import emit_zionvm_task_failed

            emit_zionvm_task_failed(
                session,
                task_id=task.id,
                task_type=str(task.task_type),
                message=fail_msg,
            )
        except Exception:
            pass
        try:
            session.flush()
        except SQLAlchemyError:
            session.rollback()
            task = session.get(ZionvmTask, task_id)
            if task:
                task.status = ZionvmTaskStatus.FAILED
                task.message = fail_msg
                session.flush()
        raise exc


