"""Celery — sync Eagle local → Alertas SentinelAI + memory scan agendado."""

from __future__ import annotations

import json
from datetime import UTC, datetime

from sqlalchemy import select

from app.db_sync import SyncSession
from app.models.zionxdr import ZionxdrEndpoint
from app.services.zionxdr_alerts import pull_local_eagle_alerts, sync_eagle_alerts_to_sentinel
from app.services.zionxdr_agent_jobs import enqueue_agent_job
from app.services.zionxdr_eagle import get_console_state
from app.services.zionxdr_policies import _control_path
from app.services.zionxdr_service import ensure_local_endpoint
from app.services.zionxdr_telemetry import run_local_memory_scan
from app.workers.celery_app import celery_app


def _parse_iso(ts: str | None) -> datetime | None:
    if not ts:
        return None
    try:
        return datetime.fromisoformat(ts.replace("Z", "+00:00"))
    except ValueError:
        return None


def _memory_due(interval_sec: int, last_at: str | None) -> bool:
    if interval_sec <= 0:
        return False
    last = _parse_iso(last_at)
    if not last:
        return True
    return (datetime.now(UTC) - last.astimezone(UTC)).total_seconds() >= interval_sec


@celery_app.task(name="app.workers.zionxdr_tasks.sync_local_eagle_to_alerts")
def sync_local_eagle_to_alerts() -> dict:
    with SyncSession() as session:
        ep = ensure_local_endpoint(session)
        alerts = pull_local_eagle_alerts(limit=500)
        n = sync_eagle_alerts_to_sentinel(session, ep, alerts)
        session.commit()
        return {"ok": True, "endpoint_id": ep.id, "events_created": n}


@celery_app.task(name="app.workers.zionxdr_tasks.zionxdr_scheduled_memory_scans")
def zionxdr_scheduled_memory_scans() -> dict:
    """Dispara memory scan local/remoto conforme policy (memory_scan_interval_sec)."""
    local_runs = 0
    queued = 0
    with SyncSession() as session:
        ctrl: dict = {}
        path = _control_path()
        if path.is_file():
            try:
                ctrl = json.loads(path.read_text(encoding="utf-8"))
            except json.JSONDecodeError:
                ctrl = {}
        interval = int(ctrl.get("memory_scan_interval_sec") or 0)
        if _memory_due(interval, ctrl.get("last_memory_scan_at")):
            run_local_memory_scan()
            ep = ensure_local_endpoint(session)
            sync_eagle_alerts_to_sentinel(session, ep, pull_local_eagle_alerts(limit=500))
            local_runs += 1

        rows = session.execute(select(ZionxdrEndpoint).where(ZionxdrEndpoint.is_local.is_(False))).scalars().all()
        for ep in rows:
            telem = (ep.eagle_stats or {}).get("telemetry") or {}
            interval = int(telem.get("memory_scan_interval_sec") or 0)
            if not interval:
                extra = ep.extra or {}
                interval = int(extra.get("memory_scan_interval_sec") or 0)
            if _memory_due(interval, telem.get("last_memory_scan_at")):
                enqueue_agent_job(session, endpoint_id=ep.id, action="eagle.memory_scan", payload={"scheduled": True})
                queued += 1
        session.commit()
    return {"ok": True, "local_runs": local_runs, "remote_queued": queued}

import asyncio
import json
import logging
from dataclasses import dataclass, field

from fastapi import WebSocket

logger = logging.getLogger(__name__)


@dataclass
class MapPresence:
    username: str
    color: str
    cursor: dict = field(default_factory=lambda: {"x": 0, "y": 0})


class MapCollabManager:
    def __init__(self) -> None:
        self._rooms: dict[str, dict[WebSocket, MapPresence]] = {}
        self._lock = asyncio.Lock()
        self._colors = ["#3b82f6", "#22c55e", "#f59e0b", "#ef4444", "#8b5cf6", "#06b6d4"]

    async def connect(self, room: str, websocket: WebSocket, username: str) -> MapPresence:
        async with self._lock:
            if room not in self._rooms:
                self._rooms[room] = {}
            color = self._colors[len(self._rooms[room]) % len(self._colors)]
            presence = MapPresence(username=username, color=color)
            self._rooms[room][websocket] = presence
        await self.broadcast(room, {"type": "user_joined", "username": username, "color": color}, exclude=websocket)
        await self.broadcast_presence(room)
        return presence

    async def disconnect(self, room: str, websocket: WebSocket) -> None:
        async with self._lock:
            room_clients = self._rooms.get(room, {})
            presence = room_clients.pop(websocket, None)
            if not room_clients and room in self._rooms:
                del self._rooms[room]
        if presence:
            await self.broadcast(room, {"type": "user_left", "username": presence.username})
            await self.broadcast_presence(room)

    async def broadcast(self, room: str, message: dict, exclude: WebSocket | None = None) -> None:
        room_clients = self._rooms.get(room, {})
        dead: list[WebSocket] = []
        for ws in room_clients:
            if ws is exclude:
                continue
            try:
                await ws.send_json(message)
            except Exception:
                dead.append(ws)
        for ws in dead:
            room_clients.pop(ws, None)

    async def broadcast_presence(self, room: str) -> None:
        room_clients = self._rooms.get(room, {})
        users = [
            {"username": p.username, "color": p.color, "cursor": p.cursor}
            for p in room_clients.values()
        ]
        await self.broadcast(room, {"type": "presence", "users": users})

    async def handle_message(self, room: str, websocket: WebSocket, data: dict) -> None:
        room_clients = self._rooms.get(room, {})
        presence = room_clients.get(websocket)
        if not presence:
            return

        msg_type = data.get("type")
        if msg_type == "cursor":
            presence.cursor = {"x": data.get("x", 0), "y": data.get("y", 0)}
            await self.broadcast(
                room,
                {"type": "cursor", "username": presence.username, "color": presence.color, "x": data.get("x"), "y": data.get("y")},
                exclude=websocket,
            )
        elif msg_type == "node_move":
            await self.broadcast(
                room,
                {
                    "type": "node_move",
                    "username": presence.username,
                    "node_id": data.get("node_id"),
                    "x": data.get("x"),
                    "y": data.get("y"),
                },
                exclude=websocket,
            )
        elif msg_type == "layout_saved":
            await self.broadcast(room, {"type": "layout_saved", "username": presence.username})


