const CACHE = "sentinelai-v2";
const ASSETS = ["/", "/manifest.json"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(ASSETS)));
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))),
    ).then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET") return;
  event.respondWith(
    fetch(event.request)
      .then((response) => response)
      .catch(() => caches.match(event.request)),
  );
});

self.addEventListener("push", (event) => {
  let title = "SentinelAI";
  let body = "Novo alerta";
  let url = "/#/alerts";
  let extra = {};
  try {
    const data = event.data ? event.data.json() : {};
    if (data && typeof data === "object") {
      if (data.title) title = String(data.title);
      if (data.body) body = String(data.body);
      if (data.url) url = String(data.url);
      extra = {
        event_type: data.event_type ?? null,
        device_id: data.device_id ?? null,
        alert_id: data.alert_id ?? null,
        event_id: data.event_id ?? null,
      };
    }
  } catch {
    try {
      body = event.data ? event.data.text() : body;
    } catch {
      /* ignore */
    }
  }
  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      icon: "/favicon.ico",
      badge: "/favicon.ico",
      data: { url, ...extra },
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || "/#/alerts";
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      for (const client of clients) {
        if ("focus" in client) {
          client.navigate?.(target);
          return client.focus();
        }
      }
      if (self.clients.openWindow) return self.clients.openWindow(target);
      return undefined;
    }),
  );
});

(function () {
  const theme = localStorage.getItem("sentinel-theme") || localStorage.getItem("theme");
  if (theme === "light" || theme === "dark") {
    document.documentElement.setAttribute("data-theme", theme);
  }

  document.querySelectorAll(".reveal").forEach((el, i) => {
    el.style.transitionDelay = `${Math.min(i * 0.06, 0.35)}s`;
  });

  const revealIo = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-visible");
        }
      });
    },
    { threshold: 0.12, rootMargin: "0px 0px -8% 0px" }
  );
  document.querySelectorAll(".reveal").forEach((el) => revealIo.observe(el));

  const layers = document.querySelectorAll(".layer-card");
  const layerIo = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        layers.forEach((el, i) => {
          window.setTimeout(() => {
            el.style.opacity = "1";
            el.style.transform = "none";
          }, i * 80);
        });
        layerIo.disconnect();
      });
    },
    { threshold: 0.15 }
  );
  if (layers.length) {
    layers.forEach((el) => {
      el.style.opacity = "0";
      el.style.transform = "translateY(12px)";
      el.style.transition = "opacity 0.55s cubic-bezier(0.22, 1, 0.36, 1), transform 0.55s cubic-bezier(0.22, 1, 0.36, 1)";
    });
    layerIo.observe(layers[0].parentElement);
  }

  const counter = document.querySelector("[data-count]");
  if (counter) {
    const target = Number(counter.getAttribute("data-count") || "0");
    const duration = 900;
    const start = performance.now();
    const tick = (now) => {
      const t = Math.min(1, (now - start) / duration);
      const eased = 1 - (1 - t) ** 3;
      counter.textContent = String(Math.round(target * eased));
      if (t < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }

  const visual = document.querySelector(".corp-card-visual");
  if (visual && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    window.addEventListener(
      "pointermove",
      (e) => {
        const x = (e.clientX / window.innerWidth - 0.5) * 10;
        const y = (e.clientY / window.innerHeight - 0.5) * 6;
        visual.style.transform = `translate(${x}px, ${y}px)`;
      },
      { passive: true }
    );
  }
})();

