/** Shared Product AI / NOC Copilot engineer portrait. */
export const AI_ENGINEER_AVATAR_SRC = "/avatars/sentinel-ai-engineer.png";

type AiEngineerAvatarProps = {
  size?: "sm" | "md" | "lg" | "fab";
