export default function AiEngineerAvatar({
  size = "md",
  className = "",
  thinking = false,
  alt = "SentinelAI Engineer",
  speakWelcome = false,
  onClick,
}: AiEngineerAvatarProps) {
  const decorative = !alt && !speakWelcome && !onClick;
