import { useCallback, useEffect, useState } from "react";
import { Send, Sparkles, X } from "lucide-react";
import { chatbotChat } from "../api/client";
import AiEngineerAvatar from "./AiEngineerAvatar";
import { useChatMessageScroll } from "../hooks/useChatMessageScroll";
import {
  playSentinelWelcomeAudio,
  preloadSentinelWelcomeAudio,
} from "../utils/sentinelWelcomeAudio";

interface ChatMessage {
  role: "user" | "assistant";
  text: string;
}

export default function ChatbotWidget() {
  const [open, setOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      role: "assistant",
      text: "Product AI · SentinelAI\nPergunte sobre módulos, Zion, Alertas, Guardian, Plataforma ou DeepSeek. Pedidos que possam prejudicar a rede ou expor segredos são bloqueados.",
    },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const messagesScrollRef = useChatMessageScroll(messages.length, loading, open);

  useEffect(() => {
    preloadSentinelWelcomeAudio();
  }, []);

  const send = useCallback(async () => {
    const text = input.trim();
    if (!text || loading) return;
    setInput("");
    setMessages((m) => [...m, { role: "user", text }]);
    setLoading(true);
    try {
      const history = messages.slice(-6).map((m) => ({ role: m.role, content: m.text }));
      const res = await chatbotChat(text, history);
      setMessages((m) => [...m, { role: "assistant", text: res.answer }]);
    } catch (e) {
      setMessages((m) => [...m, { role: "assistant", text: String(e) }]);
    } finally {
      setLoading(false);
    }
  }, [input, loading, messages]);

  return (
    <div className="sa-chatbot-widget">
      {open && (
        <div className="sa-chatbot-panel" role="dialog" aria-label="Chatbot SentinelAI">
          <div className="sa-chatbot-fx" aria-hidden>
            <span className="sa-chatbot-fx-grid" />
            <span className="sa-chatbot-fx-scan" />
            <span className="sa-chatbot-fx-glow" />
          </div>

          <div className="sa-chatbot-panel-header">
            <div className="sa-chatbot-panel-title">
              <AiEngineerAvatar size="md" thinking={loading} speakWelcome alt="Product AI" />
              <div>
                <strong>Product AI</strong>
                <span className="sa-chatbot-panel-sub">Canon Engine · knowledge corpus</span>
              </div>
            </div>
            <div className="sa-chatbot-panel-meta">
              <span className={`sa-chatbot-status${loading ? " sa-chatbot-status-busy" : ""}`}>
                <Sparkles size={11} />
                {loading ? "inferindo" : "online"}
              </span>
              <button
                type="button"
                className="sa-btn sa-btn-ghost sa-btn-icon"
                onClick={() => setOpen(false)}
                aria-label="Fechar"
              >
                <X size={16} />
              </button>
            </div>
          </div>

          <div className="sa-chatbot-panel-body" ref={messagesScrollRef}>
            {messages.map((msg, i) => (
              <div
                key={i}
                className={`sa-chatbot-msg-row sa-chatbot-msg-row-${msg.role}`}
              >
                {msg.role === "assistant" && (
                  <AiEngineerAvatar size="sm" alt="" />
                )}
                <div className={`sa-chatbot-bubble sa-chatbot-bubble-${msg.role}`}>
                  {msg.role === "assistant" && (
                    <span className="sa-chatbot-bubble-label" aria-hidden>
                      ASSISTANT
                    </span>
                  )}
                  {msg.text}
                </div>
              </div>
            ))}
            {loading && (
              <div className="sa-chatbot-msg-row sa-chatbot-msg-row-assistant" aria-live="polite">
                <AiEngineerAvatar size="sm" thinking alt="" />
                <div className="sa-chatbot-typing">
                  <span />
                  <span />
                  <span />
                </div>
              </div>
            )}
          </div>

          <div className="sa-chatbot-panel-footer">
            <input
              className="sa-input sa-chatbot-input"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && send()}
              placeholder="Consulta ao corpus SentinelAI…"
              disabled={loading}
            />
            <button
              type="button"
              className="sa-btn sa-btn-primary sa-btn-icon sa-chatbot-send"
              onClick={send}
              disabled={loading}
              aria-label="Enviar"
            >
              <Send size={16} />
            </button>
          </div>
        </div>
      )}
      <button
        type="button"
        className={`sa-chatbot-fab${open ? " sa-chatbot-fab-open" : ""}`}
        onClick={() => {
          // Speak in the same user-gesture tick (not inside setState updater).
          if (!open) playSentinelWelcomeAudio();
          setOpen((v) => !v);
        }}
        title="Product AI — Chatbot SentinelAI"
        aria-label="Abrir chatbot"
      >
        <span className="sa-chatbot-fab-ring" aria-hidden />
        {open ? <X size={22} /> : <AiEngineerAvatar size="fab" alt="" />}
      </button>
    </div>
  );
}

