      if (version === "v2c") {
        if (community.trim()) snmp.community = community.trim();
      } else {
        if (username.trim()) snmp.username = username.trim();
        snmp.auth_protocol = authProtocol;
        snmp.priv_protocol = privProtocol;
        snmp.security_level = securityLevel;
        if (authKey.trim()) snmp.auth_key = authKey.trim();
        if (privKey.trim()) snmp.priv_key = privKey.trim();
