      const body: import("../api/client").CollectAuthUpdate = {
        snmp,
        wmi: {
          username: wmiUser.trim() || undefined,
          password: wmiPass.trim() || undefined,
          domain: wmiDomain.trim() || undefined,
        },
        ssh: {
          username: sshUser.trim() || undefined,
          password: sshPass.trim() || undefined,
        },
      };
      const updated = await updateDeviceCollectAuth(deviceId, body);
      setView(updated);
      setCommunity("");
      setAuthKey("");
      setPrivKey("");
      setWmiPass("");
      setSshPass("");
      setMessage("Credenciais salvas (secrets criptografados).");
    } catch (err) {
