    <div className="sa-stack" style={{ gap: "1rem" }}>
      <p className="sa-devpanel-meta">
        <KeyRound size={12} style={{ marginRight: 6, verticalAlign: "middle" }} />
        Senhas e communities nunca são exibidas após salvar. Cascata: device → tag → site → .env.
        Fonte atual: <code className="sa-devpanel-mono">{String(effective?.source || view?.resolved_from || "settings")}</code>
        {effective?.version ? ` · SNMP ${String(effective.version)}` : ""}
      </p>

      {error && <div className="sa-alert sa-alert-info">{error}</div>}
      {message && <div className="sa-alert sa-alert-success">{message}</div>}

      <fieldset disabled={!canWrite} className="sa-devpanel-block">
        <legend>SNMP</legend>
        <div className="sa-devpanel-grid">
          <label>
            Versão
            <select className="sa-input" value={version} onChange={(e) => setVersion(e.target.value as "v2c" | "v3")}>
              <option value="v2c">SNMPv2c</option>
              <option value="v3">SNMPv3</option>
            </select>
          </label>
          {version === "v2c" ? (
