        : d.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
    return { time, value: m.value, name: m.metric_name };
  });

  const unit =
    series[0]?.unit ||
    (LATENCY_METRICS.has(selected) ? "ms" : PERFORMANCE_SET.has(selected) && selected !== "temperature_c" ? "%" : selected === "temperature_c" ? "°C" : "");

  if (loading) {
    return (
      <p className="sa-empty">
        <span className="sa-spinner" /> Carregando métricas...
      </p>
    );
  }

  return (
    <div className="sa-stack" style={{ gap: "var(--sa-space-md)" }}>
      {sla && (
        <div className="sa-platform-pane-kpis" style={{ padding: 0, gridTemplateColumns: "repeat(3, minmax(0, 1fr))" }}>
          <article className="sa-platform-pane-kpi sa-platform-pane-kpi-ok">
