              <option key={t} value={t}>{t.toUpperCase()}</option>
            ))}
          </select>
          <input
            className="sa-input"
            placeholder="Target (URL ou host:porta)"
            value={form.target}
            onChange={(e) => setForm({ ...form, target: e.target.value })}
          />
          <input
            className="sa-input"
            type="number"
            min={15}
            max={3600}
            value={form.interval_seconds}
            onChange={(e) => setForm({ ...form, interval_seconds: Number(e.target.value) })}
            style={{ width: 100 }}
          />
          <button type="submit" className="sa-btn sa-btn-primary">Adicionar</button>
        </form>
      )}
      {monitors.length === 0 ? (
        <p className="sa-empty">Nenhum monitor configurado (ping é criado automaticamente).</p>
      ) : (
        <div className="sa-table-wrap sa-devpanel-table">
          <table className="sa-table">
            <thead>
              <tr>
                <th>Tipo</th>
                <th>Target</th>
                <th>Intervalo</th>
                <th>Status</th>
                {canWrite && <th />}
              </tr>
            </thead>
            <tbody>
              {monitors.map((m) => (
                <tr key={m.id}>
