}

import { type NodeProps } from "@xyflow/react";
import { Pencil, Trash2 } from "lucide-react";
import { useEffect, useRef, type CSSProperties } from "react";
import { getDeviceEmoji, getDeviceTypeColor, getDeviceTypeLabel } from "../constants/deviceTypes";
import { useMapActions } from "../context/MapActionsContext";
import MapNodeHandles from "./map/MapNodeHandles";

const AWAITING_MAX_MS = 90_000;

export default function DeviceNode({ data, selected }: NodeProps) {
  const { canWrite, onDeleteDevice, onEditDevice } = useMapActions();
  const status = String(data.status ?? "").toLowerCase();
  const deviceType = (data.device_type as string) || "unknown";
  const deviceId = data.device_id as number | undefined;
  const zionxdrEndpoint = data.zionxdr_endpoint as { endpoint_id: number; name: string } | undefined;
  const ip = String(data.ip_address ?? "—");
  const name = String(data.label ?? "");
  const deviceLabel = name && name !== ip ? name : getDeviceTypeLabel(deviceType);
  const typeColor = getDeviceTypeColor(deviceType);
  const isOnline = status === "active";
  // Amarelo só se já ficou online no mapa (flag explícita) — não usar last_seen histórico
  const wasEverOnline = Boolean(data.was_ever_online) || isOnline;
  const showDownAlert = !isOnline && wasEverOnline;

  // "Aguardando ping" só durante a janela curta após adicionar no mapa.
  // UNKNOWN antigo / refresh falho → Offline (nunca fica preso).
  const pingPending = Boolean(data.ping_pending);
  const pendingSince = Number(data.ping_pending_since ?? 0);
  const pendingFresh = !pendingSince || Date.now() - pendingSince < AWAITING_MAX_MS;
  const isAwaiting =
    pingPending &&
    pendingFresh &&
    !isOnline &&
    (status === "unknown" || status === "pending" || status === "");

  const statusClass = isOnline
    ? "sa-topo-node-online"
    : showDownAlert
      ? "sa-topo-node-down-alert"
      : isAwaiting
        ? "sa-topo-node-unknown"
        : "sa-topo-node-offline";

  const ref = useRef<HTMLDivElement>(null);
  const prevStatus = useRef(status);

  useEffect(() => {
    if (prevStatus.current !== status && ref.current) {
      ref.current.classList.add("sa-topo-node-pulse");
      const timer = setTimeout(() => ref.current?.classList.remove("sa-topo-node-pulse"), 800);
      prevStatus.current = status;
      return () => clearTimeout(timer);
    }
    prevStatus.current = status;
  }, [status]);

  return (
    <div
      className="sa-map-node-frame"
      style={{ "--sa-topo-type-color": typeColor } as CSSProperties}
    >
      <MapNodeHandles connectable={canWrite} />
      {showDownAlert && <span className="sa-topo-node-alert-ring" aria-hidden="true" />}
      {!isOnline && !showDownAlert && !isAwaiting && (
        <span className="sa-topo-node-offline-ring" aria-hidden="true" />
      )}
      {canWrite && deviceId != null && (
        <div className="sa-topo-node-actions">
          {onEditDevice && (
            <button
              type="button"
              className="sa-topo-node-edit"
              title={`Editar IP de ${deviceLabel}`}
              onClick={(e) => {
                e.stopPropagation();
                e.preventDefault();
                onEditDevice(deviceId, deviceLabel, ip);
              }}
            >
              <Pencil size={11} />
            </button>
          )}
          <button
            type="button"
            className="sa-topo-node-delete"
            title={`Remover ${deviceLabel}`}
            onClick={(e) => {
              e.stopPropagation();
              onDeleteDevice(deviceId, deviceLabel, ip);
            }}
          >
            <Trash2 size={12} />
          </button>
        </div>
      )}
      <div
        ref={ref}
        className={`sa-topo-node ${statusClass}${selected ? " sa-topo-node-selected" : ""}`}
        style={
          {
            border: showDownAlert ? undefined : `3px solid ${typeColor}`,
            background: "var(--sa-surface)",
            ...(isOnline
              ? {
                  /* Volta à cor normal do desenho ao ficar online */
                  filter: "none",
                  boxShadow: "var(--sa-shadow-sm)",
                }
              : {}),
          } as CSSProperties
        }
        title={`${deviceLabel}${ip ? ` · ${ip}` : ""}`}
      >
        <div className="sa-topo-node-icon">{getDeviceEmoji(deviceType)}</div>
        <strong>{deviceLabel}</strong>
        <small>{ip}</small>
        {zionxdrEndpoint && (
          <button
            type="button"
            className="sa-topo-xdr-badge"
            title={`Abrir ZionXDR · ${zionxdrEndpoint.name}`}
            onClick={(e) => {
              e.stopPropagation();
              window.location.hash = `zionxdr?endpoint_id=${zionxdrEndpoint.endpoint_id}`;
              window.dispatchEvent(new CustomEvent("sentinel:open-zionxdr"));
            }}
          >
            XDR
          </button>
        )}
        <span className="sa-topo-status-pill">
          {isOnline ? "Online" : showDownAlert ? "Alerta" : isAwaiting ? "Aguardando…" : "Offline"}
        </span>
      </div>
    </div>
