export type StatusFocusKind =
  | "online"
  | "offline"
  | "alert"
  | "offline_30m"
  | "occ_no_comm"
  | "occ_ping"
  | "occ_agent"
  | "occ_computers";

export interface StatusFocus {
  kind: StatusFocusKind;
  label: string;
  deviceIds: number[];
}

