  activeFocusKind?: StatusFocusKind | null;
}

const STATUS_COLORS = {
  online: "var(--sa-success)",
  offline: "var(--sa-danger)",
  alert: "var(--sa-warning)",
} as const;

function minutesSince(iso: string | null | undefined): number | null {
  if (!iso) return null;
  const t = new Date(iso).getTime();
  if (Number.isNaN(t)) return null;
  return (Date.now() - t) / 60_000;
}

const COMPUTER_TYPES = new Set(["desktop", "laptop", "server", "vm", "computer", "pc", "workstation"]);

function isComputerDevice(device: Device): boolean {
  const type = String(device.device_type || "").toLowerCase();
  if (COMPUTER_TYPES.has(type)) return true;
  const os = String(device.os_name || "").toLowerCase();
  return (
    os.includes("windows") ||
    os.includes("linux") ||
    os.includes("ubuntu") ||
    os.includes("macos") ||
    os.includes("mac os")
  );
}

function isAgentDisconnected(device: Device): boolean {
  const extra = device.extra_data || {};
  const agent = (extra.agent || extra.lab_agent || null) as Record<string, unknown> | null;
  if (!agent || typeof agent !== "object") return false;
  if (agent.reachable === false || agent.connected === false) return true;
  const status = String(agent.status || agent.state || "").toLowerCase();
  return status.includes("disconnect") || status === "offline" || status === "down";
}

function formatUpdatedAgo(seconds: number): string {
  if (seconds < 5) return "Atualizado agora";
  if (seconds < 60) return `Atualizado há ${seconds} segundos`;
  const mins = Math.floor(seconds / 60);
  if (mins === 1) return "Atualizado há 1 minuto";
  if (mins < 60) return `Atualizado há ${mins} minutos`;
  return "Atualizado há mais de 1 hora";
}

