import { useEffect, useState } from "react";
import { ShieldCheck } from "lucide-react";
import { disableMfa, enableMfa, fetchMe, formatApiError, setupMfa } from "../api/client";

export default function MfaSettingsPanel() {
  const [enabled, setEnabled] = useState(false);
  const [secret, setSecret] = useState<string | null>(null);
  const [qr, setQr] = useState<string | null>(null);
  const [code, setCode] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [manageOpen, setManageOpen] = useState(false);

  useEffect(() => {
    fetchMe()
      .then((me) => setEnabled(Boolean(me.mfa_enabled)))
      .catch(() => undefined);
  }, []);

  async function handleSetup() {
    setBusy(true);
    setError(null);
    setMessage(null);
    try {
      const data = await setupMfa();
      setSecret(data.secret);
      setQr(data.qr_png_base64);
      setEnabled(false);
      setManageOpen(true);
      setMessage("Escaneie o QR no autenticador e confirme com o código de 6 dígitos.");
    } catch (err) {
      setError(formatApiError(err));
    } finally {
      setBusy(false);
    }
  }

  async function handleEnable() {
    setBusy(true);
    setError(null);
    try {
      await enableMfa(code);
      setEnabled(true);
      setSecret(null);
      setQr(null);
      setCode("");
      setManageOpen(false);
      setMessage("MFA ativado. O próximo login pedirá o código TOTP.");
    } catch (err) {
      setError(formatApiError(err));
    } finally {
      setBusy(false);
    }
  }

  async function handleDisable() {
    setBusy(true);
    setError(null);
    try {
      await disableMfa(password, code);
      setEnabled(false);
      setSecret(null);
      setQr(null);
      setCode("");
      setPassword("");
      setManageOpen(false);
      setMessage("MFA desativado.");
    } catch (err) {
      setError(formatApiError(err));
    } finally {
      setBusy(false);
    }
  }

  const showBody = Boolean(message || error || secret || (enabled && manageOpen));

  return (
    <section className="sa-card sa-mfa-panel sa-users-create">
      <div className="sa-users-fx" aria-hidden>
        <span className="sa-users-fx-grid" />
        <span className="sa-users-fx-scan" />
      </div>

      <div className="sa-mfa-panel-head">
        <div className="sa-mfa-panel-copy">
          <span className="sa-icon-badge sa-mfa-panel-icon" aria-hidden>
            <ShieldCheck size={18} strokeWidth={1.75} />
          </span>
          <div>
            <h3 className="sa-mfa-panel-title">MFA TOTP</h3>
          </div>
        </div>

        <div className="sa-mfa-panel-rail">
          <span
            className={`sa-users-badge sa-mfa-status${enabled ? " sa-users-ldap-on sa-mfa-status--on" : " sa-mfa-status--off"}`}
          >
            {enabled ? "Ativo" : "Inativo"}
          </span>

          {!enabled && !secret && (
            <button type="button" className="sa-btn sa-btn-primary sa-btn-sm" disabled={busy} onClick={() => void handleSetup()}>
              {busy ? "Gerando…" : "Configurar MFA"}
            </button>
          )}

          {enabled && !secret && (
            <button
              type="button"
              className="sa-btn sa-btn-secondary sa-btn-sm"
              onClick={() => setManageOpen((v) => !v)}
            >
              {manageOpen ? "Fechar" : "Gerir MFA"}
            </button>
          )}

          {secret && (
            <button
              type="button"
              className="sa-btn sa-btn-ghost sa-btn-sm"
              disabled={busy}
              onClick={() => {
                setSecret(null);
                setQr(null);
                setCode("");
                setManageOpen(false);
              }}
            >
              Cancelar
            </button>
          )}
        </div>
      </div>

      {showBody && (
        <div className="sa-mfa-panel-body">
          {message && (
            <div className="sa-users-toast" role="status">
              {message}
            </div>
          )}
          {error && <div className="sa-alert sa-alert-error">{error}</div>}

          {secret && (
            <div className="sa-mfa-setup-grid">
              {qr && (
                <img
                  className="sa-mfa-qr"
                  src={`data:image/png;base64,${qr}`}
                  alt="QR code MFA"
                  width={160}
                  height={160}
                />
              )}
              <div className="sa-mfa-setup-fields">
                <p className="sa-mfa-secret">Secret: {secret}</p>
                <label className="sa-field">
                  <span className="sa-label">Código de confirmação</span>
                  <input
                    className="sa-input"
                    inputMode="numeric"
                    value={code}
                    onChange={(e) => setCode(e.target.value.replace(/\D/g, "").slice(0, 8))}
                    placeholder="123456"
                  />
                </label>
                <button
                  type="button"
                  className="sa-btn sa-btn-primary sa-btn-sm"
                  disabled={busy || code.length < 6}
                  onClick={() => void handleEnable()}
                >
                  Ativar MFA
                </button>
              </div>
            </div>
          )}

          {enabled && manageOpen && !secret && (
            <div className="sa-mfa-disable-grid">
              <label className="sa-field">
                <span className="sa-label">Senha atual</span>
                <input
                  className="sa-input"
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  autoComplete="current-password"
                />
              </label>
              <label className="sa-field">
                <span className="sa-label">Código MFA</span>
                <input
                  className="sa-input"
                  inputMode="numeric"
                  value={code}
                  onChange={(e) => setCode(e.target.value.replace(/\D/g, "").slice(0, 8))}
                  placeholder="123456"
                />
              </label>
              <button
                type="button"
                className="sa-btn sa-btn-secondary sa-btn-sm"
                disabled={busy || !password || code.length < 6}
                onClick={() => void handleDisable()}
              >
                Desativar MFA
              </button>
            </div>
          )}
        </div>
      )}
    </section>
  );
}

