  nodes: ZionvmTopologyNode[];
  totalCount?: number;
};

function statusMeta(status: string): {
  tone: "run" | "muted" | "bad" | "warn" | "info";
  live?: boolean | "danger";
  label: string;
} {
  const raw = (status || "unknown").trim();
  const s = raw.toLowerCase();
  if (s === "running") return { tone: "run", live: true, label: raw };
  if (s === "stopped") return { tone: "muted", live: "danger", label: raw };
  if (s.includes("error") || s.includes("fail")) return { tone: "bad", live: "danger", label: raw };
  if (s.includes("warn") || s === "paused") return { tone: "warn", label: raw };
  return { tone: "info", label: raw };
}

function openZionVm(deepLink?: string) {
  if (deepLink) {
    const hash = deepLink.replace(/^#/, "");
    window.location.hash = hash;
  } else {
    window.location.hash = "zionvm";
  }
  window.dispatchEvent(new CustomEvent("sentinel:open-zionvm"));
}

