/** Estado comum de painéis ZionVM: busy, feedback, reload. */
export function useZionvmPanelState(reload: () => Promise<void>) {
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const withBusy = useCallback(
    async (fn: () => Promise<void>) => {
      setBusy(true);
      setMessage(null);
      setError(null);
      try {
        await fn();
        await reload();
      } catch (e) {
        setError(e instanceof Error ? e.message : String(e));
      } finally {
        setBusy(false);
      }
    },
    [reload],
  );

  const refresh = useCallback(async () => {
    setError(null);
    try {
      await reload();
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, [reload]);

  return { busy, message, error, setMessage, setError, withBusy, refresh };
}

import { useCallback, useRef, useState } from "react";
import ZvmConfirmDialog, { type ZvmConfirmVariant } from "./ZvmConfirmDialog";

export type ZvmConfirmOptions = {
  title: string;
  message?: string;
  confirmLabel?: string;
  cancelLabel?: string;
  variant?: ZvmConfirmVariant;
  checkbox?: { label: string; defaultChecked?: boolean };
};

export type ZvmConfirmResult =
  | { confirmed: false }
  | { confirmed: true; checkbox?: boolean };

type Pending = ZvmConfirmOptions & { open: true };

export function useZvmConfirm() {
  const [pending, setPending] = useState<Pending | null>(null);
  const resolverRef = useRef<((r: ZvmConfirmResult) => void) | null>(null);

  const confirm = useCallback((opts: ZvmConfirmOptions) => {
    return new Promise<ZvmConfirmResult>((resolve) => {
      resolverRef.current = resolve;
      setPending({ ...opts, open: true });
    });
  }, []);

  const finish = (result: ZvmConfirmResult) => {
    setPending(null);
    const r = resolverRef.current;
    resolverRef.current = null;
    r?.(result);
  };

  const ConfirmDialog = pending ? (
    <ZvmConfirmDialog
      open
      title={pending.title}
      message={pending.message}
      confirmLabel={pending.confirmLabel}
      cancelLabel={pending.cancelLabel}
      variant={pending.variant}
      checkbox={pending.checkbox}
      onCancel={() => finish({ confirmed: false })}
      onConfirm={(checkbox) => finish({ confirmed: true, checkbox })}
    />
  ) : null;

  return { confirm, ConfirmDialog };
}

