/** Mensagem amigável para falhas da API ZionVM (evita "Not Found" cru no topo da UI). */
export function zvmApiError(e: unknown, context?: string): string {
  const err = e as Error & { status?: number };
  if (err.status === 404) {
    return (
      context ||
      "Recurso ou endpoint não encontrado (404). Reinicie o serviço api e aplique migrações: alembic upgrade head."
    );
  }
  if (err.status === 422) {
    return err.message || context || "Pedido inválido (422).";
  }
  if (err.status === 500 && (!err.message || err.message === "Internal Server Error")) {
    return (
      context ||
      "Erro interno na API (500). Se acabou de criar VM, reinicie o serviço api — VMID em conflito ou task pendente."
    );
  }
  return err.message || String(e);
}

