import { useEffect, useId, useState } from "react";
import { createPortal } from "react-dom";
import { AlertTriangle, ShieldAlert, X } from "lucide-react";
import ZvmActionButton from "./ZvmActionButton";

export type ZvmConfirmVariant = "danger" | "primary" | "default";

export type ZvmConfirmDialogProps = {
  open: boolean;
  title: string;
  message?: string;
  confirmLabel?: string;
  cancelLabel?: string;
  variant?: ZvmConfirmVariant;
  busy?: boolean;
  checkbox?: { label: string; defaultChecked?: boolean };
  onConfirm: (checkbox?: boolean) => void;
  onCancel: () => void;
};

export default function ZvmConfirmDialog({
  open,
  title,
  message,
  confirmLabel = "Confirmar",
  cancelLabel = "Cancelar",
  variant = "default",
  busy,
  checkbox,
  onConfirm,
  onCancel,
}: ZvmConfirmDialogProps) {
  const titleId = useId();
  const [checked, setChecked] = useState(checkbox?.defaultChecked ?? false);

  useEffect(() => {
    if (open) setChecked(checkbox?.defaultChecked ?? false);
  }, [open, checkbox?.defaultChecked]);

  useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !busy) onCancel();
    };
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = prev;
      window.removeEventListener("keydown", onKey);
    };
  }, [open, busy, onCancel]);

  if (!open) return null;

  const Icon = variant === "danger" ? ShieldAlert : AlertTriangle;

  return createPortal(
    <div
      className="zvm-ds-confirm-backdrop"
      role="presentation"
      onMouseDown={() => {
        if (!busy) onCancel();
      }}
    >
      <div
        className={`zvm-ds-confirm-dialog sa-corp-card zvm-ds-confirm-${variant}`}
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onMouseDown={(e) => e.stopPropagation()}
      >
        <span className="sa-corp-card-fx" aria-hidden>
          <span className="sa-corp-card-fx-grid" />
          <span className="sa-corp-card-fx-scan" />
        </span>
        <div className="zvm-ds-confirm-inner">
          <div className={`zvm-ds-confirm-icon zvm-ds-confirm-icon-${variant}`} aria-hidden>
            <Icon size={22} strokeWidth={2.1} />
          </div>
          <div className="zvm-ds-confirm-copy">
            <h3 id={titleId} className="zvm-ds-confirm-title">
              {title}
            </h3>
            {message ? <p className="zvm-ds-confirm-message">{message}</p> : null}
            {checkbox ? (
              <label className="zvm-ds-confirm-check">
                <input
                  type="checkbox"
                  checked={checked}
                  disabled={busy}
                  onChange={(e) => setChecked(e.target.checked)}
                />
                <span>{checkbox.label}</span>
              </label>
            ) : null}
          </div>
          <button
            type="button"
            className="zvm-ds-confirm-close"
            aria-label="Fechar"
            disabled={busy}
            onClick={onCancel}
          >
            <X size={18} />
          </button>
        </div>
        <div className="zvm-ds-confirm-actions">
          <ZvmActionButton variant="ghost" disabled={busy} onClick={onCancel}>
            {cancelLabel}
          </ZvmActionButton>
          <ZvmActionButton
            variant={variant === "danger" ? "danger" : "primary"}
            disabled={busy}
            onClick={() => onConfirm(checkbox ? checked : undefined)}
          >
            {confirmLabel}
          </ZvmActionButton>
        </div>
      </div>
    </div>,
    document.body,
  );
}

type Tab = {
  id: string;
  vmId: number;
  label: string;
};

type Props = {
  tabs: Tab[];
  activeId: string | null;
  onSelect: (id: string) => void;
