import { ChevronDown, ChevronUp } from "lucide-react";
import type { InputHTMLAttributes } from "react";

type Props = Omit<InputHTMLAttributes<HTMLInputElement>, "type" | "value" | "onChange"> & {
  label: string;
  value: number | "";
  onChange: (value: number | "") => void;
  step?: number;
  fieldClass?: string;
  allowEmpty?: boolean;
};

export default function ZvmNumberField({
  label,
  value,
  onChange,
  step = 1,
  min,
  max,
  fieldClass = "",
  className = "",
  allowEmpty = false,
  ...rest
}: Props) {
  const clamp = (n: number) => {
    let v = n;
    if (typeof min === "number") v = Math.max(min, v);
    if (typeof max === "number") v = Math.min(max, v);
    return v;
  };

  const bump = (delta: number) => {
    const base = typeof value === "number" && Number.isFinite(value) ? value : typeof min === "number" ? min : 0;
    onChange(clamp(base + delta));
  };

  return (
    <div className={`zvm-ds-form-field zvm-ds-number-field ${fieldClass}`.trim()}>
      <span className="zvm-ds-form-label">{label}</span>
      <div className="zvm-ds-number-wrap">
        <input
          {...rest}
          type="number"
          className={`zvm-ds-number-input ${className}`.trim()}
          value={typeof value === "number" && Number.isFinite(value) ? value : ""}
          step={step}
          min={min}
          max={max}
          onChange={(e) => {
            const raw = e.target.value;
            if (raw === "" && allowEmpty) {
              onChange("");
              return;
            }
            const n = Number(raw);
            if (!Number.isFinite(n)) {
              if (allowEmpty) onChange("");
              return;
            }
            onChange(clamp(n));
          }}
        />
        <div className="zvm-ds-number-stepper">
          <button
            type="button"
            className="zvm-ds-number-step zvm-ds-number-step-up"
            aria-label={`Aumentar ${label}`}
            tabIndex={-1}
            onClick={() => bump(step)}
          >
            <ChevronUp size={13} strokeWidth={2.4} aria-hidden />
          </button>
          <button
            type="button"
            className="zvm-ds-number-step zvm-ds-number-step-down"
            aria-label={`Diminuir ${label}`}
            tabIndex={-1}
            onClick={() => bump(-step)}
          >
            <ChevronDown size={13} strokeWidth={2.4} aria-hidden />
          </button>
        </div>
        <span className="zvm-ds-number-fx" aria-hidden />
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

type Props = {
  wsUrl: string;
  className?: string;
};

function loadSpiceGlobal(): Promise<ZvmSpiceClientGlobal> {
  if (window.SpiceClient) return Promise.resolve(window.SpiceClient);

  return new Promise((resolve, reject) => {
    const done = () => {
      if (window.SpiceClient) resolve(window.SpiceClient);
      else reject(new Error("SpiceClient global não encontrado após carregar script."));
    };

    const existing = document.querySelector<HTMLScriptElement>('script[data-zvm-spice="1"]');
    if (existing) {
      if (window.SpiceClient) {
        done();
        return;
      }
      existing.addEventListener("load", done, { once: true });
      existing.addEventListener(
        "error",
        () => reject(new Error("Falha ao carregar spice-client.min.js")),
        { once: true },
      );
      return;
    }

    const script = document.createElement("script");
    script.src = "/zionvm/spice-client.min.js";
    script.async = true;
    script.dataset.zvmSpice = "1";
    script.onload = () => done();
    script.onerror = () =>
      reject(
        new Error(
          "Ficheiro /zionvm/spice-client.min.js em falta — no container frontend: npm install (postinstall copia o bundle).",
        ),
      );
    document.head.appendChild(script);
  });
}

export default function ZvmSpiceConsole({ wsUrl, className = "" }: Props) {
  const screenRef = useRef<HTMLDivElement>(null);
  const connRef = useRef<ZvmSpiceMainConn | null>(null);
  const [status, setStatus] = useState<"connecting" | "connected" | "disconnected">("connecting");
  const [detail, setDetail] = useState<string | null>(null);

  useEffect(() => {
    const screen = screenRef.current;
    if (!screen || !wsUrl) return;

    let cancelled = false;
    setStatus("connecting");
    setDetail(null);
    screen.innerHTML = "";

    void (async () => {
      try {
        const SpiceClient = await loadSpiceGlobal();
        if (cancelled) return;
        const spice = new SpiceClient.SpiceMainConn({
          uri: wsUrl,
          password: "",
          screen_id: "zvm-spice-screen",
          onsuccess: () => {
            if (!cancelled) setStatus("connected");
          },
          onerror: (e: unknown) => {
            if (!cancelled) {
              setStatus("disconnected");
              setDetail(String(e instanceof Error ? e.message : e));
            }
          },
        });
        spice.on("connection_status", (st: unknown) => {
          if (cancelled) return;
          if (st === "connected") setStatus("connected");
          if (st === "disconnected" || st === "error") setStatus("disconnected");
        });
        connRef.current = spice;
      } catch (e) {
        if (!cancelled) {
          setStatus("disconnected");
          setDetail(e instanceof Error ? e.message : String(e));
        }
      }
    })();

    return () => {
      cancelled = true;
      try {
        connRef.current?.disconnect?.();
      } catch {
        /* ignore */
      }
      connRef.current = null;
    };
  }, [wsUrl]);

  return (
    <div className={`zvm-vnc-wrap zvm-spice-wrap ${className}`.trim()}>
      {status !== "connected" && (
        <p className="zvm-vnc-status" role="status">
          {status === "connecting" ? "A ligar ao console SPICE…" : detail || "Desligado"}
        </p>
      )}
      <div
        id="zvm-spice-screen"
        ref={screenRef}
        className="zvm-spice-screen"
        aria-label="VM console SPICE"
      />
    </div>
  );
}

