import { useEffect, useState, type ReactNode } from "react";

export type ZvmTabItem = {
  id: string;
  label: ReactNode;
};

type Props = {
  tabs: ZvmTabItem[];
  active: string;
  onChange: (id: string) => void;
  /** Persiste aba em sessionStorage (ex.: zionvm.permissions.tab) */
  storageKey?: string;
  ariaLabel?: string;
};

export function useZvmTabState(tabs: ZvmTabItem[], storageKey?: string) {
  const defaultId = tabs[0]?.id ?? "";
  const [active, setActive] = useState(() => {
    if (storageKey && typeof window !== "undefined") {
      const saved = sessionStorage.getItem(storageKey);
      if (saved && tabs.some((t) => t.id === saved)) return saved;
    }
    return defaultId;
  });

  useEffect(() => {
    if (storageKey) sessionStorage.setItem(storageKey, active);
  }, [active, storageKey]);

  return [active, setActive] as const;
}

export default function ZvmTabs({ tabs, active, onChange, ariaLabel }: Props) {
  return (
    <nav className="zvm-ds-tabs" aria-label={ariaLabel ?? "Seções"}>
      {tabs.map((t) => (
        <button
          key={t.id}
          type="button"
          className={`zvm-ds-tab${active === t.id ? " zvm-ds-tab-active" : ""}`}
          aria-selected={active === t.id}
          onClick={() => onChange(t.id)}
        >
          {t.label}
        </button>
      ))}
    </nav>
  );
}

