import { useEffect, useRef, useState } from "react";
import RFB from "@novnc/novnc";

type Props = {
  wsUrl: string;
  className?: string;
};

export default function ZvmVncConsole({ wsUrl, className = "" }: Props) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rfbRef = useRef<RFB | null>(null);
  const [status, setStatus] = useState<"connecting" | "connected" | "disconnected">("connecting");
  const [detail, setDetail] = useState<string | null>(null);

  useEffect(() => {
    const el = canvasRef.current;
    if (!el || !wsUrl) return;

    setStatus("connecting");
    setDetail(null);
    const rfb = new RFB(el, wsUrl);
    rfb.scaleViewport = true;
    rfb.resizeSession = true;
    rfb.background = "#0c1219";
    rfbRef.current = rfb;
    const rfbEvents = rfb as RFB & Pick<EventTarget, "addEventListener" | "removeEventListener">;

    const onConnect = () => {
      setStatus("connected");
      setDetail(null);
    };
    const onDisconnect = (ev: CustomEvent<{ clean?: boolean; detail?: { reason?: string } }>) => {
      setStatus("disconnected");
      const reason = ev.detail?.detail?.reason;
      setDetail(reason || (ev.detail?.clean ? "Sessão encerrada" : "Ligação VNC perdida"));
    };

    rfbEvents.addEventListener("connect", onConnect);
    rfbEvents.addEventListener("disconnect", onDisconnect as EventListener);

    return () => {
      rfbEvents.removeEventListener("connect", onConnect);
      rfbEvents.removeEventListener("disconnect", onDisconnect as EventListener);
      try {
        rfb.disconnect();
      } catch {
        /* ignore */
      }
      rfbRef.current = null;
    };
  }, [wsUrl]);

  return (
    <div className={`zvm-vnc-wrap ${className}`.trim()}>
      {status !== "connected" && (
        <p className="zvm-vnc-status" role="status">
          {status === "connecting" ? "A ligar ao console VNC…" : detail || "Desligado"}
        </p>
      )}
      <canvas ref={canvasRef} className="zvm-vnc-canvas" aria-label="VM console VNC" />
    </div>
  );
}

