export type SocTone = "ok" | "watch" | "mitre" | "chain" | "critical" | "medium" | "high" | "low";

export function severityTone(sev?: string): SocTone {
  switch ((sev || "").toLowerCase()) {
    case "critical":
      return "critical";
    case "high":
      return "high";
    case "medium":
      return "medium";
    case "low":
    case "info":
      return "low";
    default:
      return "watch";
  }
}

export function alertSocTone(a: ZionxdrEagleAlert): SocTone {
  if (a.category === "correlation" || String(a.rule_id || "").startsWith("BEHAVIOR-")) return "chain";
  const score = a.risk_score ?? 0;
  if (score >= 81 || (a.severity || "").toLowerCase() === "critical") return "critical";
  if (a.mitre_technique && score >= 61) return "mitre";
  return severityTone(a.severity);
}

export function categoryIcon(category?: string): LucideIcon {
  switch ((category || "").toLowerCase()) {
    case "powershell":
    case "script":
      return Terminal;
    case "ransomware":
      return Skull;
    case "credentials":
      return KeyRound;
    case "c2":
    case "lateral":
    case "discovery":
      return Network;
    case "office":
    case "lolbins":
      return Crosshair;
    case "persistence":
    case "evasion":
      return ShieldAlert;
    case "correlation":
      return Activity;
    case "files":
    case "fileless":
      return FileWarning;
    default:
      return Shield;
  }
}

export function riskLabel(score?: number): string {
  if (score == null) return "—";
  if (score >= 81) return "CRITICAL";
  if (score >= 61) return "HIGH";
  if (score >= 31) return "MEDIUM";
  return "LOW";
}

export function ruleSearchBlob(r: ZionxdrEagleRule): string {
  return [r.id, r.name, r.description, r.category, r.mitre_tactic, r.mitre_technique, r.severity, r.action]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

export function alertSearchBlob(a: ZionxdrEagleAlert): string {
  return [
    a.rule_id,
    a.rule_name,
    a.description,
    a.detail,
    a.process?.name,
    a.process?.parent_name,
    a.process?.cmdline,
    a.process?.username,
    a.mitre_tactic,
    a.mitre_technique,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

