};

const SHORT_HINTS: Record<string, string> = {
  reverse_dns_scan: "Detecção de consultas reversas anômalas.",
  port_scan: "Ferramentas e padrões de varredura de portas.",
  port_sweep: "Varredura ampla de hosts/portas na rede.",
  stealth_http: "Tráfego HTTP ofuscado ou low-and-slow.",
  tor_activity: "Uso de TOR / onion routing no endpoint.",
};

export function normalizeSecState(status?: string): SecState {
  switch ((status || "").toLowerCase()) {
    case "endpoint":
    case "siem":
    case "active":
    case "ativo":
      return "ativo";
    case "partial":
    case "parcial":
      return "parcial";
    case "planned":
    case "planejado":
      return "planejado";
    case "unavailable":
    case "indisponivel":
    case "down":
    case "missing":
      return "indisponivel";
    case "analyzing":
    case "em_analise":
    case "analysis":
      return "em_analise";
    default:
      return "planejado";
  }
}

export const SEC_STATE_LABEL: Record<SecState, string> = {
  ativo: "ATIVO",
  parcial: "PARCIAL",
  planejado: "PLANEJADO",
  indisponivel: "INDISPONÍVEL",
  em_analise: "EM ANÁLISE",
};

export function controlOrigin(status?: string): string {
  switch ((status || "").toLowerCase()) {
    case "siem":
      return "SIEM";
    case "endpoint":
      return "Endpoint";
    case "partial":
      return "Endpoint";
    case "planned":
      return "Rede / SIEM";
    default:
      return "Endpoint";
  }
}

export function controlTitle(item: ZionxdrCoverageItem): string {
  if (item.id && SHORT_NAMES[item.id]) return SHORT_NAMES[item.id];
  return item.name || item.id || "Controle";
}

export function controlHint(item: ZionxdrCoverageItem): string | undefined {
  if (item.id && SHORT_HINTS[item.id]) return SHORT_HINTS[item.id];
  const short = item.id ? SHORT_NAMES[item.id] : undefined;
  if (short && item.name && short !== item.name) return item.name;
  return undefined;
}

export function pillarAccent(pillarId?: string): PillarAccent {
  const id = (pillarId || "").toLowerCase();
  if (id.includes("network") || id.includes("threat")) return "network";
  if (id.includes("adversar") || id.includes("tactic")) return "tactics";
  if (id.includes("siem") || id.includes("audit") || id.includes("log")) return "siem";
  return "default";
}

export function pillarIcon(accent: PillarAccent): LucideIcon {
  switch (accent) {
    case "network":
      return Shield;
    case "tactics":
      return Crosshair;
    case "siem":
      return Database;
    default:
      return Activity;
  }
}

export function pillarCoveragePct(pillar: ZionxdrCoveragePillar): number {
  const total = pillar.summary?.total ?? pillar.items?.length ?? 0;
  if (!total) return 0;
  const active = (pillar.items || []).filter((it) => {
    const s = normalizeSecState(it.status);
    return s === "ativo" || s === "parcial";
  }).length;
  return Math.round((active / total) * 100);
}

export function itemCoveragePct(item: ZionxdrCoverageItem): number {
  const linked = item.rules?.length ?? 0;
  const missing = item.rules_missing?.length ?? 0;
  const total = linked + missing;
  if (total > 0) return Math.round((linked / total) * 100);
  const s = normalizeSecState(item.status);
  if (s === "ativo") return 100;
  if (s === "parcial") return 55;
  if (s === "em_analise") return 35;
  if (s === "indisponivel") return 0;
  return 15;
}

export type CoverageKpis = {
  controles: number;
  ativos: number;
  parciais: number;
  planejados: number;
  alertas: number;
};

export function aggregateCoverageKpis(pillars: ZionxdrCoveragePillar[]): CoverageKpis {
  let controles = 0;
  let ativos = 0;
  let parciais = 0;
  let planejados = 0;
  let alertas = 0;
  for (const p of pillars) {
    for (const it of p.items || []) {
      controles += 1;
      alertas += it.alert_hits ?? 0;
      const s = normalizeSecState(it.status);
      if (s === "ativo") ativos += 1;
      else if (s === "parcial") parciais += 1;
      else if (s === "planejado") planejados += 1;
    }
  }
  return { controles, ativos, parciais, planejados, alertas };
}

import { useCallback, useEffect, useRef, useState } from "react";

/** Fade nas bordas + glow do thumb enquanto rola (scroll principal da página). */
export function useZionxdrScrollChrome() {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [edges, setEdges] = useState({ top: false, bottom: false });
  const [scrolling, setScrolling] = useState(false);
  const scrollTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const updateEdges = useCallback(() => {
    const el = scrollRef.current;
    if (!el) {
      setEdges({ top: false, bottom: false });
      return;
    }
    const max = el.scrollHeight - el.clientHeight;
    if (max <= 2) {
      setEdges({ top: false, bottom: false });
      return;
    }
    setEdges({
      top: el.scrollTop > 4,
      bottom: el.scrollTop < max - 4,
    });
  }, []);

  useEffect(() => {
    updateEdges();
    const el = scrollRef.current;
    if (!el) return;

    const onScroll = () => {
      updateEdges();
      setScrolling(true);
      if (scrollTimer.current) clearTimeout(scrollTimer.current);
      scrollTimer.current = setTimeout(() => setScrolling(false), 700);
    };

    el.addEventListener("scroll", onScroll, { passive: true });
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(updateEdges) : null;
    ro?.observe(el);
    window.addEventListener("resize", updateEdges);

    return () => {
      el.removeEventListener("scroll", onScroll);
      ro?.disconnect();
      window.removeEventListener("resize", updateEdges);
      if (scrollTimer.current) clearTimeout(scrollTimer.current);
    };
  }, [updateEdges]);

  const scrollClassName = [
    "sa-type-scroll-shell",
    "zionxdr-page-scroll",
    "zvm-scroll",
    "zionxdr-scroll",
    edges.top ? "is-scrolled-top" : "",
    edges.bottom ? "is-scrolled-bottom" : "",
    scrolling ? "is-scrolling" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return { scrollRef, scrollClassName };
}

