function alertKey(a: ZionxdrEagleAlert): string {
  const p = a.process;
  return `${a.ts}|${a.rule_id}|${p?.pid}|${p?.name}`;
}

async function alertFingerprint(a: ZionxdrEagleAlert): Promise<string> {
  const p = a.process || {};
  const raw = [a.ts || "", a.rule_id || "", p.pid || "", p.name || ""].join("|");
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(raw));
  return Array.from(new Uint8Array(buf))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("")
    .slice(0, 64);
}

