type Props = {
  endpointId: number | null;
  onEndpointId: (id: number | null) => void;
};

export default function ZionXDREndpointBar({ endpointId, onEndpointId }: Props) {
  const { user } = useAuth();
  const isAdmin = user?.role === "admin";
  const [endpoints, setEndpoints] = useState<ZionxdrEndpoint[]>([]);
  const [tokenMsg, setTokenMsg] = useState<string | null>(null);
  const [tokenMsgOk, setTokenMsgOk] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [registerOpen, setRegisterOpen] = useState(false);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    try {
      const rows = await fetchZionxdrEndpoints();
      setLoadError(null);
      setEndpoints(rows);
      if (endpointId == null && rows.length) {
        const local = rows.find((r) => r.is_local) ?? rows[0];
        onEndpointId(local.id);
      }
    } catch (err) {
      const status = (err as Error & { status?: number }).status;
      setLoadError(
        status === 404
          ? "Rotas ZionXDR em falta (404) — reinicie o serviço api (Docker: docker compose restart api). Se persistir: alembic upgrade head"
          : err instanceof Error
            ? err.message
            : "Falha ao carregar endpoints",
      );
      setEndpoints([]);
    }
  }, [endpointId, onEndpointId]);

  useEffect(() => {
    void load();
    const id = setInterval(() => void load(), 15000);
    return () => clearInterval(id);
  }, [load]);

  const selected = endpoints.find((e) => e.id === endpointId);

  const onSyncAlerts = async () => {
    setBusy(true);
    try {
      const res = await syncZionxdrEagleAlerts(endpointId);
      setTokenMsgOk(true);
      setTokenMsg(`${res.events_created} evento(s) enviado(s) ao módulo Alertas`);
    } catch (err) {
      setTokenMsgOk(false);
      setTokenMsg(err instanceof Error ? err.message : "Falha ao sincronizar");
    } finally {
      setBusy(false);
    }
  };

  const onIssueToken = async () => {
    if (!endpointId || selected?.is_local) return;
    setBusy(true);
    try {
      const out = await issueZionxdrAgentToken(endpointId);
      setTokenMsg(`Token emitido (copie agora): ${out.token.slice(0, 12)}…`);
      if (typeof navigator.clipboard?.writeText === "function") {
        await navigator.clipboard.writeText(out.token);
        setTokenMsg("Token copiado para a área de transferência");
      }
    } catch (err) {
      setTokenMsg(err instanceof Error ? err.message : "Falha ao emitir token");
    } finally {
      setBusy(false);
    }
  };

  const onRegisterSubmit = async (data: { name: string; hostname: string; os_platform: string }) => {
    setBusy(true);
    setTokenMsg(null);
    try {
      const row = await createZionxdrEndpoint({
        name: data.name,
        os_platform: data.os_platform,
        hostname: data.hostname || undefined,
      });
      await load();
      onEndpointId(row.id);
      setRegisterOpen(false);
      setTokenMsg(`Endpoint «${row.name}» cadastrado`);
    } catch (err) {
      setTokenMsg(err instanceof Error ? err.message : "Falha ao criar endpoint");
    } finally {
      setBusy(false);
    }
  };

  const emptyList = endpoints.length === 0;
  const statusTone =
    selected?.status === "online" ? "ok" : selected?.status === "offline" ? "warn" : "muted";

  return (
    <ZionXDRCorpSurface
      aria-label="Endpoints Eagle"
      className={`zionxdr-endpoint-bar${emptyList ? " zionxdr-endpoint-bar--empty" : ""}`}
    >
      <div id="zionxdr-endpoint-bar" className="zionxdr-endpoint-bar-inner">
        <header className="zionxdr-endpoint-head">
          <span className="sa-icon-badge" aria-hidden>
            <Crosshair size={18} strokeWidth={1.75} />
          </span>
          <div className="zionxdr-endpoint-head-copy">
            <strong className="zionxdr-endpoint-bar-title">Endpoints Eagle</strong>
          </div>
          {selected ? (
            <span className={`zionxdr-endpoint-status zionxdr-endpoint-status--${statusTone}`}>
              {selected.is_local ? "Local · " : ""}
              {selected.status}
            </span>
          ) : null}
        </header>

        <div className="zionxdr-endpoint-controls">
          <label className="zionxdr-endpoint-field" htmlFor="zionxdr-endpoint-select">
            <span className="zionxdr-endpoint-label">Selecionar endpoint</span>
            <select
              id="zionxdr-endpoint-select"
              className="sa-input zionxdr-endpoint-select zionxdr-corp-select"
              value={endpointId ?? ""}
              disabled={emptyList}
              onChange={(e) => onEndpointId(Number(e.target.value) || null)}
            >
              {emptyList ? (
                <option value="">Nenhum endpoint — cadastre abaixo</option>
              ) : (
                endpoints.map((ep) => (
                  <option key={ep.id} value={ep.id}>
                    {ep.name}
                    {ep.is_local ? " · control plane" : ""} · {ep.status}
                  </option>
                ))
              )}
            </select>
          </label>
          <div className="zionxdr-endpoint-actions">
            <button
              type="button"
              className="sa-btn sa-btn-secondary sa-btn-sm"
              disabled={busy || !endpointId}
              onClick={() => void onSyncAlerts()}
            >
              <RefreshCw size={14} aria-hidden /> Sync alertas
            </button>
            {isAdmin && !selected?.is_local && endpointId ? (
              <button type="button" className="sa-btn sa-btn-ghost sa-btn-sm" disabled={busy} onClick={() => void onIssueToken()}>
                Token agent
              </button>
            ) : null}
            {isAdmin ? (
              <button
                type="button"
                className="sa-btn sa-btn-primary sa-btn-sm"
                disabled={busy}
                title="Cadastrar máquina Windows para o agent Eagle"
                onClick={() => setRegisterOpen(true)}
              >
                + Cadastrar endpoint
              </button>
            ) : (
              <span className="zionxdr-endpoint-hint">Cadastro: perfil admin</span>
            )}
          </div>
        </div>

        {loadError ? <p className="zionxdr-endpoint-banner zionxdr-endpoint-error">{loadError}</p> : null}
        {tokenMsg ? (
          <p className={`zionxdr-endpoint-banner${tokenMsgOk ? " zionxdr-endpoint-ok" : " zionxdr-endpoint-error"}`}>


