      const ctx = await fetchZionxdrCopilotIncident({ event_id: eventId });
      const slug = playbook || ctx.suggested_playbook_slug;
      const res = await requestZionxdrHitl(ctx.endpoint_id, ctx.fingerprint, slug, reason);
      onMessage(res.message || "Pedido HITL criado");
      onClose();
    } catch (err) {
      onMessage(err instanceof Error ? err.message : "Falha ao criar HITL");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="zionxdr-hitl-backdrop" role="dialog" aria-modal="true" aria-label="HITL ZionXDR">
      <div className="zionxdr-hitl-card sa-corp-card">
        <h3>Pedido HITL — ZionXDR</h3>
        <p className="zionxdr-hitl-hint">Após aprovação (Platform → Autonomous), o agent executa o job Eagle.</p>
        <label className="zionxdr-hitl-field">
          Playbook
          <select value={playbook} disabled={busy} onChange={(e) => setPlaybook(e.target.value)}>
            <option value="zionxdr-collect-evidence">Coletar evidências</option>
            <option value="zionxdr-quarantine-file">Quarentena (lab)</option>
            <option value="zionxdr-isolate-endpoint">Isolar endpoint (stub)</option>
          </select>
        </label>
        <label className="zionxdr-hitl-field">
          Motivo
          <textarea value={reason} disabled={busy} rows={3} onChange={(e) => setReason(e.target.value)} />
        </label>
        <div className="zionxdr-hitl-actions">
          <button type="button" className="sa-btn sa-btn-secondary" disabled={busy} onClick={onClose}>
            Cancelar
          </button>
          <button type="button" className="sa-btn sa-btn-primary" disabled={busy} onClick={() => void submit()}>
            Submeter HITL
          </button>
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { ShieldAlert } from "lucide-react";
import {
  fetchZionxdrCopilotIncident,
  requestZionxdrHitl,
} from "../../api/client";
import ZionXDRCorpSurface from "./ZionXDRCorpSurface";

type Props = {
  endpointId: number | null;
  fingerprint: string | null;
  eventId?: number | null;
};

export default function ZionXDRIncidentPanel({ endpointId, fingerprint, eventId }: Props) {
  const [summary, setSummary] = useState<string | null>(null);
  const [playbook, setPlaybook] = useState<string | null>(null);
  const [hints, setHints] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);

  const load = async () => {
    if (eventId != null) {
      const ctx = await fetchZionxdrCopilotIncident({ event_id: eventId });
      setSummary(ctx.summary);
      setPlaybook(ctx.suggested_playbook_slug);
      setHints(ctx.hints || []);
      return;
    }
    if (endpointId != null && fingerprint) {
      const ctx = await fetchZionxdrCopilotIncident({ endpoint_id: endpointId, fp: fingerprint });
      setSummary(ctx.summary);
      setPlaybook(ctx.suggested_playbook_slug);
      setHints(ctx.hints || []);
    }
  };

  const onHitl = async () => {
    if (endpointId == null || !fingerprint || !playbook) return;
    setBusy(true);
    setMsg(null);
    try {
      const res = await requestZionxdrHitl(endpointId, fingerprint, playbook);
      setMsg(`HITL #${res.approval_id} — ${res.message}`);
    } catch (err) {
      setMsg(err instanceof Error ? err.message : "Falha HITL");
    } finally {
      setBusy(false);
    }
  };

  if (endpointId == null) return null;

  return (
    <ZionXDRCorpSurface className="zionxdr-incident-panel" aria-label="Copilot incidente">
      <div className="zionxdr-policy-inner">
        <h3 className="zionxdr-policy-title">
          <ShieldAlert size={15} aria-hidden /> Incidente (S6)
        </h3>
        <p className="zionxdr-nms-muted zionxdr-incident-lede">
          Copilot resume o evento, sugere playbook e encaminha HITL quando aplicável.
        </p>
        <button
          type="button"
          className="sa-btn sa-btn-secondary sa-btn-sm zionxdr-incident-analyze"
          disabled={busy}
          onClick={() => void load().catch(() => setMsg("Sem contexto"))}
        >
          Analisar com Copilot
        </button>
        {summary && <p className="zionxdr-nms-line">{summary}</p>}
        {playbook && (
          <p className="zionxdr-nms-muted">
            Playbook sugerido: <code>{playbook}</code>
          </p>
        )}
        {hints.length > 0 && (
          <ul className="zionxdr-incident-hints">
            {hints.map((h) => (
              <li key={h}>{h}</li>
            ))}
          </ul>
        )}
        {fingerprint && playbook && (
          <button type="button" className="sa-btn sa-btn-primary sa-btn-sm" disabled={busy} onClick={() => void onHitl()}>
            Pedir aprovação HITL
          </button>
        )}
        {msg && <p className="zionxdr-policy-msg">{msg}</p>}
      </div>
    </ZionXDRCorpSurface>
  );
}

import { useEffect, useRef, useState } from "react";

const LAYERS = [
  { id: "01", title: "Prevenção NGAV", text: "Reputação, hash e políticas na execução." },
  { id: "02", title: "IA + threat intel", text: "Score de risco e IOCs além de assinaturas." },
  { id: "03", title: "Comportamento", text: "LOLBins, ransom e living-off-the-land." },
  { id: "04", title: "Memória", text: "Injeção, hollow e artefatos fileless." },
  { id: "05", title: "Mitigação exploits", text: "Endurecimento e corte de filhos anómalos." },
];

export default function ZionXDRLayers() {
  const rootRef = useRef<HTMLElement>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) {
          setVisible(true);
          io.disconnect();
        }
      },
      { threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <section className="sa-corp-card zionxdr-layers-section" ref={rootRef} aria-labelledby="zionxdr-layers-title">
      <span className="sa-corp-card-fx" aria-hidden>
        <span className="sa-corp-card-fx-grid" />
      </span>
      <div className="zionxdr-layers-head">
        <h3 id="zionxdr-layers-title">Cinco camadas de defesa</h3>
      </div>
      <ul className={`zionxdr-layers-grid zionxdr-layers-corp${visible ? " is-visible" : ""}`}>
        {LAYERS.map((layer, i) => (
          <li
            key={layer.id}
            className="sa-corp-card zionxdr-layer-card"
            style={{ animationDelay: visible ? `${i * 75}ms` : undefined }}
          >
            <span className="zionxdr-layer-id">{layer.id}</span>
            <h4>{layer.title}</h4>
            <p>{layer.text}</p>
          </li>
        ))}
      </ul>
    </section>
  );
}

import { useCallback, useEffect, useState } from "react";
import { MapPin, Link2 } from "lucide-react";
import {
  fetchZionxdrNmsContext,
  linkZionxdrDevice,
  type ZionxdrNmsContext,
} from "../../api/client";
import { useAuth } from "../../context/AuthContext";
import ZionXDRCorpSurface from "./ZionXDRCorpSurface";

type Props = {
  endpointId: number | null;
  isLocal?: boolean;
  onLinked?: () => void;
};

export default function ZionXDRNmsCard({ endpointId, isLocal, onLinked }: Props) {
  const { user } = useAuth();
  const isAdmin = user?.role === "admin";
  const [ctx, setCtx] = useState<ZionxdrNmsContext | null>(null);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (endpointId == null || isLocal) {
      setCtx(null);
      return;
    }
    try {
      setCtx(await fetchZionxdrNmsContext(endpointId));
    } catch {
      setCtx(null);
    }
  }, [endpointId, isLocal]);

  useEffect(() => {
    void load();
  }, [load]);

  if (endpointId == null) return null;

  if (isLocal) {
    return (
      <ZionXDRCorpSurface className="zionxdr-nms-card" aria-label="Contexto NMS">
        <div className="zionxdr-nms-inner">
          <h3 className="zionxdr-nms-title">
            <MapPin size={15} aria-hidden /> Contexto NMS
          </h3>
          <p className="zionxdr-nms-muted">
            O endpoint local (Control Plane) não usa vínculo ao mapa. Cadastre um host Windows remoto para associar a
            um dispositivo NMS e abrir deep link no mapa.
          </p>
        </div>
      </ZionXDRCorpSurface>
    );
  }

  const dept = ctx?.department_path?.length ? ctx.department_path.map((d) => d.name).join(" › ") : null;

  const onLink = async (deviceId: number) => {
    setBusy(true);
    setMsg(null);
    try {
      await linkZionxdrDevice(endpointId, deviceId);
      setMsg("Dispositivo vinculado");
      onLinked?.();
      await load();
    } catch (err) {
      setMsg(err instanceof Error ? err.message : "Falha ao vincular");
    } finally {
      setBusy(false);
    }
  };

  return (
    <ZionXDRCorpSurface className="zionxdr-nms-card" aria-label="Contexto NMS">
      <div className="zionxdr-nms-inner">
        <h3 className="zionxdr-nms-title">
          <MapPin size={15} aria-hidden /> Contexto NMS
        </h3>
        {ctx?.device ? (
          <p className="zionxdr-nms-line">
            <strong>{ctx.device.hostname || ctx.device.ip_address}</strong>
            {dept && <span className="zionxdr-nms-dept">{dept}</span>}
          </p>
        ) : (
          <p className="zionxdr-nms-muted">Sem dispositivo NMS vinculado.</p>
        )}
        {ctx?.topology_deep_link && (
          <a className="zionxdr-nms-link" href={ctx.topology_deep_link}>
            Ver no mapa
          </a>
        )}
        {isAdmin && ctx?.suggested_devices?.length ? (
          <ul className="zionxdr-nms-suggest">
            {ctx.suggested_devices.map((d) => (
              <li key={d.device_id}>
                <button type="button" className="zionxdr-nms-link-btn" disabled={busy} onClick={() => void onLink(d.device_id)}>
                  <Link2 size={12} aria-hidden />
                  Vincular {d.hostname || d.ip_address}
                </button>
              </li>
            ))}
          </ul>
        ) : null}
        {msg && <p className="zionxdr-policy-msg">{msg}</p>}
      </div>
    </ZionXDRCorpSurface>
  );
}

import { useEffect, useId, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { FileCode2, X } from "lucide-react";

type Props = {
  open: boolean;
  busy?: boolean;
  onClose: () => void;
  onSubmit: (data: { name: string; slug: string; yaml_text: string }) => void;
};

export default function ZionXDRPolicyCreateDialog({ open, busy, onClose, onSubmit }: Props) {
  const titleId = useId();
  const nameRef = useRef<HTMLInputElement>(null);
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const [yaml, setYaml] = useState("rules: []\n");

  useEffect(() => {
    if (!open) return;
    setName("");
    setSlug("");
    setYaml("rules: []\n");
    const t = window.setTimeout(() => nameRef.current?.focus(), 80);
    return () => window.clearTimeout(t);
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !busy) onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = prev;
      window.removeEventListener("keydown", onKey);
    };
  }, [open, busy, onClose]);

  if (!open) return null;

  const canSubmit = name.trim().length >= 2 && slug.trim().length >= 2;

  const slugFromName = (raw: string) =>
    raw
      .trim()
      .toLowerCase()
      .replace(/\s+/g, "-")
      .replace(/[^a-z0-9-_]/g, "");

  return createPortal(
    <div
      className="zionxdr-corp-dialog-backdrop"
      role="presentation"
      onMouseDown={() => {
        if (!busy) onClose();
      }}
    >
      <div
        className="zionxdr-corp-dialog sa-corp-card zionxdr-corp-dialog--policy"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onMouseDown={(e) => e.stopPropagation()}
      >
        <span className="sa-corp-card-fx" aria-hidden>
          <span className="sa-corp-card-fx-grid" />
          <span className="sa-corp-card-fx-scan" />
        </span>
        <span className="sa-corp-card-rail" aria-hidden />

        <div className="zionxdr-corp-dialog-inner">
          <header className="zionxdr-corp-dialog-head">
            <span className="sa-icon-badge" aria-hidden>
              <FileCode2 size={18} strokeWidth={1.75} />
            </span>
            <div className="zionxdr-corp-dialog-titles">
              <h2 id={titleId} className="zionxdr-corp-dialog-title">
                Nova política Eagle
              </h2>
            </div>
            <button
              type="button"
              className="zionxdr-corp-dialog-close sa-btn sa-btn-ghost sa-btn-sm"
              disabled={busy}
              aria-label="Fechar"
              onClick={onClose}
            >
              <X size={16} />
            </button>
          </header>

          <form
            className="zionxdr-corp-dialog-form zionxdr-policy-create-form"
            onSubmit={(e) => {
              e.preventDefault();
              if (!canSubmit || busy) return;
              onSubmit({
                name: name.trim(),
                slug: slug.trim(),
                yaml_text: yaml,
              });
            }}
          >
            <div className="zionxdr-policy-create-grid">
              <label className="zionxdr-corp-field">
                <span>Nome</span>
                <input
                  ref={nameRef}
                  className="zionxdr-corp-input sa-input"
                  placeholder="SOC baseline"
                  value={name}
                  disabled={busy}
                  autoComplete="off"
                  onChange={(e) => {
                    const v = e.target.value;
                    setName(v);
                    setSlug((s) => (s === "" || s === slugFromName(name) ? slugFromName(v) : s));
                  }}
                />
              </label>
              <label className="zionxdr-corp-field">
                <span>Slug</span>
                <input
                  className="zionxdr-corp-input sa-input zionxdr-corp-input-mono"
                  placeholder="soc-baseline"
                  value={slug}
                  disabled={busy}
                  autoComplete="off"
                  onChange={(e) => setSlug(e.target.value)}
                />
              </label>
            </div>
            <label className="zionxdr-corp-field zionxdr-corp-field-yaml">
              <span>Regras (YAML)</span>
              <textarea
                className="zionxdr-policy-yaml zionxdr-corp-yaml"
                rows={8}
                spellCheck={false}
                value={yaml}
                disabled={busy}
                onChange={(e) => setYaml(e.target.value)}
              />
            </label>

            <div className="zionxdr-corp-dialog-actions">
              <button type="button" className="sa-btn sa-btn-secondary" disabled={busy} onClick={onClose}>
                Cancelar
              </button>
              <button type="submit" className="sa-btn sa-btn-primary zionxdr-corp-submit" disabled={busy || !canSubmit}>
                {busy ? "A criar…" : "Criar política"}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>,
    document.body,
  );
}

import { useCallback, useEffect, useState } from "react";
import { Shield } from "lucide-react";
import {
  assignZionxdrPolicy,
  createZionxdrPolicy,
  fetchZionxdrPolicies,
  patchZionxdrEndpoint,
  type ZionxdrEnforcementMode,
  type ZionxdrPolicy,
} from "../../api/client";
import ZionXDRCorpSurface from "./ZionXDRCorpSurface";
import ZionXDRCorpConfirmDialog from "./ZionXDRCorpConfirmDialog";
import ZionXDRPolicyCreateDialog from "./ZionXDRPolicyCreateDialog";

type Props = {
  endpointId: number | null;
  isLocal?: boolean;
  enforcementMode?: ZionxdrEnforcementMode;
  policyId?: number | null;
  appliedVersion?: number | null;
  onUpdated?: () => void;
};

const MODES: { id: ZionxdrEnforcementMode; label: string; hint: string }[] = [
  { id: "monitor", label: "Monitor", hint: "Só alertas — sem resposta automática" },
  { id: "detect", label: "Detect", hint: "Telemetria reforçada (resposta igual monitor)" },
  { id: "enforce", label: "Enforce", hint: "Aplica kill/quarantine conforme regra" },
];

export default function ZionXDRPolicyPanel({
  endpointId,
  isLocal: _isLocal,
  enforcementMode = "monitor",
  policyId,
  appliedVersion,
  onUpdated,
}: Props) {
  const [policies, setPolicies] = useState<ZionxdrPolicy[]>([]);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [pickPolicy, setPickPolicy] = useState<number | "">(policyId ?? "");
  const [createOpen, setCreateOpen] = useState(false);
  const [enforceConfirmOpen, setEnforceConfirmOpen] = useState(false);

  const load = useCallback(async () => {
    try {
      setPolicies(await fetchZionxdrPolicies());
    } catch {
      /* ignore */
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    setPickPolicy(policyId ?? "");
  }, [policyId]);

  if (endpointId == null) return null;

  const applyMode = async (mode: ZionxdrEnforcementMode) => {
    setBusy(true);
    setMsg(null);
    try {
      await patchZionxdrEndpoint(endpointId, { enforcement_mode: mode });
      setMsg(`Modo ${mode} aplicado`);
      onUpdated?.();
    } catch (err) {
      setMsg(err instanceof Error ? err.message : "Falha ao alterar modo");
    } finally {
      setBusy(false);
    }
  };

  const onMode = (mode: ZionxdrEnforcementMode) => {
    if (mode === "enforce" && enforcementMode !== "enforce") {
      setEnforceConfirmOpen(true);
      return;
    }
    void applyMode(mode);
  };

  const onCreatePolicy = async (data: { name: string; slug: string; yaml_text: string }) => {
    setBusy(true);
    setMsg(null);
    try {
      const row = await createZionxdrPolicy(data);
      await load();
      setPickPolicy(row.id);
      setCreateOpen(false);
      setMsg(`Política ${row.slug} v${row.version} criada`);
    } catch (err) {
      setMsg(err instanceof Error ? err.message : "Falha ao criar política");
    } finally {
      setBusy(false);
    }
  };

  const onApplyPolicy = async () => {
    if (pickPolicy === "") return;
    setBusy(true);
    setMsg(null);
    try {
      const res = await assignZionxdrPolicy(endpointId, Number(pickPolicy));
      setMsg(res.queued ? "Política enfileirada para o agent" : "Política aplicada no host local");
      onUpdated?.();
    } catch (err) {
      setMsg(err instanceof Error ? err.message : "Falha ao aplicar política");
    } finally {
      setBusy(false);
    }
  };

  return (
    <ZionXDRCorpSurface className="zionxdr-policy-panel" aria-label="Política e modo Eagle">
      <div className="zionxdr-policy-inner">
        <header className="zionxdr-policy-head">
          <h3 className="zionxdr-policy-title">
            <Shield size={15} aria-hidden /> Política &amp; MITRE
          </h3>
          {appliedVersion != null && (
            <span className="zionxdr-policy-ver">v{appliedVersion}</span>
          )}
        </header>

        <div className="zionxdr-policy-modes" role="group" aria-label="Modo de enforcement">
          {MODES.map((m) => (
            <button
              key={m.id}
              type="button"
              className={`zionxdr-mode-btn${enforcementMode === m.id ? " is-active" : ""}`}
              title={m.hint}
              disabled={busy}
              onClick={() => void onMode(m.id)}
            >
              {m.label}
            </button>
          ))}
        </div>

        <div className="zionxdr-policy-row">
          <select
            className="zionxdr-policy-select zionxdr-corp-select"
            value={pickPolicy}
            disabled={busy}
            onChange={(e) => setPickPolicy(e.target.value === "" ? "" : Number(e.target.value))}
          >
            <option value="">Política…</option>
            {policies.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name} ({p.slug} v{p.version})
              </option>
            ))}
          </select>
          <button type="button" className="sa-btn sa-btn-primary sa-btn-sm" disabled={busy || pickPolicy === ""} onClick={() => void onApplyPolicy()}>
            Aplicar
          </button>
          <button type="button" className="sa-btn sa-btn-secondary sa-btn-sm" disabled={busy} onClick={() => setCreateOpen(true)}>
            Nova
          </button>
        </div>

        {msg && <p className="zionxdr-policy-msg">{msg}</p>}
      </div>

      <ZionXDRPolicyCreateDialog
        open={createOpen}
        busy={busy}
        onClose={() => {
          if (!busy) setCreateOpen(false);
        }}
        onSubmit={(data) => void onCreatePolicy(data)}
      />

      <ZionXDRCorpConfirmDialog
        open={enforceConfirmOpen}
        busy={busy}
        variant="warning"
        title="Ativar modo Enforce"
        message="Em ambiente lab, o Enforce pode terminar processos ou isolar ficheiros conforme as regras. Confirma que pretende aplicar este modo neste endpoint?"
        confirmLabel="Ativar Enforce"
        onClose={() => {
          if (!busy) setEnforceConfirmOpen(false);
        }}
        onConfirm={() => {
          setEnforceConfirmOpen(false);
          void applyMode("enforce");
        }}
      />
    </ZionXDRCorpSurface>
  );
}

import { useCallback, useEffect, useState } from "react";
import { Activity, Cpu, MemoryStick } from "lucide-react";
import { fetchZionxdrTelemetry, runZionxdrTelemetryJob } from "../../api/client";
import ZionXDRCorpSurface from "./ZionXDRCorpSurface";

type Props = {
  endpointId: number | null;
};

export default function ZionXDRTelemetryCard({ endpointId }: Props) {
  const [telemetry, setTelemetry] = useState<Record<string, unknown> | null>(null);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (endpointId == null) return;
    try {
      setTelemetry(await fetchZionxdrTelemetry(endpointId));
    } catch {
      setTelemetry(null);
    }
  }, [endpointId]);

  useEffect(() => {
    void load();
    const id = setInterval(() => void load(), 8000);
    return () => clearInterval(id);
  }, [load]);

  const run = async (action: string) => {
    if (endpointId == null) return;
    setBusy(true);
    setMsg(null);
    try {
      const res = await runZionxdrTelemetryJob(endpointId, action);
      setMsg(res.queued ? `Job ${res.job_id} enfileirado` : "Concluído no host");
      await load();
    } catch (err) {
      setMsg(err instanceof Error ? err.message : "Falha");
    } finally {
      setBusy(false);
    }
  };

  if (endpointId == null) return null;

  const etw = (telemetry?.etw as Record<string, unknown>) || {};
  const memAt = telemetry?.last_memory_scan_at as string | undefined;
  const memFind = telemetry?.last_memory_findings as number | undefined;

  const etwActive = Boolean(etw.running);

  return (
