/** Texto legível sobre o fundo sólido da cor do tipo (mesma cor do ícone da biblioteca). */
export function getDeviceTypeTextColor(typeColor: string): string {
  const hex = typeColor.replace("#", "");
  if (hex.length !== 6) return "#ffffff";
  const r = parseInt(hex.slice(0, 2), 16);
  const g = parseInt(hex.slice(2, 4), 16);
  const b = parseInt(hex.slice(4, 6), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > 0.55 ? "#1e293b" : "#ffffff";
}

export function deviceTypesByCategory(category: DeviceCategory): DeviceTypeDef[] {
  return DEVICE_TYPES.filter((d) => d.category === category);
}

