type Theme = "light" | "dark";

interface ThemeContextValue {
  theme: Theme;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>(() => {
    const saved = localStorage.getItem("sentinelai-theme") as Theme | null;
    if (saved) return saved;
    return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  });

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
    localStorage.setItem("sentinelai-theme", theme);
  }, [theme]);

  function toggleTheme() {
    setTheme((t) => (t === "light" ? "dark" : "light"));
  }

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const ctx = useContext(ThemeContext);
  if (!ctx) throw new Error("useTheme must be used within ThemeProvider");
  return ctx;
}

import { useEffect, useLayoutEffect, useRef } from "react";

/**
 * Mantém o histórico colado ao topo ao abrir; só desce ao enviar novas mensagens.
 * Evita scrollIntoView no documento (escondia o início do chat).
 */
export function useChatMessageScroll(messagesLength: number, loading: boolean, resetWhen?: boolean) {
  const scrollRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    if (resetWhen === false) return;
    const root = document.documentElement;
    const prev = root.style.scrollBehavior;
    root.style.scrollBehavior = "auto";
    window.scrollTo(0, 0);
    scrollRef.current?.scrollTo(0, 0);
    root.style.scrollBehavior = prev;
  }, [resetWhen]);

  useEffect(() => {
    const box = scrollRef.current;
    if (!box) return;
    const followTail = messagesLength > 1 || loading;
    if (!followTail) {
      box.scrollTop = 0;
      return;
    }
    box.scrollTo({ top: box.scrollHeight, behavior: loading ? "auto" : "smooth" });
  }, [messagesLength, loading]);

  return scrollRef;
}

import { useCallback, useEffect, useRef, useState } from "react";
import {
  applyDashboardTemplate,
  fetchDashboardLayout,
  fetchDashboardTemplates,
  saveDashboardLayout,
  type DashboardTemplateInfo,
} from "../api/client";

export type DashboardWidgetId =
  | "stats"
  | "status_chart"
  | "type_breakdown"
  | "fleet_metrics"
  | "deep_coverage"
  | "discovery"
  | "devices"
  | "events";

export interface DashboardLayout {
  widgets: DashboardWidgetId[];
  hidden: DashboardWidgetId[];
}

const STORAGE_KEY = "sentinelai_dashboard_layout";

const DEFAULT_LAYOUT: DashboardLayout = {
  widgets: [
    "stats",
    "status_chart",
    "type_breakdown",
    "fleet_metrics",
    "deep_coverage",
    "discovery",
    "devices",
    "events",
  ],
  hidden: ["fleet_metrics", "deep_coverage"],
};

const ALL_WIDGETS: DashboardWidgetId[] = DEFAULT_LAYOUT.widgets;

function normalizeLayout(
  raw: Partial<DashboardLayout> | { widgets?: string[]; hidden?: string[] } | null | undefined,
): DashboardLayout {
  const seen = new Set<DashboardWidgetId>();
  const widgets: DashboardWidgetId[] = [];
  for (const id of raw?.widgets || []) {
    if ((ALL_WIDGETS as string[]).includes(id) && !seen.has(id as DashboardWidgetId)) {
      widgets.push(id as DashboardWidgetId);
      seen.add(id as DashboardWidgetId);
    }
  }
  for (const id of ALL_WIDGETS) {
    if (!seen.has(id)) widgets.push(id);
  }
  const hidden = (raw?.hidden || []).filter((id): id is DashboardWidgetId =>
    (ALL_WIDGETS as string[]).includes(id),
  );
  return { widgets, hidden };
}

function readLocal(): DashboardLayout {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) return normalizeLayout(JSON.parse(raw) as DashboardLayout);
  } catch {
    /* ignore */
  }
  return DEFAULT_LAYOUT;
}

export function useDashboardLayout() {
  const [layout, setLayout] = useState<DashboardLayout>(() => readLocal());
  const [templates, setTemplates] = useState<DashboardTemplateInfo[]>([]);
  const [synced, setSynced] = useState(false);
  const skipNextSave = useRef(true);
  const saveTimer = useRef<number | null>(null);

  useEffect(() => {
    let cancelled = false;
    Promise.all([fetchDashboardLayout(), fetchDashboardTemplates().catch(() => [] as DashboardTemplateInfo[])])
      .then(([remote, tmpls]) => {
        if (cancelled) return;
        const hasRemote = (remote.widgets?.length || 0) > 0 || (remote.hidden?.length || 0) > 0;
        if (hasRemote) {
          skipNextSave.current = true;
          setLayout(normalizeLayout(remote));
        }
        setTemplates(tmpls);
        setSynced(true);
      })
      .catch(() => {
        if (!cancelled) setSynced(true);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(layout));
    if (!synced) return;
    if (skipNextSave.current) {
      skipNextSave.current = false;
      return;
    }
    if (saveTimer.current) window.clearTimeout(saveTimer.current);
    saveTimer.current = window.setTimeout(() => {
      saveDashboardLayout(layout).catch(() => undefined);
    }, 600);
    return () => {
      if (saveTimer.current) window.clearTimeout(saveTimer.current);
    };
  }, [layout, synced]);

  const toggleWidget = useCallback((id: DashboardWidgetId) => {
    setLayout((prev) => {
      const hidden = new Set(prev.hidden);
      if (hidden.has(id)) hidden.delete(id);
      else hidden.add(id);
      return { ...prev, hidden: [...hidden] };
    });
  }, []);

  const moveWidget = useCallback((id: DashboardWidgetId, direction: "up" | "down") => {
    setLayout((prev) => {
      const widgets = [...prev.widgets];
      const index = widgets.indexOf(id);
      if (index < 0) return prev;
      const swap = direction === "up" ? index - 1 : index + 1;
      if (swap < 0 || swap >= widgets.length) return prev;
      [widgets[index], widgets[swap]] = [widgets[swap], widgets[index]];
      return { ...prev, widgets };
    });
  }, []);

  const reorderWidget = useCallback((fromId: DashboardWidgetId, toId: DashboardWidgetId) => {
    if (fromId === toId) return;
    setLayout((prev) => {
      const widgets = [...prev.widgets];
      const from = widgets.indexOf(fromId);
      const to = widgets.indexOf(toId);
      if (from < 0 || to < 0) return prev;
      widgets.splice(from, 1);
      widgets.splice(to, 0, fromId);
      return { ...prev, widgets };
    });
  }, []);

  const resetLayout = useCallback(() => {
    skipNextSave.current = true;
    setLayout(DEFAULT_LAYOUT);
    applyDashboardTemplate("default")
      .then((remote) => {
        skipNextSave.current = true;
        setLayout(normalizeLayout(remote));
      })
      .catch(() => undefined);
  }, []);

  const applyTemplate = useCallback(async (templateId: string) => {
    const remote = await applyDashboardTemplate(templateId);
    skipNextSave.current = true;
    setLayout(normalizeLayout(remote));
  }, []);

  const isVisible = useCallback((id: DashboardWidgetId) => !layout.hidden.includes(id), [layout.hidden]);

  return {
    layout,
    templates,
    toggleWidget,
    moveWidget,
    reorderWidget,
    resetLayout,
    applyTemplate,
    isVisible,
    synced,
  };
}

