import { FormEvent, useEffect, useState } from "react";
import { AlertCircle, KeyRound, Shield } from "lucide-react";
import { fetchOidcStatus, login, verifyMfa, type OidcStatus } from "../api/client";

export default function LoginPage({
  onLogin,
  initialMfaToken = null,
  initialError = null,
}: {
  onLogin: (opts?: { must_change_password?: boolean }) => void;
  initialMfaToken?: string | null;
  initialError?: string | null;
}) {
  const [username, setUsername] = useState("admin");
  const [password, setPassword] = useState("admin123");
  const [mfaToken, setMfaToken] = useState<string | null>(initialMfaToken);
  const [mfaCode, setMfaCode] = useState("");
  const [error, setError] = useState(initialError || "");
  const [loading, setLoading] = useState(false);
  const [oidc, setOidc] = useState<OidcStatus | null>(null);

  useEffect(() => {
    if (initialMfaToken) setMfaToken(initialMfaToken);
  }, [initialMfaToken]);

  useEffect(() => {
    if (initialError) setError(initialError);
  }, [initialError]);

  useEffect(() => {
    fetchOidcStatus()
      .then(setOidc)
      .catch(() => setOidc(null));
  }, []);

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    setLoading(true);
    setError("");
    try {
      if (mfaToken) {
        const result = await verifyMfa(mfaToken, mfaCode);
        onLogin({ must_change_password: result.must_change_password });
        return;
      }
      const result = await login(username, password);
      if (result.mfa_required && result.mfa_token) {
        setMfaToken(result.mfa_token);
        setMfaCode("");
        return;
      }
      onLogin({ must_change_password: result.must_change_password });
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Usuário ou senha inválidos");
    } finally {
      setLoading(false);
    }
  }

  function startSso() {
    window.location.assign("/api/auth/oidc/login");
  }

  return (
    <div className="sa-login-page">
      <div className="sa-login-card">
        <div className="sa-login-brand">
          <div className="sa-login-brand-icon">
            <Shield size={28} />
          </div>
          <h1>SentinelAI</h1>
          <p>
            {mfaToken
              ? "Segundo fator · código do autenticador"
              : "Plataforma de monitoramento e inventário de rede"}
          </p>
        </div>

        <form className="sa-login-form" onSubmit={handleSubmit}>
          {!mfaToken ? (
            <>
              <label className="sa-label">
                Usuário
                <input
                  className="sa-input"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  autoComplete="username"
                  autoFocus
                />
              </label>
              <label className="sa-label">
                Senha
                <input
                  className="sa-input"
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  autoComplete="current-password"
                />
              </label>
            </>
          ) : (
            <label className="sa-label">
              Código MFA (6 dígitos)
              <input
                className="sa-input"
                inputMode="numeric"
                autoComplete="one-time-code"
                placeholder="123456"
                value={mfaCode}
                onChange={(e) => setMfaCode(e.target.value.replace(/\D/g, "").slice(0, 8))}
                autoFocus
              />
            </label>
          )}

          {error && (
            <div className="sa-alert sa-alert-error" role="alert">
              <AlertCircle size={16} />
              {error}
            </div>
          )}

          <button type="submit" className="sa-btn sa-btn-primary sa-btn-block" disabled={loading}>
            {loading ? (
              <>
                <span className="sa-spinner" /> {mfaToken ? "Verificando..." : "Entrando..."}
              </>
            ) : mfaToken ? (
              "Verificar MFA"
            ) : (
              "Entrar"
            )}
          </button>

          {!mfaToken && oidc?.enabled && (
            <>
              <div className="sa-login-divider" aria-hidden>
                <span>ou</span>
              </div>
              <button
                type="button"
                className="sa-btn sa-btn-secondary sa-login-sso sa-btn-block"
                onClick={startSso}
              >
                <KeyRound size={16} /> Entrar com SSO
              </button>
              {oidc.issuer ? (
                <p className="sa-text-muted sa-login-meta">
                  IdP: {oidc.issuer}
                </p>
              ) : null}
            </>
          )}

          {mfaToken && (
            <button
              type="button"
              className="sa-btn sa-btn-ghost sa-btn-block"
              onClick={() => {
                setMfaToken(null);
                setMfaCode("");
                setError("");
              }}
            >
              Voltar
            </button>
          )}
        </form>
      </div>
    </div>
  );
}

