type Props = {
  label?: string;
  dashboard: ZionvmDashboard | null;
  loading?: boolean;
  busy?: boolean;
  showCreate: boolean;
  onToggleCreate: () => void;
  createForm: ZionvmCreateVmForm;
  onCreateFormChange: (patch: Partial<ZionvmCreateVmForm>) => void;
  onSimulateTask: () => void;
  onSubmitCreate: () => void;
  onRefresh: () => void;
  error?: string | null;
  provision?: {
    storages?: ZvmProvisionStorage[];
    bridges?: string[];
    isos?: ZvmProvisionIso[];
    onUploadIso?: (
      storageId: number,
      file: File,
      onProgress?: (pct: number) => void,
    ) => Promise<string | void>;
  };
};

function taskTone(status: string): "ok" | "bad" | "run" | "muted" {
  const s = status.toLowerCase();
  if (s === "success" || s === "completed") return "ok";
  if (s === "failed" || s === "error") return "bad";
  if (s === "running" || s === "pending" || s === "queued") return "run";
  return "muted";
}

function KpiTile({
  icon: Icon,
  label,
  value,
  hint,
  accent,
}: {
  icon: LucideIcon;
  label: string;
  value: string | number;
  hint?: string;
  accent?: "primary" | "ok" | "info";
}) {
