}

export default function ZionvmDashboardView({
  label,
  dashboard,
  loading,
  busy,
  showCreate,
  onToggleCreate,
  createForm,
  onCreateFormChange,
  onSimulateTask,
  onSubmitCreate,
  onRefresh,
  error,
  provision,
}: Props) {
  const healthPct = useMemo(() => {
    if (!dashboard) return null;
    const nodes = dashboard.nodes || 0;
    if (nodes <= 0) return dashboard.vms_running > 0 ? 72 : 48;
    const online = dashboard.nodes_online / nodes;
    const vmRun = dashboard.vms > 0 ? dashboard.vms_running / dashboard.vms : 1;
    return Math.round((online * 0.55 + vmRun * 0.45) * 100);
  }, [dashboard]);

  const toolbar = (
    <>
      <ZvmActionButton variant="primary" disabled={busy} onClick={onSimulateTask} icon={Sparkles}>
        Simular task
      </ZvmActionButton>
      <ZvmActionButton variant={showCreate ? "accent" : "default"} disabled={busy} onClick={onToggleCreate} icon={Plus}>
        {showCreate ? "Fechar wizard" : "Criar VM"}
      </ZvmActionButton>
    </>
  );

  return (
    <ZvmViewShell
      title={label || "Dashboard"}
      icon={Activity}
      busy={busy || loading}
      onRefresh={onRefresh}
      error={error}
      toolbar={toolbar}
    >
      <div className="zvm-ds-kpi-grid">
        <KpiTile icon={Building2} label="Datacenters" value={dashboard?.datacenters ?? "—"} />
        <KpiTile icon={Layers} label="Clusters" value={dashboard?.clusters ?? "—"} accent="info" />
        <KpiTile
          icon={Server}
          label="Nodes online"
          value={
            dashboard != null ? `${dashboard.nodes_online}/${dashboard.nodes || dashboard.nodes_online || 0}` : "—"
          }
          hint={healthPct != null ? `Saúde estimada ${healthPct}%` : undefined}
          accent="ok"
        />
        <KpiTile icon={Server} label="VMs" value={dashboard?.vms ?? "—"} />
        <KpiTile icon={Play} label="VMs em execução" value={dashboard?.vms_running ?? "—"} accent="ok" />
        <KpiTile
          icon={ListTodo}
          label="Tasks ativas"
          value={dashboard?.tasks_running ?? "—"}
          hint="Engine Celery · fila zionvm"
          accent="info"
        />
      </div>

      {showCreate ? (
        <ZvmCreateVmCard
          createForm={createForm}
          onCreateFormChange={onCreateFormChange}
          onSubmitCreate={onSubmitCreate}
          busy={busy}
          storages={provision?.storages}
          bridges={provision?.bridges}
          isos={provision?.isos}
          onUploadIso={provision?.onUploadIso}
        />
      ) : null}

      <ZvmCard title="Tasks recentes">
        <div className="zvm-ds-table-wrap">
          <table className="zvm-table zvm-ds-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Tipo</th>
                <th>Status</th>
                <th>Progresso</th>
              </tr>
            </thead>
            <tbody>
              {(dashboard?.recent_tasks || []).length === 0 ? (
                <tr>
                  <td colSpan={4} className="zvm-empty">
                    Nenhuma task registada ainda.
                  </td>
                </tr>
              ) : (
                (dashboard?.recent_tasks || []).map((t) => (
                  <tr key={t.id}>
                    <td className="zvm-mono">{t.id}</td>
                    <td>{t.task_type}</td>
                    <td>
                      <ZvmStatusPill tone={taskTone(t.status)}>{t.status}</ZvmStatusPill>
                    </td>
                    <td>
                      <span className="zvm-ds-progress">
                        <span className="zvm-ds-progress-bar" style={{ width: `${Math.min(100, t.progress_pct)}%` }} />
                        <span className="zvm-ds-progress-label">{t.progress_pct}%</span>
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </ZvmCard>
    </ZvmViewShell>
  );
}

