function ctStatusTone(status: string): "ok" | "bad" | "run" | "muted" {
  const s = status.toLowerCase();
  if (s === "running") return "ok";
  if (s === "stopped") return "muted";
  if (s === "failed" || s === "error") return "bad";
  return "run";
}

function ctStatusLive(status: string): boolean | "danger" | undefined {
  const s = status.toLowerCase();
  if (s === "running") return true;
  if (s === "stopped") return "danger";
  return undefined;
}

