function HealthGauge({ score }: { score: number | null | undefined }) {
  const v = typeof score === "number" && Number.isFinite(score) ? Math.max(0, Math.min(100, score)) : null;
  const tone = v == null ? "muted" : v >= 80 ? "ok" : v >= 50 ? "warn" : "bad";
  const dash = v != null ? (v / 100) * 264 : 0;

  return (
    <div className={`zvm-ds-manager-health zvm-ds-manager-health-${tone}`} aria-hidden>
      <svg viewBox="0 0 96 96" className="zvm-ds-manager-health-svg">
        <circle className="zvm-ds-manager-health-track" cx="48" cy="48" r="42" />
        <circle
          className="zvm-ds-manager-health-fill"
          cx="48"
          cy="48"
          r="42"
          strokeDasharray={`${dash} 264`}
          strokeDashoffset={0}
        />
      </svg>
      <span className="zvm-ds-manager-health-glow" />
    </div>
  );
}

