  return `zvm-tree-status-${s}`;
}

function TreeRows({
  nodes,
  depth,
  expanded,
  selectedId,
  onToggle,
  onSelect,
  filter,
}: {
  nodes: ZionvmTreeNode[];
  depth: number;
  expanded: Set<string>;
  selectedId: string | null;
  onToggle: (id: string) => void;
  onSelect: (node: ZionvmTreeNode) => void;
  filter: string;
}) {
  const q = filter.trim().toLowerCase();
  return (
    <ul className="zvm-tree">
      {nodes.map((node) => {
        const kids = node.children || [];
        const matchSelf = !q || node.label.toLowerCase().includes(q);
        const matchChild = q && kids.length > 0 && JSON.stringify(kids).toLowerCase().includes(q);
        if (q && !matchSelf && !matchChild) return null;
        const open = expanded.has(node.id) || Boolean(q && matchChild);
        const hasKids = kids.length > 0;
        const Icon = zvmTreeIcon(node.type);
        return (
          <li key={node.id}>
            <button
              type="button"
              className={`zvm-tree-row${selectedId === node.id ? " zvm-tree-row-active" : ""}`}
              onClick={() => onSelect(node)}
            >
              <span
                className="zvm-tree-toggle"
                onClick={(e) => {
                  if (!hasKids) return;
                  e.stopPropagation();
                  onToggle(node.id);
                }}
              >
                {hasKids ? open ? <ChevronDown size={12} /> : <ChevronRight size={12} /> : null}
              </span>
              {Icon ? (
                <span className="zvm-ds-tree-icon" aria-hidden>
                  <Icon size={13} strokeWidth={2.2} />
                </span>
              ) : null}
              <span className="zvm-tree-label">{node.label}</span>
              {node.status ? (
                <span
                  className={`zvm-tree-status ${statusClass(node.status)}${
                    ["online", "running", "success"].includes(String(node.status).toLowerCase())
                      ? " zvm-tree-status-live"
                      : ""
                  }`}
                  title={node.status}
                />
              ) : null}
            </button>
            {hasKids && open ? (
              <TreeRows
                nodes={kids}
                depth={depth + 1}
                expanded={expanded}
                selectedId={selectedId}
                onToggle={onToggle}
                onSelect={onSelect}
                filter={filter}
              />
            ) : null}
          </li>
        );
      })}
    </ul>
  );
}

function collectExpandableIds(nodes: ZionvmTreeNode[], into: string[] = []): string[] {
  for (const n of nodes) {
    if (n.children?.length) {
      into.push(n.id);
      collectExpandableIds(n.children, into);
    }
  }
  return into;
}

