import { useCallback, useEffect, useState } from "react";
import { fetchZionxdrEndpoints, type ZionxdrEagleStats, type ZionxdrEndpoint } from "../api/client";
import ZionXDRConsole from "../components/zionxdr/ZionXDRConsole";
import ZionXDREndpointBar from "../components/zionxdr/ZionXDREndpointBar";
import ZionXDRFlow from "../components/zionxdr/ZionXDRFlow";
import ZionXDRHero from "../components/zionxdr/ZionXDRHero";
import ZionXDRLayers from "../components/zionxdr/ZionXDRLayers";
import ZionXDRIncidentPanel from "../components/zionxdr/ZionXDRIncidentPanel";
import ZionXDRNmsCard from "../components/zionxdr/ZionXDRNmsCard";
import ZionXDRPolicyPanel from "../components/zionxdr/ZionXDRPolicyPanel";
import ZionXDRTelemetryCard from "../components/zionxdr/ZionXDRTelemetryCard";
import ZionXDREndpointPlaceholder from "../components/zionxdr/ZionXDREndpointPlaceholder";
import { useZionxdrScrollChrome } from "../components/zionxdr/useZionxdrScrollChrome";

type WorkspaceId = "console" | "governance" | "telemetry" | "product";

const WORKSPACE_TABS: { id: WorkspaceId; label: string; hint: string }[] = [
  { id: "console", label: "Consola Eagle", hint: "Alertas · Monitoramento · SIEM · Regras · Quarentena" },
  { id: "governance", label: "Política & NMS", hint: "MITRE, modos, vínculo mapa" },
  { id: "telemetry", label: "Telemetria & HITL", hint: "Memória, ETW, incidente" },
  { id: "product", label: "Visão produto", hint: "Camadas Eagle no ecossistema" },
];

export default function ZionXDRPage() {
  const [workspace, setWorkspace] = useState<WorkspaceId>("console");
  const [stats, setStats] = useState<ZionxdrEagleStats | null>(null);
  const [endpointId, setEndpointId] = useState<number | null>(null);
  const [endpointRow, setEndpointRow] = useState<ZionxdrEndpoint | null>(null);
  const [highlightFp, setHighlightFp] = useState<string | null>(null);
  const [metaTick, setMetaTick] = useState(0);
  const monitorOn = !!stats?.monitor_running;
  const { scrollRef, scrollClassName } = useZionxdrScrollChrome();

  useEffect(() => {
    const eid = sessionStorage.getItem("zionxdr:endpoint_id");
    const fp = sessionStorage.getItem("zionxdr:highlight_fp");
    const ws = sessionStorage.getItem("zionxdr:workspace") as WorkspaceId | null;
    if (eid || fp) setWorkspace("console");
    else if (ws && WORKSPACE_TABS.some((t) => t.id === ws)) setWorkspace(ws);
    if (eid) {
      setEndpointId(Number(eid));
      sessionStorage.removeItem("zionxdr:endpoint_id");
    }
    if (fp) {
      setHighlightFp(fp);
      sessionStorage.removeItem("zionxdr:highlight_fp");
    }
  }, []);

  const onWorkspace = (id: WorkspaceId) => {
    setWorkspace(id);
    sessionStorage.setItem("zionxdr:workspace", id);
  };

  const refreshEndpointMeta = useCallback(async () => {
    try {
      const rows = await fetchZionxdrEndpoints();
      const row = rows.find((r) => r.id === endpointId) ?? null;
      setEndpointRow(row);
    } catch {
      setEndpointRow(null);
    }
  }, [endpointId]);

  useEffect(() => {
    void refreshEndpointMeta();
  }, [refreshEndpointMeta, metaTick]);

  const onMetaUpdated = () => setMetaTick((t) => t + 1);

  return (
    <div ref={scrollRef} className={scrollClassName}>
      <div className="zionxdr-corp-shell zionxdr-corp-stage">
        <ZionXDREndpointBar endpointId={endpointId} onEndpointId={setEndpointId} />

        <nav className="zionxdr-workspace-tabs" aria-label="Áreas ZionXDR">
          {WORKSPACE_TABS.map((t) => (
            <button
              key={t.id}
              type="button"
              className={`zionxdr-workspace-tab${workspace === t.id ? " is-active" : ""}`}
              title={t.hint}
              onClick={() => onWorkspace(t.id)}
            >
              <span className="zionxdr-workspace-tab-label">{t.label}</span>
              <span className="zionxdr-workspace-tab-hint">{t.hint}</span>
            </button>
          ))}
        </nav>

        {workspace === "console" && (
          <ZionXDRConsole
            endpointId={endpointId}
            highlightFingerprint={highlightFp}
            onStatsChange={setStats}
          />
        )}

        {workspace === "governance" &&
          (endpointId == null ? (
            <ZionXDREndpointPlaceholder title="Política & NMS" />
          ) : (
            <div className="zionxdr-s2-row">
              <ZionXDRPolicyPanel
                endpointId={endpointId}
                isLocal={endpointRow?.is_local}
                enforcementMode={endpointRow?.enforcement_mode ?? "monitor"}
                policyId={endpointRow?.policy_id}
                appliedVersion={endpointRow?.applied_policy_version}
                onUpdated={onMetaUpdated}
              />
              <ZionXDRNmsCard endpointId={endpointId} isLocal={endpointRow?.is_local} onLinked={onMetaUpdated} />
            </div>
          ))}

        {workspace === "telemetry" &&
          (endpointId == null ? (
            <ZionXDREndpointPlaceholder title="Telemetria & HITL" />
          ) : (
            <div className="zionxdr-s2-row">
              <ZionXDRTelemetryCard endpointId={endpointId} />
              <ZionXDRIncidentPanel endpointId={endpointId} fingerprint={highlightFp} />
            </div>
          ))}

        {workspace === "product" && (
          <>
            <ZionXDRHero stats={stats} monitorOn={monitorOn} />
            <ZionXDRFlow />
            <ZionXDRLayers />
          </>
        )}
      </div>
    </div>
  );
}

