/**
 * ZionVM — efeitos corporativos (camada apresentação only).
 * Ambiente, transições, sidebar Plataforma, cards legados → DS.
 */

.zvm-shell {
  position: relative;
  isolation: isolate;
}

.zvm-shell::before {
  content: "";
  pointer-events: none;
  position: fixed;
  inset: 0;
  z-index: 0;
  opacity: 0.35;
  background:
    radial-gradient(ellipse 80% 50% at 10% -10%, color-mix(in srgb, var(--sa-primary) 14%, transparent), transparent 55%),
    radial-gradient(ellipse 60% 40% at 95% 100%, color-mix(in srgb, var(--sa-info) 10%, transparent), transparent 50%);
}

.zvm-shell > * {
  position: relative;
  z-index: 1;
}

.zvm-ds-content-stage {
  animation: zvm-ds-stage-in 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
  min-width: 0;
}

@keyframes zvm-ds-stage-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .zvm-ds-content-stage {
    animation: none;
  }
}

/* Hero — brilho ambiente */
.zvm-ds-hero::after {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    105deg,
    transparent 42%,
    color-mix(in srgb, var(--sa-primary) 12%, transparent) 50%,
    transparent 58%
  );
  background-size: 220% 100%;
  opacity: 0;
  animation: zvm-ds-hero-sweep 8s ease-in-out infinite;
}

@keyframes zvm-ds-hero-sweep {
  0%,
  72% {
    opacity: 0;
    background-position: 120% 0;
  }
  78% {
    opacity: 0.55;
  }
  100% {
    opacity: 0;
    background-position: -20% 0;
  }
}

