#>

param(
  [string]$InstallDir = (Join-Path $env:ProgramFiles "SentinelAI"),
  [switch]$SkipFirewall,
  [switch]$SkipStart
)

$ErrorActionPreference = "Stop"
$InstallerRoot = Split-Path $PSScriptRoot -Parent
$RepoRoot = Split-Path $InstallerRoot -Parent
