function Write-Log([string]$Message, [string]$Color = "White") {
  $line = "[{0:u}] {1}" -f (Get-Date), $Message
  Write-Host $Message -ForegroundColor $Color
  if (Test-Path $LogDir) { Add-Content -Path $LogFile -Value $line -ErrorAction SilentlyContinue }
}

function Assert-Admin {
  $id = [Security.Principal.WindowsIdentity]::GetCurrent()
  $p = New-Object Security.Principal.WindowsPrincipal($id)
  if (-not $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    throw "Execute este instalador como Administrador."
  }
}

function Test-Docker {
  try {
    docker version --format "{{.Server.Version}}" | Out-Null
    if ($LASTEXITCODE -ne 0) { return $false }
    docker compose version | Out-Null
    return ($LASTEXITCODE -eq 0)
  } catch {
    return $false
  }
}

function New-SecretHex([int]$Bytes = 32) {
  $buf = New-Object byte[] $Bytes
  [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($buf)
  return ($buf | ForEach-Object { $_.ToString("x2") }) -join ""
}

function New-StrongPassword {
  # Cumpre política production (não fraca)
  $a = New-SecretHex 9
  return "Sa!${a}Xx9"
}

function Copy-TreeFiltered([string]$Source, [string]$Dest) {
  if (-not (Test-Path $Source)) { throw "Origem em falta: $Source" }
  New-Item -ItemType Directory -Force -Path $Dest | Out-Null
  # Robocopy: exclui artefactos de lab / git / caches (não copia BD nem .env de desenvolvimento)
  $excludeDirs = @(
    ".git", ".cursor", "node_modules", ".venv", "venv", "__pycache__",
    "dist", "build", ".pytest_cache", "coverage", "agent-transcripts",
    "terminals", "assets"
  )
  $excludeFiles = @(
    ".env", "*.pyc", "*.db", "*.sqlite", "*.sql", "*.dump",
    "Thumbs.db", ".DS_Store"
  )
  $xd = @(); foreach ($d in $excludeDirs) { $xd += @("/XD", $d) }
  $xf = @(); foreach ($f in $excludeFiles) { $xf += @("/XF", $f) }
  & robocopy $Source $Dest /E /NFL /NDL /NJH /NJS /nc /ns /np @xd @xf | Out-Null
  # robocopy exit 0-7 = sucesso
  if ($LASTEXITCODE -ge 8) { throw "Robocopy falhou ($LASTEXITCODE) de $Source" }
  $global:LASTEXITCODE = 0
}

function Open-Firewall5173 {
  $name = "SentinelAI Web UI (5173)"
  $existing = Get-NetFirewallRule -DisplayName $name -ErrorAction SilentlyContinue
  if ($existing) {
    Write-Log "Firewall: regra já existe ($name)." "Yellow"
    return
  }
  New-NetFirewallRule `
    -DisplayName $name `
    -Direction Inbound `
    -Action Allow `
    -Protocol TCP `
    -LocalPort 5173 `
    -Profile Any `
    -Description "SentinelAI NMS — acesso UI na rede da empresa" | Out-Null
  Write-Log "Firewall: liberada TCP 5173 ($name)." "Green"
}

function Get-LanIPv4 {
  try {
    $ip = Get-NetIPAddress -AddressFamily IPv4 |
      Where-Object { $_.IPAddress -notlike "127.*" -and $_.PrefixOrigin -ne "WellKnown" } |
      Sort-Object InterfaceMetric |
      Select-Object -First 1 -ExpandProperty IPAddress
    if ($ip) { return $ip }
  } catch {}
  return "IP-DO-SERVIDOR"
}

