    <div class="coverage-grid">
      ${cov.pillars
        .map((p) => {
          const s = p.summary || {};
          return `<section class="coverage-col" data-pillar="${p.id}">
            <header>
              <div>
                <h3>${p.name}</h3>
                <span class="ok-pill">Contempla</span>
              </div>
              <p class="meta">${s.with_rules || 0}/${s.total || 0} com regra · hits ${s.alert_hits || 0}</p>
            </header>
            <ul>
              ${(p.items || [])
                .map(
                  (it) => `<li class="cov-item ${state.selectedCoverage === `${p.id}:${it.id}` ? "active" : ""}"
                    data-key="${p.id}:${it.id}">
                    <span class="cov-name">${it.name}</span>
                    <span class="cov-status ${statusClass(it.status)}">${it.status_label}</span>
                  </li>`
                )
                .join("")}
            </ul>
          </section>`;
        })
        .join("")}
    </div>
  `;

  pane.querySelectorAll(".cov-item").forEach((el) => {
    el.addEventListener("click", () => {
      state.selectedCoverage = el.dataset.key;
      renderCoverage();
      renderDetail();
    });
  });
}

function renderAudit() {
  const pane = $("listPane");
  const entries = state.audit?.entries || [];
  if (!entries.length) {
    pane.innerHTML = `<p class="empty-list">Sem entradas em ${state.audit?.source || "logs"}.</p>`;
    return;
  }
  pane.innerHTML = entries
    .map((e, i) => {
      const d = e.data || {};
      const title = e.raw
        ? (d.line || "").slice(0, 120)
        : d.rule_id || d.name || d.ts || `evento ${i + 1}`;
      const meta = e.raw
        ? "raw"
        : `${d.severity || d.pid || ""} ${d.process?.name || d.exe || ""}`.trim();
      return `<article class="alert-row ${state.selectedId === String(i) ? "active" : ""}" data-key="${i}">
