class ConsoleState:
    def __init__(self, paths: RuntimePaths) -> None:
        self.paths = paths
        self._lock = threading.Lock()
        self._monitor_stop = threading.Event()
        self._monitor_thread: threading.Thread | None = None
        self.monitor_running = False
        self.last_scan_alerts = 0
        self.last_error: str | None = None

    def read_alerts(self, limit: int = 200) -> list[dict[str, Any]]:
        path = self.paths.alerts
        if not path.exists():
            return []
        lines = path.read_text(encoding="utf-8").strip().splitlines()
        out: list[dict[str, Any]] = []
        for line in lines[-limit:]:
            try:
                out.append(json.loads(line))
            except json.JSONDecodeError:
                continue
        out.reverse()
        return out

    def scan_once(self, evaluate_all: bool = True) -> dict[str, Any]:
        with self._lock:
            try:
                runner = AgentRunner(
                    paths=self.paths,
                    evaluate_all=evaluate_all,
                    enforce=enforcement_active(self.paths.root),
                    quiet=True,
                )
                n = runner.pass_once()
                self.last_scan_alerts = n
                self.last_error = None
                return {"ok": True, "alerts": n}
            except Exception as exc:
                self.last_error = str(exc)
                return {"ok": False, "error": str(exc)}

    def start_monitor(self, interval: float = 3.0) -> dict[str, Any]:
        with self._lock:
            if self.monitor_running:
                return {"ok": True, "monitor_running": True}
            self._monitor_stop.clear()

            def loop() -> None:
                from eagle.zionxdr_control import monitor_evaluate_all

                runner = AgentRunner(
                    paths=self.paths,
                    interval=interval,
                    enforce=enforcement_active(self.paths.root),
                    evaluate_all=monitor_evaluate_all(self.paths.root),
                    stop_check=self._monitor_stop.is_set,
                    quiet=True,
                )
                self.monitor_running = True
                try:
                    runner.run_forever()
                except Exception as exc:
                    self.last_error = str(exc)
                finally:
                    self.monitor_running = False

            self._monitor_thread = threading.Thread(target=loop, name="eagle-monitor", daemon=True)
            self._monitor_thread.start()
            return {"ok": True, "monitor_running": True}

    def stop_monitor(self) -> dict[str, Any]:
        self._monitor_stop.set()
        thread = self._monitor_thread
        if thread and thread.is_alive():
            thread.join(timeout=5)
        self.monitor_running = False
        return {"ok": True, "monitor_running": False}

    def telemetry_status(self) -> dict[str, Any]:
        from eagle.telemetry_ops import telemetry_snapshot

        return telemetry_snapshot(self.paths.root)

    def etw_start(self) -> dict[str, Any]:
        from eagle.etw_sensor import etw_start

        return etw_start(self.paths.root)

    def etw_stop(self) -> dict[str, Any]:
        from eagle.etw_sensor import etw_stop

        return etw_stop(self.paths.root)

    def memory_scan(self) -> dict[str, Any]:
        from eagle.telemetry_ops import run_memory_scan

        with self._lock:
            try:
                result = run_memory_scan(self.paths)
                self.last_error = None
                return result
            except Exception as exc:
                self.last_error = str(exc)
                return {"ok": False, "error": str(exc)}

    def quarantine_list(self) -> list[str]:
        if not self.paths.quarantine.exists():
            return []
        return sorted(p.name for p in self.paths.quarantine.iterdir() if p.is_file())

    def rules_summary(self) -> list[dict[str, Any]]:
        if not self.paths.rules.exists():
            return []
        from eagle.engine import RuleEngine
        from eagle.risk import points_for_rule

        engine = RuleEngine(self.paths.rules)
        out: list[dict[str, Any]] = []
        for r in engine.rules:
            out.append(
                {
                    "id": r.get("id"),
                    "name": r.get("name"),
                    "severity": r.get("severity"),
                    "action": r.get("action"),
                    "mitre_tactic": r.get("mitre_tactic"),
                    "mitre_technique": r.get("mitre_technique"),
                    "category": r.get("category"),
                    "description": r.get("description"),
                    "risk_points": points_for_rule(r),
                }
            )
        return out

    def stats(self) -> dict[str, Any]:
        alerts = self.read_alerts(limit=5000)
        by_sev = Counter((a.get("severity") or "unknown").lower() for a in alerts)
        rules = len(self.rules_summary())
        quar = 0
        if self.paths.quarantine.exists():
            quar = sum(1 for p in self.paths.quarantine.iterdir() if p.is_file())
        telem = self.telemetry_status()
        chains = sum(1 for a in alerts if (a.get("category") == "correlation") or str(a.get("rule_id", "")).startswith("BEHAVIOR-"))
        incidents = 0
        try:
            from eagle.incident_engine import IncidentEngine

            incidents = len(IncidentEngine(self.paths.incidents).recent(limit=500))
        except Exception:
            inc_path = getattr(self.paths, "incidents", None)
            if inc_path and Path(inc_path).exists():
                incidents = len(Path(inc_path).read_text(encoding="utf-8").strip().splitlines())
        return {
            "total_alerts": len(alerts),
            "by_severity": dict(by_sev),
            "rules": rules,
            "quarantine_files": quar,
            "monitor_running": self.monitor_running,
            "last_scan_alerts": self.last_scan_alerts,
            "last_error": self.last_error,
            "alerts_path": str(self.paths.alerts),
            "telemetry": telem,
            "behavior_chains": chains,
            "incidents": incidents,
        }

    def incidents_summary(self, limit: int = 50) -> list[dict[str, Any]]:
        try:
            from eagle.incident_engine import IncidentEngine

            return IncidentEngine(getattr(self.paths, "incidents", self.paths.logs / "incidents.jsonl")).recent(limit=limit)
        except Exception:
            return []




