"""Correlação multi-regra — cadeias comportamentais (EDR-like)."""

from __future__ import annotations

from collections import deque
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import yaml

from eagle.models import Alert, ProcessEvent, utc_now_iso
from eagle.risk import points_for_rule


def _parse_ts(ts: str | None) -> float:
    if not ts:
        return datetime.now(timezone.utc).timestamp()
    try:
        return datetime.fromisoformat(ts.replace("Z", "+00:00")).timestamp()
    except ValueError:
        return datetime.now(timezone.utc).timestamp()


@dataclass
class _Hit:
    rule_id: str
    ts: float
    process: ProcessEvent


@dataclass
class CorrelationEngine:
    config_path: Path
    window_sec: float = 120.0
    chains: list[dict[str, Any]] = field(default_factory=list)
    _hits: deque[_Hit] = field(default_factory=lambda: deque(maxlen=500))
    _fired: set[str] = field(default_factory=set)

    def reload(self) -> None:
        if not self.config_path.exists():
            self.chains = []
            return
        data = yaml.safe_load(self.config_path.read_text(encoding="utf-8")) or {}
        self.window_sec = float(data.get("window_sec") or 120)
        self.chains = list(data.get("chains") or [])

    def observe(self, alert: Alert) -> Alert | None:
        """Regista alerta e, se uma cadeia fechar, devolve incidente correlacionado."""
        now = _parse_ts(alert.ts)
        self._hits.append(_Hit(rule_id=alert.rule_id, ts=now, process=alert.process))
        self._prune(now)
        for chain in self.chains:
            incident = self._try_chain(chain, now)
            if incident:
                return incident
        return None

    def _prune(self, now: float) -> None:
        while self._hits and now - self._hits[0].ts > self.window_sec:
            self._hits.popleft()
        # limpar fired antigos (chave inclui minuto)
        stale = [k for k in self._fired if not k.endswith(str(int(now // 60)))]
        for k in stale:
            self._fired.discard(k)

    def _try_chain(self, chain: dict[str, Any], now: float) -> Alert | None:
        stages = chain.get("any_of_stages") or []
        if not stages:
            return None
        matched_rules: list[str] = []
        last_proc: ProcessEvent | None = None
        for stage in stages:
            wanted = {str(x) for x in stage}
            found = None
            for hit in self._hits:
                if hit.rule_id in wanted:
                    found = hit
                    break
            if not found:
                return None
            matched_rules.append(found.rule_id)
            last_proc = found.process

        chain_id = str(chain.get("id", "BEHAVIOR-UNKNOWN"))
        fire_key = f"{chain_id}:{int(now // 60)}"
        if fire_key in self._fired:
            return None
        self._fired.add(fire_key)

        proc = last_proc or ProcessEvent(
            pid=0, ppid=0, name="correlation", exe=None, cmdline="", username=None, create_time=now
        )
        pts = int(chain.get("risk_points") or 100)
        return Alert(
            rule_id=chain_id,
            rule_name=str(chain.get("name", chain_id)),
            severity=str(chain.get("severity", "critical")),
            action="alert",
            process=proc,
            detail=(
                f"Attack chain · stages={len(stages)} · matched={','.join(matched_rules)} · "
                f"{chain.get('description') or ''}"
            ),
            ts=utc_now_iso(),
            mitre_tactic=chain.get("mitre_tactic"),
            mitre_technique=chain.get("mitre_technique"),
            category="correlation",
            risk_score=min(100, pts),
            risk_points=pts,
            confidence=92,
            correlation_id=chain_id,
            correlated_rules=matched_rules,
            description=str(chain.get("description") or ""),
        )


def load_correlation_engine(path: Path) -> CorrelationEngine:
    eng = CorrelationEngine(config_path=path)
    eng.reload()
    return eng

from __future__ import annotations

import re
from collections import defaultdict

from eagle.models import ProcessEvent
from eagle.sensor import Sensor

_IP_RE = re.compile(r"\b(?:(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\b")
_URL_RE = re.compile(r"https?://[^\s\"']+", re.I)
_UNUSUAL_PORTS = {4444, 5555, 6666, 1337, 31337, 8081, 8443, 9001, 4443}


class Correlator:
    """Enriquece eventos com tags comportamentais (aditivo — mass write, office, download, C2 hints)."""

    def __init__(self, sensor: Sensor) -> None:
        self.sensor = sensor
        self._ext_ips_seen: set[str] = set()
        self._connect_ts: dict[str, list[float]] = defaultdict(list)

    def enrich(self, events: list[ProcessEvent]) -> list[ProcessEvent]:
        mass = self.sensor.mass_write_pids()
        multi = getattr(self.sensor, "multi_directory_pids", lambda: set())()
        entropy = getattr(self.sensor, "high_entropy_pids", lambda: set())()
        net_hints = getattr(self.sensor, "network_hints", lambda: {})()

        for event in events:
            tags = set(event.tags)
            if event.pid in mass:
                tags.add("mass_file_write")
                tags.add("mass_rename")
            if event.pid in multi:
                tags.add("multi_directory_write")
            if event.pid in entropy:
                tags.add("high_entropy_write")

            if event.parent_name in {
                "winword.exe",
                "excel.exe",
                "powerpnt.exe",
                "outlook.exe",
            } and event.name in {
                "cmd.exe",
                "powershell.exe",
                "pwsh.exe",
                "wscript.exe",
                "cscript.exe",
                "mshta.exe",
            }:
                tags.add("office_child_shell")

            cmdline = (event.cmdline or "").lower()
            name = (event.name or "").lower()
            exe = (event.exe or "").strip()

            if not exe:
                tags.add("no_image_path")

            if name in {"curl.exe", "certutil.exe", "bitsadmin.exe"} and (
                "http://" in cmdline or "https://" in cmdline
            ):
                tags.add("download_execute_chain")
            if name in {"powershell.exe", "pwsh.exe"} and any(
                x in cmdline for x in ("downloadstring", "downloadfile", "invoke-webrequest", "wget ")
            ):
                tags.add("download_execute_chain")
            if "\\temp\\" in exe.lower() and name.endswith(".exe"):
                tags.add("download_execute_chain")

            # C2 / network heuristics from cmdline
            urls = _URL_RE.findall(event.cmdline or "")
            ips = _IP_RE.findall(event.cmdline or "")
            for ip in ips:
                if ip.startswith(("10.", "192.168.", "127.")) or ip.startswith("172."):
                    continue
                if ip not in self._ext_ips_seen:
                    tags.add("new_external_ip")
                    self._ext_ips_seen.add(ip)
            if urls and any(x in name for x in ("powershell", "pwsh", "curl", "certutil", "bitsadmin", "mshta")):
                tags.add("rare_domain")
                tags.add("external_beacon")

            # porta incomum na cmdline
            for m in re.finditer(r":(\d{2,5})\b", event.cmdline or ""):
                try:
                    port = int(m.group(1))
                except ValueError:
                    continue
                if port in _UNUSUAL_PORTS or (port > 1024 and port not in {8080, 8443, 3389, 443, 80}):
                    if port in _UNUSUAL_PORTS:
                        tags.add("unusual_port")

            # DNS entropy / tunnel hints
            if any(x in cmdline for x in ("dnscat", "iodine", "dns-tunnel")):
                tags.add("dns_high_entropy")
            if name in {"nslookup.exe", "dig.exe"} and len(cmdline) > 80:
                tags.add("dns_burst")
                tags.add("dns_high_entropy")

            if name == "mstsc.exe" or "3389" in cmdline:
                tags.add("rdp_scan")

            # net hints from sensor (pid → flags)
            flags = net_hints.get(event.pid) or set()
            tags |= set(flags)

            # preparação ransomware: mass write + evade cmdline no mesmo processo
            if "mass_file_write" in tags and any(
                x in cmdline for x in ("vssadmin", "wbadmin", "bcdedit", "delete shadows", "exclusion")
            ):
                tags.add("ransom_preparation")

            event.tags = sorted(tags)
        return events

from __future__ import annotations

from collections import Counter
from pathlib import Path
from typing import Any

import yaml


STATUS_LABEL = {
    "endpoint": "Endpoint (ativo)",
    "partial": "Parcial (endpoint)",
    "planned": "Planejado (rede/SIEM)",
    "siem": "SIEM local (ativo)",
}


def load_coverage(path: Path) -> dict[str, Any]:
    data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    return data


def enrich_coverage(
    coverage: dict[str, Any],
    known_rule_ids: set[str],
    alert_rule_counts: Counter[str] | None = None,
) -> dict[str, Any]:
    alert_rule_counts = alert_rule_counts or Counter()
    pillars_out: list[dict[str, Any]] = []

    for pillar in coverage.get("pillars") or []:
        items_out: list[dict[str, Any]] = []
        counts = Counter()
        for item in pillar.get("items") or []:
            rules = list(item.get("rules") or [])
            linked = [r for r in rules if r in known_rule_ids]
            missing = [r for r in rules if r not in known_rule_ids]
            hits = sum(alert_rule_counts.get(r, 0) for r in linked)
            status = item.get("status", "planned")
            counts[status] += 1
            items_out.append(
                {
                    "id": item.get("id"),
                    "name": item.get("name"),
                    "mitre": item.get("mitre"),
                    "status": status,
                    "status_label": STATUS_LABEL.get(status, status),
                    "contempla": True,
                    "rules": linked,
                    "rules_missing": missing,
                    "alert_hits": hits,
                    "sources": item.get("sources") or [],
                }
            )

        pillars_out.append(
            {
                "id": pillar.get("id"),
                "name": pillar.get("name"),
                "contempla": bool(pillar.get("contempla", True)),
                "items": items_out,
                "summary": {
                    "total": len(items_out),
                    "by_status": dict(counts),
                    "with_rules": sum(1 for i in items_out if i["rules"]),
                    "alert_hits": sum(i["alert_hits"] for i in items_out),
                },
            }
        )

    return {
        "title": coverage.get("title", "Monitoramento contratado"),
        "note": (coverage.get("note") or "").strip(),
        "pillars": pillars_out,
    }


def read_recent_log_lines(path: Path, limit: int = 100) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    lines = path.read_text(encoding="utf-8", errors="replace").strip().splitlines()
    out: list[dict[str, Any]] = []
    for line in lines[-limit:]:
        line = line.strip()
        if not line:
            continue
        try:
            import json

            out.append({"raw": False, "data": json.loads(line)})
        except Exception:
            out.append({"raw": True, "data": {"line": line[:2000]}})
    out.reverse()
    return out

from __future__ import annotations

import re
from pathlib import Path
from typing import Any

import yaml

from eagle.models import Alert, ProcessEvent
from eagle.risk import band_from_score, confidence_for_alert, points_for_rule
from eagle.whitelist import Whitelist


class RuleEngine:
    def __init__(self, rules_path: Path, whitelist: Whitelist | None = None) -> None:
        self.rules_path = rules_path
        self.whitelist = whitelist
        self.rules: list[dict[str, Any]] = []
        self._regex_cache: dict[str, re.Pattern[str]] = {}
        self.reload()

    def reload(self) -> None:
        merged: list[dict[str, Any]] = []
        seen: set[str] = set()

        def _ingest(path: Path) -> None:
            if not path.is_file():
                return
            data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
            for rule in data.get("rules") or []:
                rid = str(rule.get("id") or "")
                if not rid or rid in seen:
                    continue
                seen.add(rid)
                merged.append(rule)

        _ingest(self.rules_path)
        rules_d = self.rules_path.parent / "rules.d"
        if rules_d.is_dir():
            for extra in sorted(rules_d.glob("*.yaml")) + sorted(rules_d.glob("*.yml")):
                _ingest(extra)

        self.rules = merged
        self._regex_cache.clear()
        if self.whitelist:
            self.whitelist.reload()

    def evaluate(self, event: ProcessEvent) -> list[Alert]:
        alerts: list[Alert] = []
        for rule in self.rules:
            if not self._matches(event, rule.get("match") or {}):
                continue
            rid = str(rule.get("id", "UNKNOWN"))
            if self.whitelist and self.whitelist.suppresses(rid, event):
                continue
            pts = points_for_rule(rule)
            score = min(100, pts)
            alerts.append(
                Alert(
                    rule_id=rid,
                    rule_name=str(rule.get("name", rid)),
                    severity=str(rule.get("severity") or band_from_score(score)),
                    action=str(rule.get("action", "alert")),
                    process=event,
                    detail=self._detail(event, rule),
                    mitre_tactic=rule.get("mitre_tactic"),
                    mitre_technique=rule.get("mitre_technique"),
                    category=rule.get("category"),
                    description=rule.get("description"),
                    risk_score=score,
                    risk_points=pts,
                    confidence=confidence_for_alert(rule, event.tags),
                )
            )
        return alerts

    def _compile(self, pattern: str) -> re.Pattern[str] | None:
        cached = self._regex_cache.get(pattern)
        if cached is not None:
            return cached
        try:
            compiled = re.compile(pattern)
        except re.error:
            return None
        self._regex_cache[pattern] = compiled
        return compiled

    def _matches(self, event: ProcessEvent, match: dict[str, Any]) -> bool:
        name = (event.name or "").lower()
        parent = (event.parent_name or "").lower()
        cmdline = (event.cmdline or "").lower()
        cmdline_raw = event.cmdline or ""
        exe = (event.exe or "").lower()
        tags = set(event.tags or [])

        if "process_name_in" in match:
            allowed = {x.lower() for x in match["process_name_in"]}
            if name not in allowed:
                return False

        if "process_name_not_in" in match:
            denied = {x.lower() for x in match["process_name_not_in"]}
            if name in denied:
                return False

        if "parent_name_in" in match:
            allowed = {x.lower() for x in match["parent_name_in"]}
            if parent not in allowed:
                return False

        if "parent_name_not_in" in match:
            denied = {x.lower() for x in match["parent_name_not_in"]}
            if parent in denied:
                return False

        if "cmdline_contains_any" in match:
            needles = [x.lower() for x in match["cmdline_contains_any"]]
            if not any(n in cmdline for n in needles):
                return False

        if "cmdline_contains_all" in match:
            needles = [x.lower() for x in match["cmdline_contains_all"]]
            if not all(n in cmdline for n in needles):
                return False

        if "cmdline_regex" in match:
            pat = self._compile(str(match["cmdline_regex"]))
            if not pat or not pat.search(cmdline_raw):
                return False

        if "cmdline_regex_any" in match:
            ok = False
            for raw in match["cmdline_regex_any"] or []:
                pat = self._compile(str(raw))
                if pat and pat.search(cmdline_raw):
                    ok = True
                    break
            if not ok:
                return False

        if "path_contains_any" in match:
            needles = [x.lower() for x in match["path_contains_any"]]
            hay = exe or ""
            if not any(n in hay for n in needles):
                return False

        if "path_not_contains_any" in match:
            needles = [x.lower() for x in match["path_not_contains_any"]]
            hay = exe or ""
            if any(n in hay for n in needles):
                return False

        if "process_name_endswith" in match:
            suffixes = [x.lower() for x in match["process_name_endswith"]]
            if not any(name.endswith(s) for s in suffixes):
                return False

        if "tags_any" in match:
            wanted = set(match["tags_any"])
            if tags.isdisjoint(wanted):
                return False

        return True

    def _detail(self, event: ProcessEvent, rule: dict[str, Any]) -> str:
        return (
            f"rule={rule.get('id')} pid={event.pid} name={event.name} "
            f"parent={event.parent_name} exe={event.exe}"
        )

