"""Coleta de evidências no host Eagle (job HITL)."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from eagle.runner import RuntimePaths
from eagle.zionxdr_control import read_control


def _fingerprint(alert: dict[str, Any]) -> str:
    import hashlib

    p = alert.get("process") or {}
    raw = "|".join(
        [
            str(alert.get("ts") or ""),
            str(alert.get("rule_id") or ""),
            str(p.get("pid") or ""),
            str(p.get("name") or ""),
        ]
    )
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:64]


def collect_evidence(paths: RuntimePaths, fingerprint: str) -> dict[str, Any]:
    alert_match: dict[str, Any] | None = None
    if paths.alerts.is_file():
        for line in paths.alerts.read_text(encoding="utf-8").splitlines()[-500:]:
            line = line.strip()
            if not line:
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError:
                continue
            if _fingerprint(row) == fingerprint:
                alert_match = row
                break

    quarantine_files: list[str] = []
    if paths.quarantine.is_dir():
        quarantine_files = sorted(p.name for p in paths.quarantine.iterdir() if p.is_file())[:100]

    return {
        "ok": True,
        "fingerprint": fingerprint,
        "alert": alert_match,
        "quarantine_files": quarantine_files,
        "control": read_control(paths.root),
        "rules_path": str(paths.rules),
    }

"""
Heurísticas leves de memória — protótipo.

Em produção: APIs nativas (ReadProcessMemory, VirtualQueryEx), ETW,
e drivers assinados. Aqui usamos apenas metadados acessíveis via psutil
para não introduzir código ofensivo nem PoCs de exploit.
"""

from __future__ import annotations

import psutil

from eagle.models import ProcessEvent


def annotate_memory_hints(events: list[ProcessEvent], sample_limit: int = 40) -> list[ProcessEvent]:
    """
    Marca processos com indicadores indiretos:
    - muitos threads + sem exe resolvido (possível reflective / hollowed)
    - memória RSS muito alta vs. peers do mesmo nome (outlier grosseiro)
    """
    skip_names = {"system", "idle", "registry", "memory compression", "system interrupts"}
    by_name: dict[str, list[tuple[int, int]]] = {}
    meta: dict[int, dict] = {}

    for i, event in enumerate(events):
        if i >= sample_limit:
            break
        if event.pid < 8 or (event.name or "").lower() in skip_names:
            continue
        try:
            p = psutil.Process(event.pid)
            with p.oneshot():
                mem = p.memory_info().rss
                threads = p.num_threads()
                exe = p.exe()
            meta[event.pid] = {"rss": mem, "threads": threads, "exe": exe}
            by_name.setdefault(event.name, []).append((event.pid, mem))
        except (psutil.Error, OSError):
            continue

    averages: dict[str, float] = {}
    for name, pairs in by_name.items():
        if not pairs:
            continue
        averages[name] = sum(m for _, m in pairs) / len(pairs)

    for event in events:
        if event.pid < 8 or (event.name or "").lower() in skip_names:
            continue
        info = meta.get(event.pid)
        if not info:
            continue
        tags = set(event.tags)
        exe = info.get("exe") or event.exe
        if not exe and info.get("threads", 0) >= 8:
            tags.add("memory_rwx")  # label de heurística (não prova RWX real)
        avg = averages.get(event.name)
        if avg and avg > 0 and info["rss"] > avg * 8 and info["rss"] > 200 * 1024 * 1024:
            tags.add("memory_rwx")
        event.tags = sorted(tags)

    return events

from __future__ import annotations

import json
import shutil
from pathlib import Path

import psutil

from eagle.models import Alert


class Responder:
    def __init__(
        self,
        quarantine_dir: Path,
        alerts_log: Path,
        enforce: bool = False,
    ) -> None:
        self.quarantine_dir = quarantine_dir
        self.alerts_log = alerts_log
        self.enforce = enforce
        self.quarantine_dir.mkdir(parents=True, exist_ok=True)
        self.alerts_log.parent.mkdir(parents=True, exist_ok=True)

    def handle(self, alert: Alert) -> None:
        self._append_alert(alert)
        action = (alert.action or "alert").lower()

        if action in {"monitor", "alert"}:
            return

        if not self.enforce:
            return

        if action in {"kill", "block", "quarantine"}:
            self._kill(alert.process.pid)

        if action == "quarantine" and alert.process.exe:
            self._quarantine_file(alert.process.exe)

    def _append_alert(self, alert: Alert) -> None:
        with self.alerts_log.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(alert.to_dict(), ensure_ascii=False) + "\n")

    def _kill(self, pid: int) -> None:
        try:
            p = psutil.Process(pid)
            p.terminate()
        except (psutil.Error, OSError):
            return

    def _quarantine_file(self, path: str) -> None:
        src = Path(path)
        if not src.is_file():
            return
        dest = self.quarantine_dir / f"{src.stem}_{src.stat().st_mtime_ns}{src.suffix}.quarantine"
        try:
            shutil.move(str(src), str(dest))
        except OSError:
            return

"""Risk score dinâmico Eagle — Evento → pontos → banda de severidade."""

from __future__ import annotations

from typing import Any


# Pontos por severidade base (quando a regra não define risk_points)
SEVERITY_POINTS = {
    "info": 5,
    "low": 10,
    "medium": 20,
    "high": 30,
    "critical": 45,
}


def band_from_score(score: int) -> str:
    if score >= 81:
        return "critical"
    if score >= 61:
        return "high"
    if score >= 31:
        return "medium"
    return "low"


def points_for_rule(rule: dict[str, Any]) -> int:
    raw = rule.get("risk_points")
    if isinstance(raw, (int, float)):
        return max(0, min(100, int(raw)))
    sev = str(rule.get("severity") or "medium").lower()
    return SEVERITY_POINTS.get(sev, 20)


def score_alerts(rule_hits: list[dict[str, Any]], chain_bonus: int = 0) -> dict[str, Any]:
    """Soma pontos de alertas recentes + bónus de cadeia comportamental."""
    total = 0
    breakdown: list[dict[str, Any]] = []
    for hit in rule_hits:
        pts = int(hit.get("risk_points") or points_for_rule(hit))
        total += pts
        breakdown.append({"rule_id": hit.get("id") or hit.get("rule_id"), "points": pts})
    total = min(100, total + max(0, chain_bonus))
    return {
        "risk_score": total,
        "severity_band": band_from_score(total),
        "breakdown": breakdown,
        "chain_bonus": chain_bonus,
    }


def confidence_for_alert(rule: dict[str, Any], event_tags: list[str] | None = None) -> int:
    """0–100: sobe com MITRE, parent match implícito e tags comportamentais."""
    base = 55
    if rule.get("mitre_technique"):
        base += 10
    if rule.get("mitre_tactic"):
        base += 5
    match = rule.get("match") or {}
    if "parent_name_in" in match:
        base += 12
    if "cmdline_contains_any" in match or "cmdline_contains_all" in match:
        base += 8
    tags = set(event_tags or [])
    if tags & {"office_child_shell", "mass_file_write", "download_execute_chain"}:
        base += 10
    return max(0, min(100, base))

from __future__ import annotations

import time
from collections import defaultdict
from typing import Iterable

import psutil

from eagle.models import ProcessEvent


class Sensor:
    """Coleta telemetria de processos (polling). Produção usaria ETW/callbacks."""

    def __init__(self) -> None:
        self._seen: dict[int, float] = {}
        self._name_by_pid: dict[int, str] = {}
        self._write_hints: dict[int, int] = defaultdict(int)
        self._dir_hints: dict[int, set[str]] = defaultdict(set)
        self._entropy_hints: dict[int, int] = defaultdict(int)
        self._net_flags: dict[int, set[str]] = defaultdict(set)

    def snapshot_processes(self) -> list[ProcessEvent]:
        events: list[ProcessEvent] = []
        current_pids: set[int] = set()

        for proc in psutil.process_iter(
            ["pid", "ppid", "name", "exe", "cmdline", "username", "create_time"]
        ):
            try:
                info = proc.info
                pid = info["pid"]
                current_pids.add(pid)
                name = (info.get("name") or "").lower()
                self._name_by_pid[pid] = name

                cmdline_list = info.get("cmdline") or []
                cmdline = " ".join(cmdline_list) if cmdline_list else ""
                parent_name = self._name_by_pid.get(info.get("ppid") or -1)

                event = ProcessEvent(
                    pid=pid,
                    ppid=info.get("ppid") or 0,
                    name=name,
                    exe=info.get("exe"),
                    cmdline=cmdline,
                    username=info.get("username"),
                    create_time=info.get("create_time") or 0.0,
                    parent_name=parent_name,
                )
                events.append(event)
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                continue

        # Enrich network hints (best-effort; pode falhar sem privilégios)
        try:
            for c in psutil.net_connections(kind="inet"):
                if not c.pid:
                    continue
                if c.status != "ESTABLISHED" or not c.raddr:
                    continue
                rip = getattr(c.raddr, "ip", None) or (c.raddr[0] if c.raddr else None)
                rport = getattr(c.raddr, "port", None) or (c.raddr[1] if c.raddr and len(c.raddr) > 1 else None)
                if not rip:
                    continue
                if rip.startswith(("10.", "127.", "192.168.")) or rip.startswith("172."):
                    continue
                flags = self._net_flags[c.pid]
                flags.add("external_beacon")
                if rport in {4444, 5555, 6666, 1337, 31337, 9001}:
                    flags.add("unusual_port")
                    flags.add("periodic_beacon")
                    flags.add("beacon_low_volume")
                flags.add("new_external_ip")
        except (psutil.AccessDenied, PermissionError, OSError):
            pass

        stale = [pid for pid in self._seen if pid not in current_pids]
        for pid in stale:
            self._seen.pop(pid, None)
            self._write_hints.pop(pid, None)
            self._dir_hints.pop(pid, None)
            self._entropy_hints.pop(pid, None)
            self._net_flags.pop(pid, None)

        return events

    def new_or_updated(self, events: Iterable[ProcessEvent]) -> list[ProcessEvent]:
        fresh: list[ProcessEvent] = []
        for event in events:
            prev = self._seen.get(event.pid)
            if prev is None or abs(prev - event.create_time) > 0.01:
                self._seen[event.pid] = event.create_time
                fresh.append(event)
        return fresh

    def note_file_write_activity(self, pid: int, count: int = 1, directory: str | None = None, entropy: bool = False) -> None:
        """Gancho para futuros hooks de filesystem; prototype usa incremento manual/teste."""
        self._write_hints[pid] += count
        if directory:
            self._dir_hints[pid].add(directory.lower())
        if entropy:
            self._entropy_hints[pid] += 1

    def mass_write_pids(self, threshold: int = 50) -> set[int]:
        return {pid for pid, n in self._write_hints.items() if n >= threshold}

    def multi_directory_pids(self, min_dirs: int = 3) -> set[int]:
        return {pid for pid, dirs in self._dir_hints.items() if len(dirs) >= min_dirs}

    def high_entropy_pids(self, threshold: int = 20) -> set[int]:
        return {pid for pid, n in self._entropy_hints.items() if n >= threshold}

    def network_hints(self) -> dict[int, set[str]]:
        return {pid: set(flags) for pid, flags in self._net_flags.items()}



def sleep_interval(seconds: float) -> None:
    time.sleep(max(0.5, seconds))

"""Allowlist / reputação interna — silencia regras em contexto confiado."""

from __future__ import annotations

from pathlib import Path
from typing import Any

import yaml

from eagle.models import ProcessEvent


class Whitelist:
    def __init__(self, path: Path) -> None:
        self.path = path
        self.enabled = True
        self.trusted_users: list[str] = []
        self.trusted_hosts: list[str] = []
        self.trusted_paths: list[str] = []
        self.allow_rules: list[dict[str, Any]] = []
        self.reload()

    def reload(self) -> None:
        if not self.path.exists():
            self.enabled = False
            return
        data = yaml.safe_load(self.path.read_text(encoding="utf-8")) or {}
        self.enabled = bool(data.get("enabled", True))
        self.trusted_users = [str(x).lower() for x in (data.get("trusted_users") or [])]
        self.trusted_hosts = [str(x).lower() for x in (data.get("trusted_hosts") or [])]
        self.trusted_paths = [str(x).lower() for x in (data.get("trusted_paths") or [])]
        self.allow_rules = list(data.get("allow_rules") or [])

    def suppresses(self, rule_id: str, event: ProcessEvent) -> bool:
        if not self.enabled:
            return False
        user = (event.username or "").lower()
        exe = (event.exe or "").lower()
        name = (event.name or "").lower()
        cmdline = (event.cmdline or "").lower()

        if self.trusted_users and any(u in user for u in self.trusted_users):
            # TI confiado ainda gera alertas critical de ransomware/credenciais
            if not str(rule_id).upper().startswith(("RANSOM-", "CRED-", "BEHAVIOR-")):
                if any(p in exe for p in self.trusted_paths) or not self.trusted_paths:
                    return True

        if self.trusted_paths and any(p in exe for p in self.trusted_paths):
            for ar in self.allow_rules:
                if str(ar.get("id")) != rule_id:
                    continue
                procs = {x.lower() for x in (ar.get("process_name_in") or [])}
                if procs and name not in procs:
                    continue
                needles = [x.lower() for x in (ar.get("cmdline_contains_any") or [])]
                if needles and any(n in cmdline for n in needles):
                    return True

        for ar in self.allow_rules:
            if str(ar.get("id")) != rule_id:
                continue
            procs = {x.lower() for x in (ar.get("process_name_in") or [])}
            if procs and name not in procs:
                continue
            needles = [x.lower() for x in (ar.get("cmdline_contains_any") or [])]
            if needles and any(n in cmdline for n in needles):
                return True
        return False

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def control_file(root: Path) -> Path:
    return root / "zionxdr_control.json"


def read_control(root: Path) -> dict[str, Any]:
    path = control_file(root)
    if not path.is_file():
        return {"enforcement_mode": "monitor"}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return {"enforcement_mode": "monitor"}


def write_control(root: Path, **fields: Any) -> dict[str, Any]:
    data = read_control(root)
    data.update({k: v for k, v in fields.items() if v is not None})
    path = control_file(root)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2), encoding="utf-8")
    return data


def enforcement_active(root: Path) -> bool:
    mode = str(read_control(root).get("enforcement_mode") or "monitor").lower()
    return mode == "enforce"


def monitor_evaluate_all(root: Path) -> bool:
    """Modo detect — avalia todos os processos a cada passagem."""
    mode = str(read_control(root).get("enforcement_mode") or "monitor").lower()
    return mode == "detect"

const layers = document.querySelectorAll(".layers li");

const io = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        const items = [...layers];
        items.forEach((el, i) => {
          window.setTimeout(() => el.classList.add("in"), i * 90);
        });
        io.disconnect();
      }
    });
  },
  { threshold: 0.2 }
);

if (layers.length) {
  io.observe(layers[0].parentElement);
}

